export default "<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>ハンコ工房 ― 石を彫って、上司にお辞儀して押す</title>\n<meta name=\"description\" content=\"鹿児島の小さな印房で、頑固な親方・源じいに教わりながら石の印鑑を筆の下書きから彫る3D体験。彫ったハンコは稟議書の担当欄に、上司へお辞儀するように傾けて押す。親方の採点と印相鑑定書つき。\">\n<meta name=\"theme-color\" content=\"#1a120d\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:title\" content=\"ハンコ工房 ― 石を彫って、上司にお辞儀して押す\">\n<meta property=\"og:description\" content=\"頑固な親方に教わって石の印鑑を彫り、稟議書の担当欄に「上司へお辞儀したハンコ」を押す。親方の採点と印相鑑定つき。\">\n<meta property=\"og:image\" content=\"/ogp.png\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect x='6' y='6' width='52' height='52' rx='6' fill='none' stroke='%23C83228' stroke-width='6'/%3E%3Ctext x='32' y='45' font-size='34' text-anchor='middle' fill='%23C83228' font-family='serif' font-weight='700'%3E%E5%8D%B0%3C/text%3E%3C/svg%3E\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Shippori+Mincho+B1:wght@400;500;600;700;800&family=Yuji+Syuku&family=Zen+Kaku+Gothic+New:wght@400;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  /* 夜の篆刻工房。焦げ茶〜黒檀の作業台に手元灯、和紙と朱と墨だけで組む。 */\n  --wood:#1a120d;          /* 使い込まれた作業台 */\n  --wood-2:#2a1c13;\n  --wood-3:#3b2819;\n  --washi:#F7F4EB;         /* 生成りの和紙 */\n  --washi-2:#E6DDCB;\n  --shu:#C83228;           /* 朱肉 */\n  --shu-deep:#8E2219;\n  --sumi:#1C1C1C;          /* 墨 */\n  --sumi-2:#4a423b;\n  --muted:#6f6458;\n  --brass:#A8843E;\n  --f-mincho:\"Shippori Mincho B1\",\"Hiragino Mincho ProN\",\"Yu Mincho\",\"Noto Serif JP\",serif;\n  --f-brush:\"Yuji Syuku\",\"Shippori Mincho B1\",\"Hiragino Mincho ProN\",serif;\n  --f-display:var(--f-brush);\n  --f-body:var(--f-mincho);\n  --f-seal:\"Shippori Mincho B1\",\"Hiragino Mincho ProN\",\"Yu Mincho\",serif;\n  /* 旧変数（既存の部品向け） */\n  --desk:var(--wood); --ink:var(--sumi); --kin:var(--brass); --washi-old:var(--washi);\n  color-scheme: dark;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0}\nbody{background:var(--wood);color:var(--washi);font-family:var(--f-mincho);line-height:1.75;-webkit-font-smoothing:antialiased;font-feature-settings:\"palt\"}\nbutton,input,select{font:inherit;color:inherit}\n:focus-visible{outline:2px solid var(--brass);outline-offset:2px}\n\n/* 木の質感（板目）。ボタンや札に使う */\n.woodgrain,header.top,nav.steps button,.sound,.nameplate{background-color:var(--wood-3);background-image:repeating-linear-gradient(90deg,rgba(0,0,0,.18) 0 1px,transparent 1px 7px),repeating-linear-gradient(90deg,rgba(255,220,170,.04) 0 2px,transparent 2px 19px)}\n\nheader.top{display:flex;flex-wrap:nowrap;align-items:center;gap:10px 24px;padding:0 max(16px,3vw);height:62px;box-sizing:border-box;color:var(--washi);background-color:#130d09;border-bottom:1px solid #000;box-shadow:inset 0 -1px 0 rgba(168,132,62,.25)}\n.brand{display:flex;align-items:center;gap:14px}\n.brand .mark{width:38px;height:38px;border:2px solid var(--shu);display:grid;place-items:center;color:var(--shu);font-family:var(--f-seal);font-weight:800;font-size:22px;transform:rotate(-6deg);background:rgba(200,50,40,.06)}\n.brand h1{font-family:var(--f-mincho);font-weight:700;font-size:23px;margin:0;letter-spacing:.32em;line-height:1.2}\n.brand p{margin:0;font-size:11px;color:#a8998a;letter-spacing:.18em}\nnav.steps{display:flex;gap:10px;margin-left:auto;flex-wrap:wrap}\nnav.steps button{position:relative;font-size:14px;color:#e8dcc6;border:1px solid #5a3c24;border-radius:0;padding:6px 16px 6px 12px;display:flex;align-items:center;gap:10px;cursor:pointer;letter-spacing:.2em;font-family:var(--f-mincho);font-weight:600}\nnav.steps button::before{content:\"\";position:absolute;left:50%;top:-5px;width:5px;height:5px;margin-left:-2.5px;border-radius:50%;background:#0d0906;box-shadow:0 0 0 1px #6b4a2e}\nnav.steps button:hover{filter:brightness(1.15)}\nnav.steps .no{width:24px;height:24px;border:1px solid rgba(232,220,198,.55);display:grid;place-items:center;font-size:12px;letter-spacing:0}\nnav.steps button[aria-current=\"step\"] .no{background:var(--shu);border-color:var(--shu);color:var(--washi);transform:rotate(-8deg);box-shadow:0 0 0 2px rgba(200,50,40,.25)}\nnav.steps button[aria-current=\"step\"]{color:#fff;border-color:#8a5a34}\n.sound{margin-left:auto;border:1px solid #5a3c24;color:#e8dcc6;border-radius:0;padding:5px 12px;font-size:13px;cursor:pointer;letter-spacing:.1em}\n\nmain{max-width:1280px;margin:0 auto;padding:0 max(12px,2.5vw) 120px}\nmain:has(>.step[data-step=\"1\"]:not([hidden])){padding-bottom:0}\nhtml,body{overflow-x:clip} /* 100vw の作業画面がスクロールバーぶん横にはみ出さないように */\nmain>.step:not([data-step=\"1\"]){margin-top:18px}\n\n/* 入門（タイトル）と印材棚：中央は空けて、宙で回る石を見せる */\n.intro{position:absolute;inset:0;z-index:8;display:flex;background:linear-gradient(rgba(8,5,3,.78),rgba(8,5,3,0) 34%),radial-gradient(ellipse 30% 40% at 50% 44%,rgba(8,5,3,0) 0,rgba(8,5,3,.1) 55%,rgba(8,5,3,.82) 100%);transition:opacity .5s}\n[hidden]{display:none!important} /* hidden はどんな display 指定より優先 */\n.intro[hidden]{display:none}\n.howto{position:absolute;inset:0;z-index:12;display:grid;place-items:center;background:rgba(8,5,3,.62);padding:16px}\n.howto[hidden]{display:none}\n.master .say,.howto-card,.bighint,.panel,.intro p,.k-text,#k-text{word-break:auto-phrase;line-break:strict}\n.chips li{white-space:nowrap}\n.chips li.bad::before{content:\"▲\";font-size:9px;margin-right:4px;vertical-align:1px}\n.k-actions{position:sticky;bottom:0;z-index:4;justify-content:flex-end;background:var(--washi);border-top:1px solid rgba(28,28,28,.18);padding:10px 0 12px;margin-bottom:-12px}\n.k-actions:has(#btn-cert:not([hidden])){position:fixed;right:16px;bottom:16px;left:auto;z-index:20;background:rgba(19,13,9,.86);border:1px solid #5a3c24;padding:8px;margin:0;gap:6px;width:auto}\n.k-actions:has(#btn-cert:not([hidden])) #btn-kantei{background:transparent;color:#efe6d6;border-color:#7a5a3e;font-weight:500}\n.k-actions:has(#btn-cert:not([hidden])) #btn-x{background:var(--washi)}\n.step[data-step=\"3\"]{padding-bottom:96px}\n.k-dock{position:fixed;left:0;right:0;bottom:0;z-index:20;background:#130d09;border-top:1px solid #000;box-shadow:inset 0 1px 0 rgba(168,132,62,.3)}\n.step[data-step=\"3\"][hidden] .k-dock{display:none}\n.k-dock-in{max-width:1280px;margin:0 auto;padding:10px max(12px,2.5vw);display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}\n.k-grp{display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n.k-lb{font-size:11px;letter-spacing:.3em;color:#a8998a;writing-mode:horizontal-tb;margin-right:2px}\n.k-dock .btn{margin:0}\n.k-dock .btn.ghost{background:transparent;color:#efe6d6;border-color:#7a5a3e}\n.k-dock .btn.ghost:hover:not(:disabled){border-color:var(--shu);color:#fff}\n.k-dock .btn.primary{background:var(--shu);border-color:var(--shu-deep);color:var(--washi);font-weight:700;padding-left:22px;padding-right:22px}\n.k-dock .btn:disabled{opacity:.55;cursor:progress}\n.k-more{position:relative}\n.k-more summary{list-style:none;cursor:pointer}\n.k-more summary::-webkit-details-marker{display:none}\n.k-menu{position:absolute;bottom:calc(100% + 8px);left:0;background:var(--washi);border:1px solid #b8aa92;display:grid;min-width:200px;box-shadow:inset 0 0 0 3px var(--washi),inset 0 0 0 4px rgba(28,28,28,.25);padding:6px}\n.k-menu button{background:transparent;border:0;text-align:left;padding:9px 12px;font-family:var(--f-mincho);color:var(--sumi);cursor:pointer;font-size:14px}\n.k-menu button:hover{background:rgba(200,50,40,.1);color:var(--shu-deep)}\n@media (max-width:700px){\n  .k-dock-in{flex-direction:column-reverse;align-items:stretch;gap:8px;padding:8px 10px}\n  .k-grp{flex-wrap:nowrap}\n  .k-lb{display:none}\n  .k-take{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1fr) minmax(0,1.3fr)}\n  .k-next{display:grid;grid-template-columns:1fr 1fr}\n  .k-dock .lg{display:none}\n  .k-more summary{display:flex;justify-content:center}\n  .k-menu{left:0;right:auto}\n  .k-next .btn{flex:1}\n  .k-dock .btn{min-height:44px;font-size:13px;padding:8px 8px;white-space:nowrap}\n  .k-more summary{white-space:nowrap}\n  .step[data-step=\"3\"]{padding-bottom:132px}\n}\n@media (max-width:700px){ .stage .choice-bar{left:10px;right:10px;transform:none;max-width:none;padding:8px} .stage .choice-bar::before{width:100%;text-align:center;margin:0} .stage .choice-bar button{flex:1 1 40%;padding:8px 6px;font-size:14px;white-space:nowrap} }\n@media (max-width:560px){ .k-actions:has(#btn-cert:not([hidden])){left:10px;right:10px;bottom:10px;justify-content:space-between} .k-actions:has(#btn-cert:not([hidden])) #btn-kantei{display:none} .k-actions .btn{flex:1;min-height:44px;font-size:13px;white-space:nowrap;padding:8px 6px;letter-spacing:.02em} }\n.k-actions #btn-cert{background:var(--shu);color:var(--washi);border-color:var(--shu-deep);order:9;font-weight:700}\n/* 選んでいる物は、色だけでなく印と太さでも示す */\n.shelf input:checked+label{font-weight:700}\n.shelf input:checked+label::after{content:\"選\";position:absolute;top:-8px;right:-8px;width:20px;height:20px;display:grid;place-items:center;background:var(--shu);color:var(--washi);font-size:11px;font-family:var(--f-mincho);transform:rotate(-6deg)}\n.shelf label{position:relative}\n#hud-tool button.on{font-weight:700;text-decoration:underline;text-underline-offset:3px}\n.bighint::after{content:\"\";position:absolute;left:50%;top:-7px;margin-left:-6px;border:6px solid transparent;border-top:0;border-bottom:7px solid var(--shu)}\n.bighint.up::after{top:auto;bottom:-7px;border-bottom:0;border-top:7px solid rgba(247,244,235,.92)}\n.edge-arrow{position:absolute;z-index:6;left:0;top:0;transform:translate(-50%,-50%);display:flex;align-items:center;gap:6px;background:var(--washi);color:var(--sumi);border:2px solid var(--sumi);padding:6px 10px;font-family:var(--f-mincho);font-size:13px;cursor:pointer;border-radius:0}\n.edge-arrow[hidden],.loupe[hidden]{display:none}\n.edge-arrow .ar{display:inline-block;color:var(--shu);font-size:16px}\n.edge-arrow:hover{border-color:var(--shu)}\n.loupe{position:absolute;z-index:7;left:0;top:0;width:120px;height:120px;border-radius:50%;border:3px solid var(--brass);box-shadow:0 0 0 2px #1a120d;pointer-events:none;background:#000}\n.master .bubble:has(#master-say:empty){visibility:hidden}\n.howto-card{background:var(--washi);color:var(--sumi);width:min(560px,100%);max-height:100%;overflow:auto;padding:22px 26px 20px;border:1px solid #b8aa92;box-shadow:inset 0 0 0 4px var(--washi),inset 0 0 0 5px rgba(28,28,28,.35);text-align:center}\n.howto-card h2{font-family:var(--f-mincho);font-weight:800;letter-spacing:.4em;margin:0 0 12px;font-size:22px}\n.howto-steps{list-style:none;margin:0 0 12px;padding:0;text-align:left;display:grid;gap:10px}\n.howto-steps li{display:flex;gap:12px;align-items:flex-start}\n.howto-steps i{flex:none;width:34px;height:34px;display:grid;place-items:center;border:2px solid var(--shu);color:var(--shu);font-style:normal;font-family:var(--f-mincho);font-weight:800;font-size:18px;transform:rotate(-6deg);margin-top:2px}\n.howto-steps b{display:block;font-family:var(--f-mincho);font-size:16px;letter-spacing:.1em}\n.howto-steps span{display:block;font-size:13.5px;line-height:1.8;color:#3a322b}\n.howto-steps rt{font-size:9px;color:#6b5f52;letter-spacing:0}\n.howto-ops{font-size:12px;color:#6b5f52;line-height:1.7;margin:0 0 14px;padding-top:10px;border-top:1px solid rgba(28,28,28,.15)}\n.howto-btn{margin-left:auto}\n.howto-btn+.sound{margin-left:8px}\n.intro.out{opacity:0;pointer-events:none}\n.intro-in{flex:1;display:flex;flex-direction:column;align-items:center;color:var(--washi);padding:22px 20px 16px;min-height:0;overflow:auto;text-align:center}\n.intro-head{display:flex;align-items:center;gap:18px}\n.intro-seal{width:58px;height:58px;border:3px solid var(--shu);display:grid;place-items:center;color:var(--shu);font-family:var(--f-seal);font-weight:800;font-size:34px;transform:rotate(-6deg);flex:none}\n.intro h2{font-family:var(--f-mincho);font-weight:800;font-size:clamp(32px,4.6vw,54px);margin:0;letter-spacing:.38em;padding-left:.38em}\n.intro p{margin:8px 0 0;font-size:clamp(13px,1.5vw,16px);line-height:1.9;color:#e4d9c6;letter-spacing:.08em}\n.intro p rt{font-size:9px;color:#b9ab95}\n.intro-gap{flex:1;min-height:150px;display:flex;align-items:flex-end;justify-content:center;padding-bottom:6px}\n.intro-gap span{font-family:var(--f-mincho);font-size:12px;letter-spacing:.3em;color:rgba(247,244,235,.55)}\n.intro-dock{width:min(980px,100%);background:linear-gradient(rgba(16,10,7,.0),rgba(16,10,7,.0));display:flex;flex-direction:column;align-items:center;gap:14px}\n.shelf{display:flex;gap:26px;align-items:stretch;justify-content:center;flex-wrap:wrap}\n.shelf-row{display:flex;gap:8px;align-items:stretch;justify-content:center;position:relative;padding-left:34px}\n.shelf-row::before{content:attr(data-k);position:absolute;left:0;top:0;bottom:0;width:24px;display:grid;place-items:center;writing-mode:vertical-rl;font-family:var(--f-mincho);font-size:13px;letter-spacing:.4em;color:var(--washi);background:#2a1c13;border:1px solid #5a3c24}\n.shelf input{position:absolute;opacity:0;pointer-events:none}\n.shelf label{display:flex;align-items:center;gap:10px;border:1px solid rgba(247,244,235,.22);background:rgba(16,10,7,.72);color:var(--washi);border-radius:0;padding:8px 14px;cursor:pointer;font-size:15px;text-align:left;letter-spacing:.08em;transition:border-color .2s,background .2s}\n.shelf label:hover{border-color:rgba(247,244,235,.55)}\n.shelf input:checked+label{border-color:var(--shu);background:rgba(110,24,18,.62)}\n.shelf input:focus-visible+label{outline:2px solid var(--brass);outline-offset:2px}\n.shelf-row.shapes label{flex-direction:column;gap:4px;width:70px;padding:9px 0 7px;justify-content:center;font-family:var(--f-mincho);font-weight:600}\n.shelf-row.shapes svg{width:30px;height:30px;fill:none;stroke:currentColor;stroke-width:1.5}\n.shelf-row.shapes input:checked+label svg{stroke:var(--shu);fill:rgba(200,50,40,.18)}\n.shelf label small{display:block;font-size:11px;color:#bcae98;line-height:1.4;letter-spacing:.04em}\n.shelf-row.mats label{width:168px}\n.shelf .swatch{width:18px;height:30px;border-radius:0;flex:none;border:1px solid rgba(0,0,0,.4)}\n.intro-btns{display:flex;gap:12px;align-items:center;justify-content:center}\n.intro-go{display:inline-block;background:var(--shu);color:var(--washi);font-weight:700;padding:12px 38px;border-radius:0;font-size:17px;border:1px solid var(--shu-deep);cursor:pointer;letter-spacing:.24em;font-family:var(--f-mincho)}\n.intro-go:hover{filter:brightness(1.1)}\n.intro-go:disabled{background:#5a4436;border-color:#5a4436;color:#cbbda6;cursor:progress;filter:none}\n.intro-cancel{background:rgba(16,10,7,.7);border:1px solid rgba(247,244,235,.4);color:var(--washi);border-radius:0;padding:11px 24px;font-size:15px;cursor:pointer;letter-spacing:.2em}\n#intro-note{color:#a8998a;font-size:12px;letter-spacing:.06em}\n.intro small{display:block;margin-top:16px;color:#9c8e7c;font-size:12px;letter-spacing:.06em}\nbody.pre .master,body.pre .mirror,body.pre .hud,body.seating .master,body.seating .mirror,body.seating .hud,body.seating .bighint{visibility:hidden}\n\n/* 中央の手引き（短冊） */\n.bighint{z-index:5;position:absolute;left:0;top:0;bottom:auto;transform:translate(-50%,0);max-width:min(86vw,440px);text-align:center;white-space:normal;background:rgba(247,244,235,.9);color:var(--sumi);padding:8px 22px;border-radius:0;border-top:2px solid var(--shu);font-size:16px;letter-spacing:.1em;pointer-events:none;white-space:nowrap;max-width:92%;overflow:hidden;text-overflow:ellipsis}\n@keyframes hintpulse{50%{opacity:.7}}\n\n/* 作業台の端の札 */\n.hud{position:absolute;z-index:6;left:14px;right:14px;bottom:14px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;pointer-events:none}\n.hud>*{pointer-events:auto}\n/* 表示（押せない）：枠なし・控えめ */\n.hud .pill.phase,.hud .pill.obs{background:rgba(14,9,6,.62);color:#efe6d6;border:0;cursor:default;padding:5px 10px;font-size:12px;letter-spacing:.14em}\n.hud .pill.phase::before,.hud .pill.obs::before{display:none}\n.hud .pill.phase{font-family:var(--f-mincho);border-left:3px solid var(--shu)}\n.hud .pill.obs b{color:#f0b9a8}\n.hud .obs i{display:inline-block;width:6px;height:10px;margin-left:2px;background:rgba(239,230,214,.18);vertical-align:-1px}\n.hud .obs i.on{background:#efe6d6}\n/* 操作（押せる）：和紙の札。触れると朱、押すと沈む */\n.hud .pill{position:relative;background:var(--washi);color:var(--sumi);border:1px solid #b8aa92;border-radius:0;padding:5px 12px;font-size:13px;cursor:pointer;user-select:none;letter-spacing:.06em;display:flex;align-items:center;gap:6px;transition:transform .08s,border-color .15s,background .15s}\n.hud .pill b{color:var(--shu-deep);font-weight:700}\n.hud .pill:not(.phase):not(.obs):hover{border-color:var(--shu)}\n.hud .pill:not(.phase):not(.obs):active,.hud .act:active,#hud-tool button:active{transform:translateY(1px)}\n.hud .pill:focus-visible,.hud .act:focus-visible,#hud-tool button:focus-visible{outline:2px solid var(--brass);outline-offset:2px}\n/* いちばん大事な「完成」「提出」は右端に大きく */\n.hud .done{margin-left:auto;background:var(--shu);color:var(--washi);border-color:var(--shu-deep);font-weight:700;letter-spacing:.16em;font-size:15px;padding:9px 18px;font-family:var(--f-mincho)}\n.hud .done:hover{background:#d8402f}\n.hud .done{order:9}\n.hud .pill.prog{order:8;margin-left:auto;background:rgba(14,9,6,.7);color:#efe6d6;border:0;cursor:default;font-size:13px;letter-spacing:.08em;padding:6px 12px}\n.hud .pill.prog b{color:#ffd2c4;font-size:16px;font-variant-numeric:tabular-nums;margin-left:4px}\n.hud:has(#hud-prog:not([hidden])) .done{margin-left:0}\n.hud .tip{order:8}\n.hud [hidden]{display:none!important}\n.hud .acts{display:inline-flex;gap:3px}\n.hud .act:hover:not(:disabled){border-color:var(--shu);color:var(--shu-deep)}\n#hud-tool{display:inline-flex;align-items:center;gap:3px;padding:2px 4px 2px 10px}\n#hud-tool .lb{margin-right:4px}\n#hud-tool button{font-family:var(--f-mincho);font-size:13px;min-width:32px;padding:4px 6px;border:1px solid rgba(28,28,28,.3);background:transparent;color:var(--sumi);cursor:pointer;border-radius:0}\n#hud-tool button.on{background:var(--shu);border-color:var(--shu);color:var(--washi)}\n.hud .act{font-family:var(--f-mincho);font-size:13px;letter-spacing:.12em;padding:5px 10px;border:1px solid rgba(28,28,28,.35);background:var(--washi);color:var(--sumi);cursor:pointer;border-radius:0;position:relative;overflow:hidden}\n.hud .act:disabled{opacity:.45;cursor:default}\n.hud .act.cool::after{content:\"\";position:absolute;left:0;bottom:0;height:3px;background:var(--shu);animation:cool 1.5s linear forwards}\n@keyframes cool{from{width:100%}to{width:0}}\n.hud .pill.bow{display:inline-flex;align-items:center;gap:6px;padding:2px 4px}\n.hud .pill.bow button{border:1px solid rgba(28,28,28,.35);background:transparent;color:var(--sumi);width:30px;height:28px;cursor:pointer;font-size:13px;border-radius:0}\n.hud .pill.bow button:active{background:rgba(200,50,40,.15)}\n.hud .tip{color:#f3ebdd;background:rgba(14,9,6,.62);padding:5px 10px;font-size:12px;pointer-events:none;align-self:center;letter-spacing:.04em}\n.tooltip3d{position:absolute;z-index:4;pointer-events:none;background:var(--washi);color:var(--sumi);border:1px solid var(--sumi);border-left:3px solid var(--shu);padding:3px 10px;font-size:13px;transform:translate(14px,-120%);white-space:nowrap;letter-spacing:.06em}\n\n.step{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:20px;align-items:start}\n.step.wide{grid-template-columns:minmax(0,1.65fr) minmax(0,1fr)}\n.step.work{display:flex;flex-direction:column;gap:14px}\n.step[hidden]{display:none}\n.panel{background:var(--washi);color:var(--sumi);border-radius:0;padding:22px;border:1px solid #cdbfa6;box-shadow:inset 0 0 0 4px var(--washi),inset 0 0 0 5px rgba(28,28,28,.25)}\n.panel h2{font-family:var(--f-mincho);font-weight:700;font-size:22px;margin:0;letter-spacing:.24em;text-wrap:balance}\n.panel h3{font-size:13px;margin:0 0 8px;letter-spacing:.2em;color:var(--muted);font-weight:700}\n.lead{margin:0 0 14px;color:var(--muted);font-size:14px}\n.stack{display:flex;flex-direction:column;gap:18px}\n.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}\n.hint{font-size:12px;color:var(--muted);margin:6px 0 0}\n.seg{display:flex;flex-wrap:wrap;gap:6px}\n.seg input,.tray input{position:absolute;opacity:0;pointer-events:none}\n.seg label{border:1px solid #b8aa92;background:var(--washi);border-radius:0;padding:5px 12px;cursor:pointer;font-size:14px;user-select:none;display:flex;align-items:center;gap:8px}\n.seg input:checked+label{border-color:var(--shu);color:var(--shu-deep);font-weight:700}\n.swatch{width:18px;height:18px;display:inline-block;border:1px solid rgba(0,0,0,.2)}\n\n.btn{border:1px solid transparent;border-radius:0;padding:9px 20px;font-weight:700;cursor:pointer;font-size:15px;letter-spacing:.14em;font-family:var(--f-mincho)}\n.btn:active{transform:translateY(1px)}\n.btn.primary{background:var(--shu);color:var(--washi);border-color:var(--shu-deep)}\n.btn.primary:hover{filter:brightness(1.08)}\n.btn.ghost{background:transparent;border-color:var(--sumi-2);color:var(--sumi)}\n.btn.ghost:hover{background:rgba(28,28,28,.06)}\n.btn:disabled{opacity:.45;cursor:not-allowed}\n.btn.small{padding:6px 14px;font-size:13px}\n\n/* 工房（3D） */\n.stage{position:relative;width:100vw;margin-left:calc(50% - 50vw);max-width:none;height:calc(100vh - 62px);height:calc(100dvh - 62px);min-height:420px;overflow:hidden;background:#0c0806;touch-action:none;user-select:none}\n.stage canvas#gl{position:absolute;inset:0;width:100%;height:100%;display:block}\n.stage::after{content:\"\";position:absolute;inset:0;pointer-events:none;z-index:1;background:radial-gradient(ellipse 75% 70% at 50% 52%,transparent 55%,rgba(6,4,2,.55))}\n.gl-error{position:absolute;inset:0;display:grid;place-items:center;color:var(--washi);padding:24px;text-align:center;font-size:14px}\n.mirror{position:absolute;right:16px;top:14px;z-index:3;display:flex;flex-direction:column;align-items:center;gap:6px;color:var(--washi);font-size:12px;letter-spacing:.12em;text-shadow:0 1px 2px #000}\n.mirror canvas{width:110px;height:110px;border-radius:50%;background:var(--washi);border:4px solid #1e140f;box-shadow:0 0 0 2px var(--brass),inset 0 0 14px rgba(40,25,15,.45)}\n.mirror label{display:flex;gap:5px;align-items:center;cursor:pointer;background:var(--washi);color:var(--sumi);border:1px solid #b8aa92;padding:1px 8px;text-shadow:none;letter-spacing:.04em}\n.mirror input{accent-color:var(--shu)}\n.tray{display:none!important}\n\n/* 親方 */\n.master{display:flex;gap:12px;align-items:flex-start;z-index:6;pointer-events:auto}\n.master .face3d{width:124px;height:124px;flex:none;display:block;cursor:pointer;overflow:visible}\n.master .face3d #mHead{transform-origin:60px 88px;transform-box:view-box}\n.master .face3d.nod #mHead{animation:mnod .55s ease-out}\n.master .face3d.shake #mHead{animation:mshake .7s ease-out}\n.master .face3d.bob #mHead{animation:mbob .8s ease-out}\n.master .face3d.tilt #mHead{animation:mtilt 1.2s ease-out forwards}\n.master .face3d.back #mHead{animation:mback .6s ease-out}\n@keyframes mnod{0%{transform:translateY(0)}35%{transform:translateY(2.4px) rotate(1deg)}70%{transform:translateY(-.6px)}100%{transform:none}}\n@keyframes mshake{0%,100%{transform:none}20%{transform:rotate(-4deg)}45%{transform:rotate(3.5deg)}70%{transform:rotate(-2deg)}}\n@keyframes mbob{0%,100%{transform:none}25%{transform:translateY(-2px)}50%{transform:translateY(1px)}75%{transform:translateY(-1.5px)}}\n@keyframes mtilt{to{transform:rotate(5deg)}}\n@keyframes mback{0%,100%{transform:none}30%{transform:translateY(-2.5px) scale(1.02)}}\n.master .bubble{display:flex;gap:0;margin-top:10px;max-width:470px;min-width:230px;background:rgba(244,239,230,.95);color:var(--sumi);border:3px double rgba(28,28,28,.72);border-radius:0;position:relative}\n.master .nameplate{writing-mode:vertical-rl;text-orientation:upright;color:#ead9bb;border-right:1px solid #120c08;padding:8px 4px;font-size:13px;letter-spacing:.24em;font-weight:700;flex:none;line-height:1}\n.master .bubble-body{padding:8px 14px 10px;flex:1;min-width:0}\n.master .who{font-size:11px;color:var(--muted);display:flex;justify-content:flex-end;gap:10px;min-height:0}\n.master .who button{background:transparent;border:1px solid rgba(28,28,28,.3);color:#5a4d40;cursor:pointer;font-size:11px;padding:1px 7px;letter-spacing:.08em;font-family:var(--f-mincho);border-radius:0}\n.master .who button:hover{border-color:var(--shu);color:var(--shu)}\n.master .say{font-family:var(--f-mincho);font-size:16px;font-weight:500;line-height:1.85;white-space:pre-wrap;min-height:1.85em;letter-spacing:.04em}\n.master .say.fresh{animation:sayin .4s ease-out}\n@keyframes sayin{from{opacity:.3;transform:translateY(3px)}to{opacity:1;transform:none}}\n.master .grade{display:inline-block;font-family:var(--f-seal);font-weight:800;color:var(--shu);border:2.5px solid var(--shu);padding:0 8px;margin:4px 8px 2px 0;transform:rotate(-6deg);font-size:20px;line-height:1.5}\n.master .grade.self{color:var(--sumi-2);border-color:var(--sumi-2);transform:rotate(4deg)}\n.master .score-break{font-size:12px;color:var(--muted);letter-spacing:.04em}\n.master .trial{float:right;width:88px;height:88px;margin:0 0 4px 10px;background:var(--washi);border:1px solid #cdbfa6}\n.choice-bar{position:absolute;z-index:7;left:50%;transform:translateX(-50%);bottom:var(--choice-bottom,76px);display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:center;max-width:calc(100% - 28px);background:rgba(19,13,9,.9);border:1px solid #5a3c24;padding:8px 10px}\n.choice-bar:empty{display:none}\n.choice-bar::before{content:\"源じいへの返事\";font-size:11px;letter-spacing:.2em;color:#a8998a;margin-right:4px}\n.choice-bar button{border:1px solid #b8aa92;background:var(--washi);border-radius:0;padding:8px 16px;font-size:14px;font-weight:700;cursor:pointer;letter-spacing:.08em;color:var(--sumi);font-family:var(--f-mincho)}\n.choice-bar button:hover{border-color:var(--shu);color:var(--shu-deep)}\n.choice-bar button:active{transform:translateY(1px)}\n.choice-bar button.primary{background:var(--shu);border-color:var(--shu-deep);color:var(--washi)}\n.choice-bar button kbd{font:inherit;font-size:10px;opacity:.75;margin-left:6px;border:1px solid currentColor;padding:0 3px;letter-spacing:0}\n.master.in-stage{position:absolute;left:14px;top:12px;max-width:calc(100% - 170px)}\n.master.floating{position:fixed;left:16px;bottom:16px;max-width:min(580px,calc(100% - 32px))}\n.master.min .bubble{display:none}\n.m-slot{grid-column:1/-1}\n.master.inline{position:relative}\n.master.inline .face3d{width:96px;height:96px}\n.master.inline .bubble{max-width:760px;flex:1}\n.master.floating .face3d{width:100px;height:100px}\n.master.floating.right{left:auto;right:16px;flex-direction:row-reverse}\n\n/* 押す（旧画面・非表示） */\n.doc-wrap canvas{width:100%;height:auto;display:block;touch-action:none;cursor:none}\n.pad-row{display:flex;gap:16px;align-items:center}\n#pad{width:92px;height:92px;border-radius:50%;border:6px solid #3a302c;background:var(--shu);cursor:pointer;flex:none}\n.meter{position:relative;height:14px;overflow:hidden;background:var(--washi-2)}\n.meter>i{position:absolute;left:0;top:0;bottom:0;width:0;background:var(--shu)}\n.scale{display:flex;justify-content:space-between;font-size:11px;color:var(--muted);margin-top:2px}\n.readout{font-weight:700;font-variant-numeric:tabular-nums}\ninput[type=range]{width:100%;accent-color:var(--shu)}\n.angle-head{display:flex;justify-content:space-between;align-items:baseline;gap:8px}\n.bow-name{font-family:var(--f-display);font-size:22px;color:var(--shu)}\n.result{border-top:1px dashed #b8aa92;padding-top:14px;display:flex;flex-direction:column;gap:6px}\n.res-row{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap}\n.res-k{font-size:12px;color:var(--muted);width:42px;flex:none}\n.score{margin-left:auto;font-family:var(--f-seal);font-weight:800;color:var(--shu);font-size:22px}\n.result p{margin:0 0 4px 52px;font-size:13px;color:var(--muted)}\n\n/* 鑑定 */\n.imp-box{background:var(--washi);border:1px solid #cdbfa6;display:grid;place-items:center;padding:16px}\n.imp-box.check-bg{background-color:#fff;background-image:conic-gradient(#eee 25%,#fff 0 50%,#eee 0 75%,#fff 0);background-size:20px 20px}\n.imp-box img{width:min(100%,300px);aspect-ratio:1;display:block}\n.cert{background:var(--washi);color:var(--sumi);border:1px solid var(--shu);box-shadow:inset 0 0 0 5px var(--washi),inset 0 0 0 6px var(--shu);padding:22px 24px}\n.cert-head{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;border-bottom:1px solid rgba(28,28,28,.25);padding-bottom:10px;margin-bottom:14px;flex-wrap:wrap}\n.cert-head h2{margin:0;font-family:var(--f-mincho);font-weight:800;font-size:26px;letter-spacing:.3em}\n.engine{font-size:12px;color:var(--muted)}\n.chips{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 14px;padding:0;list-style:none}\n.chips li{font-size:12px;background:transparent;border:1px solid #b8aa92;padding:2px 10px}\n.chips li b{font-variant-numeric:tabular-nums}\n.chips li.bad{border-color:var(--shu);color:var(--shu-deep)}\n.chips.key li{font-size:14px;padding:5px 12px}\n.chips.key li b{font-size:16px}\n.more-stats{margin:6px 0 4px}\n.more-stats summary{cursor:pointer;font-size:12px;color:var(--muted);letter-spacing:.1em;padding:4px 0}\n.more-stats summary:hover{color:var(--shu-deep)}\n.more-stats .chips{margin-top:6px}\n.titles{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 14px;padding:0;list-style:none}\n.titles li{background:var(--wood-3);color:#f2e3c6;font-family:var(--f-brush);font-size:18px;padding:3px 12px 5px;display:flex;flex-direction:column;line-height:1.3;border:1px solid #120c08}\n.titles li small{font-family:var(--f-mincho);font-size:10px;opacity:.8}\n.titles li.none{background:transparent;color:var(--muted);font-size:14px;border-color:#b8aa92}\n.show3d-wrap{position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 30%,#3a2a1e,#100b08 80%);border:1px solid #000}\n.show3d-wrap canvas{display:block;width:100%;height:auto;cursor:grab;touch-action:none}\n.show3d-wrap span{position:absolute;left:10px;bottom:6px;font-size:11px;color:#cbbda6;pointer-events:none;letter-spacing:.1em}\n.collect{margin:-4px 0 14px;font-size:13px}\n.collect summary{cursor:pointer;color:var(--muted);font-weight:700;letter-spacing:.1em}\n.collect-list{display:flex;flex-wrap:wrap;gap:6px;list-style:none;padding:0;margin:8px 0 0}\n.collect-list li{border:1px solid #b8aa92;padding:1px 8px;font-size:12px}\n.collect-list li.lock{color:#b0a38e}\n.stars{display:grid;grid-template-columns:auto 1fr;gap:2px 14px;margin-bottom:14px;font-size:14px}\n.stars .st{color:var(--shu);letter-spacing:.12em}\n.stars .st span{color:#d6cbb6}\n#k-text{white-space:pre-wrap;font-size:15px;line-height:2;min-height:6em;max-width:65ch}\n#k-text .kh{font-family:var(--f-seal);font-weight:800;color:var(--shu-deep)}\n.thinking{color:var(--muted);animation:blink 1.2s infinite}\n@keyframes blink{50%{opacity:.4}}\n.note{font-size:11px;color:var(--muted);margin:12px 0 0}\n.empty{text-align:center;padding:40px 20px;color:var(--muted)}\n.toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:var(--washi);color:var(--sumi);border-top:2px solid var(--shu);padding:9px 20px;font-size:14px;opacity:0;pointer-events:none;transition:opacity .2s;max-width:calc(100% - 32px);text-align:center;z-index:9;letter-spacing:.06em}\n.toast.show{opacity:1}\n\n@media (max-width:900px){\n  .step,.step.wide{grid-template-columns:1fr}\n  nav.steps{margin-left:0}\n  .stage{height:calc(100dvh - 110px)}\n  .master.in-stage{max-width:calc(100% - 24px)}\n  .master .face3d{width:92px;height:92px}\n  .mirror{top:auto;bottom:58px;right:10px}\n  .hud .tip{font-size:12px}\n  .shelf{flex-direction:column;align-items:center;gap:10px}\n  .shelf-row.mats{width:min(100%,360px)}\n  .shelf-row.mats label{width:auto;flex:1;min-width:0;flex-direction:column;gap:4px;padding:8px 4px;text-align:center}\n  .shelf-row.mats label small{display:none}\n  .shelf-row.shapes label{width:62px}\n  .intro-gap{min-height:120px}\n  .intro-go{padding:12px 26px}\n  .bighint{font-size:13px;padding:6px 12px}\n  .mirror canvas{width:84px;height:84px}\n  .master .trial{width:60px;height:60px}\n  body[data-phase=press] .mirror{display:none}\n  .master.in-stage .say{max-height:34vh;overflow:auto}\n}\n@media (max-width:560px){\n  .brand p{display:none}\n  header.top{flex-wrap:nowrap;gap:8px;padding:0 12px;height:56px;box-sizing:border-box}\n  .brand h1{font-size:19px;letter-spacing:.24em}\n  header.top .sound{font-size:12px;padding:5px 9px;white-space:nowrap}\n  .howto-btn+.sound{margin-left:4px}\n  .stage{height:calc(100dvh - 56px)}\n  .master .face3d{width:66px;height:66px}\n  .master.min .face3d{box-shadow:0 0 0 2px var(--shu)}\n  /* 手鏡は親方の顔の下へ（石に重ねない） */\n  .mirror{top:94px;bottom:auto;left:10px;right:auto;gap:4px;font-size:10px;letter-spacing:.04em}\n  .mirror canvas{width:66px;height:66px;border-width:3px}\n  .mirror label{font-size:10px;padding:1px 4px;max-width:92px;line-height:1.3}\n  .hud{gap:4px}\n  .hud .obs,.hud .pill.phase{display:none}\n  .hud .done{font-size:14px;padding:8px 14px}\n  .hud .act{padding:5px 8px;font-size:12px;letter-spacing:.06em}\n}\n@media (pointer:coarse){\n  .choice-bar button kbd{display:none}\n  .choice-bar button{min-height:44px}\n  .hud .act,#hud-tool button,.hud .pill.bow button{min-height:40px;min-width:40px}\n  .hud .done{min-height:46px}\n}\n@media (prefers-reduced-motion: reduce){\n  *{transition:none!important;animation:none!important}\n}\n</style>\n</head>\n<body class=\"pre\">\n<header class=\"top\">\n  <div class=\"brand\">\n    <div class=\"mark\" aria-hidden=\"true\">工</div>\n    <div>\n      <h1>ハンコ工房</h1>\n      <p>親方に教わりながら、石を彫る</p>\n    </div>\n  </div>\n  <button type=\"button\" class=\"sound howto-btn\" id=\"howto-open\">遊び方</button><button type=\"button\" class=\"sound\" id=\"sound\" aria-pressed=\"true\">音：オン</button>\n</header>\n\n<main>\n  <!-- 一 彫る -->\n  <section class=\"step work\" data-step=\"1\">\n    <div class=\"stage\" id=\"stage\">\n      <div class=\"howto\" id=\"howto\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"howto-title\" hidden>\n        <div class=\"howto-card\">\n          <h2 id=\"howto-title\">遊び方</h2>\n          <ol class=\"howto-steps\">\n            <li><i>一</i><div><b>下書き（<ruby>布字<rt>ふじ</rt></ruby>）</b><span>筆で、赤い印面に彫りたい字を書く。名前の一字でも、絵でもいい。書けたら右下の「書けた → 彫りへ」。</span></div></li>\n            <li><i>二</i><div><b>彫る</b><span><ruby>印刀<rt>いんとう</rt></ruby>で墨の線をなぞる。同じ所をなぞるほど深くなる。細かい所は「寄る」で近づく。終わったら右下の「呼び鈴」。</span></div></li>\n            <li><i>三</i><div><b>押す</b><span>朱肉を2〜3回トントン → <ruby>稟議書<rt>りんぎしょ</rt></ruby>の担当欄を長押し。上司の欄の方へ少し傾けて押すのが、この工房の作法。</span></div></li>\n            <li><i>四</i><div><b>鑑定</b><span>押した印影から<ruby>印相<rt>いんそう</rt></ruby>鑑定書ができる。画像で保存できる。</span></div></li>\n          </ol>\n          <p class=\"howto-ops\" id=\"howto-ops\"></p>\n          <button type=\"button\" class=\"intro-go\" id=\"howto-close\">朱を塗って始める</button>\n        </div>\n      </div>\n      <div class=\"intro\" id=\"intro\">\n        <div class=\"intro-in\">\n          <div class=\"intro-head\"><div class=\"intro-seal\" aria-hidden=\"true\">印</div><h2 id=\"intro-title\">ハンコ工房</h2></div>\n          <p id=\"intro-lead\">頑固な親方に教わって、石の印鑑を筆の下書きから彫る。<br>仕上げは<ruby>稟議書<rt>りんぎしょ</rt></ruby>に、上司へお辞儀して押す。</p>\n          <div class=\"intro-gap\" aria-hidden=\"true\"><span id=\"intro-stone\">青田石・丸</span></div>\n          <div class=\"intro-dock\">\n          <div class=\"shelf\">\n            <div class=\"shelf-row shapes\" data-k=\"形\" role=\"radiogroup\" aria-label=\"印材の形\">\n              <input type=\"radio\" name=\"shape\" id=\"sh-round\" value=\"round\" checked><label for=\"sh-round\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/></svg>丸</label>\n              <input type=\"radio\" name=\"shape\" id=\"sh-square\" value=\"square\"><label for=\"sh-square\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"3.5\" y=\"3.5\" width=\"17\" height=\"17\" rx=\"1.5\"/></svg>角</label>\n              <input type=\"radio\" name=\"shape\" id=\"sh-oval\" value=\"oval\"><label for=\"sh-oval\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><ellipse cx=\"12\" cy=\"12\" rx=\"6.5\" ry=\"9.5\"/></svg>小判</label>\n            </div>\n            <div class=\"shelf-row mats\" data-k=\"石\" role=\"radiogroup\" aria-label=\"石の種類\">\n              <input type=\"radio\" name=\"mat\" id=\"mt-seiden\" value=\"seiden\" checked><label for=\"mt-seiden\"><i class=\"swatch\" style=\"background:linear-gradient(135deg,#c2c48e,#8e9a62)\"></i><span>青田石<small>柔らかく素直。初めてならこれ</small></span></label>\n              <input type=\"radio\" name=\"mat\" id=\"mt-jusan\" value=\"jusan\"><label for=\"mt-jusan\"><i class=\"swatch\" style=\"background:linear-gradient(135deg,#e6c49a,#b06a48)\"></i><span>寿山石<small>粘りがあって欠けにくい</small></span></label>\n              <input type=\"radio\" name=\"mat\" id=\"mt-barin\" value=\"barin\"><label for=\"mt-barin\"><i class=\"swatch\" style=\"background:linear-gradient(135deg,#ddb57c,#a83a30)\"></i><span>巴林石<small>硬くて欠けやすい。上級者向け</small></span></label>\n            </div>\n          </div>\n          <div class=\"intro-btns\"><button type=\"button\" class=\"intro-go\" id=\"intro-go\" disabled>石を運んでいます…</button><button type=\"button\" class=\"intro-cancel\" id=\"intro-cancel\" hidden>やめる</button></div>\n          <small id=\"intro-note\">音が出ます。左ドラッグで書く・彫る／右ドラッグで見回す／道具は画面下の札で替える</small>\n          </div>\n        </div>\n      </div>\n      <canvas id=\"gl\" aria-label=\"印房の作業台。印面をなぞると筆で書く、または彫る。印面の外をドラッグすると視点が回る\"></canvas>\n      <div class=\"mirror\">\n        <canvas id=\"pv\" width=\"360\" height=\"360\" aria-label=\"手鏡。押したときの印影\"></canvas>\n        <span>手鏡（押した向き）</span>\n        <label><input type=\"checkbox\" id=\"noflip\">反転させずに押す</label>\n      </div>\n      <div class=\"bighint\" id=\"bighint\" hidden></div><button type=\"button\" class=\"edge-arrow\" id=\"edge-arrow\" hidden aria-label=\"石を画面の真ん中に戻す\"><span class=\"ar\" aria-hidden=\"true\">➤</span><span class=\"lb\">石はこっち</span></button><canvas class=\"loupe\" id=\"loupe\" width=\"240\" height=\"240\" hidden></canvas>\n      <div class=\"tooltip3d\" id=\"tip3d\" hidden></div>\n      <div class=\"hud\" id=\"hud\"><span class=\"pill phase\" id=\"hud-phase\">工程：朱を塗る</span><span class=\"pill done\" id=\"hud-done\" role=\"button\" tabindex=\"0\" hidden>呼び鈴を鳴らす（完成）</span><span class=\"pill done\" id=\"hud-submit\" role=\"button\" tabindex=\"0\" hidden>鑑定に出す</span><span class=\"pill bow\" id=\"hud-bow\" hidden><button type=\"button\" id=\"bow-l\" aria-label=\"上司のほうへ傾ける\">◁</button><span>お辞儀 <b id=\"hud-bow-v\">0°</b></span><button type=\"button\" id=\"bow-r\" aria-label=\"戻す\">▷</button></span><span class=\"pill\" id=\"hud-tool\" role=\"button\" tabindex=\"0\" title=\"クリックで太さを切り替え（1・2・3キーでも可）\">筆・<b>中</b></span><span class=\"acts\" id=\"hud-view\" aria-label=\"見え方\"><button type=\"button\" class=\"act\" id=\"act-near\" data-ph=\"fuji carve review\" title=\"寄る（ホイール・ピンチでも可）\">寄る</button><button type=\"button\" class=\"act\" id=\"act-far\" data-ph=\"fuji carve review\" title=\"引く\">引く</button><button type=\"button\" class=\"act\" id=\"act-top\" data-ph=\"fuji carve review\" title=\"真上から／斜めから\">真上</button></span><span class=\"acts\" id=\"hud-acts\" aria-label=\"作業\"><button type=\"button\" class=\"act\" id=\"act-wipe\" data-ph=\"fuji\" title=\"下書きを拭いて消す\">拭く</button><button type=\"button\" class=\"act\" id=\"act-blow\" data-ph=\"carve review\" title=\"かすを吹き飛ばす（Space）\">吹く</button><button type=\"button\" class=\"act\" id=\"act-grind\" data-ph=\"carve review\" title=\"印面を研いで最初から\">研ぐ</button></span><span class=\"pill prog\" id=\"hud-prog\" hidden></span><span class=\"pill obs\" id=\"hud-obs\" hidden title=\"執着度\">執着：<b>素人</b></span><span class=\"tip\" id=\"hud-tip\" hidden>左ドラッグで書く・彫る ／ 右ドラッグで回す ／ 1・2・3で太さ</span></div>\n      <div class=\"tray\" id=\"tray\">\n        <span data-phase=\"fuji\">\n          <input type=\"radio\" name=\"tool\" id=\"t-f6\" value=\"f6\"><label for=\"t-f6\">筆・太</label>\n          <input type=\"radio\" name=\"tool\" id=\"t-f3\" value=\"f3\"><label for=\"t-f3\">筆・中</label>\n          <input type=\"radio\" name=\"tool\" id=\"t-f2\" value=\"f2\"><label for=\"t-f2\">筆・細</label>\n        </span>\n        <span data-phase=\"carve\" hidden>\n          <input type=\"radio\" name=\"tool\" id=\"t-k14\" value=\"k14\"><label for=\"t-k14\">印刀・大</label>\n          <input type=\"radio\" name=\"tool\" id=\"t-k7\" value=\"k7\"><label for=\"t-k7\">印刀・中</label>\n          <input type=\"radio\" name=\"tool\" id=\"t-k3\" value=\"k3\"><label for=\"t-k3\">印刀・小</label>\n          <input type=\"radio\" name=\"tool\" id=\"t-k1\" value=\"k1\"><label for=\"t-k1\">印刀・極細</label>\n        </span>\n        <input type=\"radio\" name=\"tool\" id=\"t-rot\" value=\"rotate\"><label for=\"t-rot\">見回すだけ</label>\n        <span class=\"sep\" aria-hidden=\"true\"></span>\n        <button type=\"button\" id=\"btn-undo\" disabled>ひと手戻す</button>\n        <button type=\"button\" id=\"btn-wipe\" data-phase=\"fuji\">墨を拭く</button>\n        <button type=\"button\" id=\"btn-blow\" data-phase=\"carve\" hidden>フッと吹く</button>\n        <button type=\"button\" id=\"btn-grind\" data-phase=\"carve\" hidden>砥石で研ぎ直す</button>\n        <span class=\"sep\" aria-hidden=\"true\"></span>\n        <button type=\"button\" id=\"v-tilt\">斜めから</button>\n        <button type=\"button\" id=\"v-top\">真上から</button>\n        <button type=\"button\" id=\"v-near\">寄る</button>\n        <button type=\"button\" id=\"v-far\">引く</button>\n        <button type=\"button\" id=\"v-spin\" aria-pressed=\"false\">ろくろ</button>\n      </div>\n    </div>\n\n    <div class=\"records\" hidden aria-hidden=\"true\">\n      <span id=\"phase-now\"></span><span id=\"phase-hint\"></span>\n      <span id=\"lb-prog\"></span><b id=\"st-prog\"></b><span id=\"row-spill\"><span id=\"lb-spill\"></span><b id=\"st-spill\"></b></span>\n      <span id=\"row-rim\"><b id=\"st-rim\"></b></span><b id=\"st-area\"></b><b id=\"st-time\"></b><b id=\"st-strokes\"></b><b id=\"st-ink\"></b><b id=\"st-spin\"></b><b id=\"st-grind\"></b><b id=\"st-grade\"></b>\n    </div>\n  </section>\n\n  <!-- 二 押す -->\n  <section class=\"step wide\" data-step=\"2\" hidden>\n    <div class=\"panel\">\n      <h2>押す</h2>\n      <p class=\"lead\">稟議書の「担当」欄を長押しすると力がたまり、離した瞬間に押されます。上司の欄は左側です。</p>\n      <div class=\"doc-wrap\"><canvas id=\"doc\" width=\"960\" height=\"600\" aria-label=\"稟議書。長押しで押印\"></canvas></div>\n      <div class=\"row\" style=\"margin-top:12px\">\n        <button type=\"button\" class=\"btn ghost small\" id=\"btn-newdoc\">新しい稟議書に替える</button>\n      </div>\n    </div>\n    <div class=\"panel stack\">\n      <div>\n        <h3>朱肉</h3>\n        <div class=\"pad-row\">\n          <button type=\"button\" id=\"pad\" aria-label=\"朱肉をつける\"></button>\n          <div style=\"flex:1\">\n            <div class=\"readout\" id=\"ink-val\">空っぽ</div>\n            <div class=\"meter\" aria-hidden=\"true\"><i id=\"ink-fill\"></i></div>\n            <div class=\"scale\"><span>かすれ</span><span>適量</span><span>滲み</span></div>\n            <p class=\"hint\">朱肉をタップするたびに印面へ朱がつきます。</p>\n          </div>\n        </div>\n      </div>\n      <div>\n        <div class=\"angle-head\"><h3><label for=\"angle\">お辞儀の角度</label></h3><span class=\"readout\" id=\"angle-val\">0°</span></div>\n        <input type=\"range\" id=\"angle\" min=\"-90\" max=\"90\" step=\"1\" value=\"0\">\n        <div class=\"scale\"><span>← 上司側へ傾ける</span><span>まっすぐ</span><span>反対側 →</span></div>\n        <div class=\"bow-name\" id=\"bow-live\">直立不動</div>\n      </div>\n      <div>\n        <h3>押す力</h3>\n        <div class=\"meter press\" aria-hidden=\"true\"><i id=\"press-fill\"></i></div>\n        <div class=\"scale\"><span>弱い</span><span>適正</span><span>強すぎ</span></div>\n      </div>\n      <div class=\"result\" id=\"result\" hidden>\n        <div class=\"res-row\"><span class=\"res-k\">お辞儀</span><strong id=\"r-bow\"></strong><span class=\"score\" id=\"r-score\"></span></div>\n        <p id=\"r-bow-c\"></p>\n        <div class=\"res-row\"><span class=\"res-k\">印影</span><strong id=\"r-ink\"></strong></div>\n        <p id=\"r-ink-c\"></p>\n        <div class=\"res-row\"><span class=\"res-k\">場所</span><strong id=\"r-box\"></strong></div>\n        <div class=\"row\" style=\"margin-top:8px\"><button type=\"button\" class=\"btn primary\" data-go=\"3\">この印影を鑑定してもらう</button></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 三 鑑定 -->\n  <section class=\"step\" data-step=\"3\" hidden>\n    <div class=\"k-dock\" id=\"k-dock\" role=\"toolbar\" aria-label=\"鑑定のあとにできること\">\n      <div class=\"k-dock-in\">\n        <div class=\"k-grp k-next\"><span class=\"k-lb\">つぎ</span><button type=\"button\" class=\"btn ghost\" id=\"d-repress\"><span class=\"lg\">新しい紙で</span>押し直す</button><button type=\"button\" class=\"btn ghost\" id=\"d-again\"><span class=\"lg\">石を選んで</span>もう一本</button></div>\n        <div class=\"k-grp k-take\"><span class=\"k-lb\">持ち帰る</span>\n          <details class=\"k-more\" id=\"d-more\"><summary class=\"btn ghost\">印影<span class=\"lg\">だけ保存</span> ▾</summary><div class=\"k-menu\"><button type=\"button\" id=\"d-ex-straight\">透過PNG（まっすぐ）</button><button type=\"button\" id=\"d-ex-bow\">透過PNG（お辞儀版）</button><button type=\"button\" id=\"d-ex-doc\">稟議書ごと</button></div></details>\n          <button type=\"button\" class=\"btn ghost\" id=\"d-x\" disabled>Xに投稿<span class=\"lg\">（画像も保存）</span></button>\n          <button type=\"button\" class=\"btn primary\" id=\"d-cert\" disabled>鑑定中…</button>\n        </div>\n      </div>\n    </div>\n    <div class=\"m-slot\" id=\"m-slot3\"></div>\n    <div class=\"panel stack\">\n      <h2>印影</h2>\n      <div id=\"k-empty\" class=\"empty\">まだ押印していません。<br>「二 押す」で稟議書に押してから戻ってきてください。</div>\n      <div id=\"k-left\" class=\"stack\" hidden>\n        <div class=\"row\" style=\"display:none\"><button type=\"button\" class=\"btn ghost small\" id=\"btn-again\">もう一本彫る（最初から）</button></div>\n        <div class=\"show3d-wrap\"><canvas id=\"show3d\" width=\"640\" height=\"440\" aria-label=\"完成した印鑑（ドラッグで回せる）\"></canvas><span>完成した印鑑（ドラッグで回せる）</span></div>\n        <div class=\"imp-box\" id=\"imp-box\"><img id=\"imp-img\" alt=\"あなたの印影\"></div>\n        <div class=\"row\" hidden><button type=\"button\" class=\"btn ghost small\" id=\"btn-check\">背景を透過表示</button></div>\n        <div>\n          <div hidden><h3>画像として持ち帰る</h3>\n          <div class=\"row\">\n            <button type=\"button\" class=\"btn primary small\" id=\"ex-straight\">透過PNG（まっすぐ）</button>\n            <button type=\"button\" class=\"btn ghost small\" id=\"ex-bow\">透過PNG（お辞儀版）</button>\n            <button type=\"button\" class=\"btn ghost small\" id=\"ex-doc\">稟議書ごと</button>\n          </div></div>\n          <p class=\"hint\">保存できない環境では、印影の画像を長押し（右クリック）して保存してください。</p>\n        </div>\n      </div>\n    </div>\n    <div class=\"cert\">\n      <div class=\"cert-head\">\n        <h2>印相鑑定書</h2>\n        <span class=\"engine\" id=\"engine\">鑑定：朱雀院 印斎</span>\n      </div>\n      <div id=\"k-body\" hidden>\n        <ul class=\"chips key\" id=\"k-chips\"></ul><details class=\"more-stats\"><summary>詳しい数値</summary><ul class=\"chips\" id=\"k-chips-more\"></ul></details>\n        <h3 style=\"font-size:13px;color:var(--muted);margin:0 0 6px\">称号</h3>\n        <ul class=\"titles\" id=\"k-titles\"></ul>\n        <details class=\"collect\"><summary id=\"collect-sum\">集めた称号</summary><ul class=\"collect-list\" id=\"collect-list\"></ul></details>\n        <div class=\"stars\" id=\"k-stars\"></div>\n        <div id=\"k-text\"><span style=\"color:var(--muted)\">鑑定士「朱雀院 印斎」が、あなたの彫りと押し方を見て鑑定します。</span></div>\n        <div class=\"row k-actions\" hidden><button type=\"button\" class=\"btn primary\" id=\"btn-kantei\">鑑定してもらう</button><button type=\"button\" class=\"btn ghost\" id=\"btn-cert\" hidden>鑑定書を画像で保存</button><button type=\"button\" class=\"btn ghost\" id=\"btn-x\" hidden title=\"鑑定書の画像を保存してから、Xの投稿画面を開きます\">Xに投稿（画像も保存）</button></div>\n        <p class=\"note\">※ 鑑定は娯楽です。運勢を保証するものではありません。</p>\n      </div>\n      <div id=\"k-body-empty\" class=\"empty\">押印すると、ここに鑑定書が出ます。</div>\n    </div>\n  </section>\n</main>\n\n<div class=\"master in-stage\" id=\"master\" aria-live=\"polite\">\n  <svg class=\"face3d\" id=\"master-face\" viewBox=\"0 0 120 120\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"親方の源じい（つつくと何か言う）\">\n    <defs>\n      <radialGradient id=\"mBg\" cx=\"50%\" cy=\"42%\" r=\"62%\"><stop offset=\"0\" stop-color=\"#F7F4EB\"/><stop offset=\".7\" stop-color=\"#EDE4D2\"/><stop offset=\"1\" stop-color=\"#D9CBB0\"/></radialGradient>\n      <radialGradient id=\"mVig\" cx=\"50%\" cy=\"50%\" r=\"50%\"><stop offset=\".78\" stop-color=\"#3a2614\" stop-opacity=\"0\"/><stop offset=\"1\" stop-color=\"#3a2614\" stop-opacity=\".45\"/></radialGradient>\n      <radialGradient id=\"mCheek\"><stop offset=\"0\" stop-color=\"#C83228\" stop-opacity=\".55\"/><stop offset=\"1\" stop-color=\"#C83228\" stop-opacity=\"0\"/></radialGradient>\n      <radialGradient id=\"mSkin\" cx=\"45%\" cy=\"38%\" r=\"70%\"><stop offset=\"0\" stop-color=\"#F0D7B8\"/><stop offset=\"1\" stop-color=\"#D9B08A\"/></radialGradient>\n      <filter id=\"mInk\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\"><feTurbulence type=\"fractalNoise\" baseFrequency=\".32\" numOctaves=\"2\" seed=\"3\"/><feDisplacementMap in=\"SourceGraphic\" scale=\"1.1\"/></filter>\n      <filter id=\"mWash\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\"><feTurbulence type=\"fractalNoise\" baseFrequency=\".05\" numOctaves=\"2\" seed=\"8\"/><feDisplacementMap in=\"SourceGraphic\" scale=\"2.6\"/><feGaussianBlur stdDeviation=\".35\"/></filter>\n      <clipPath id=\"mClip\"><circle cx=\"60\" cy=\"60\" r=\"55\"/></clipPath>\n    </defs>\n    <g clip-path=\"url(#mClip)\">\n      <rect width=\"120\" height=\"120\" fill=\"url(#mBg)\"/>\n      <g stroke=\"#8a7a62\" stroke-opacity=\".12\" stroke-width=\".5\" fill=\"none\"><path d=\"M8 30 q12 4 22 -2\"/><path d=\"M80 18 q10 6 26 2\"/><path d=\"M14 96 q8 -4 16 2\"/><path d=\"M92 92 q10 2 18 -4\"/></g>\n      <g id=\"mHead\">\n        <path d=\"M2 124 C8 100 26 92 44 89 L76 89 C94 92 112 100 118 124 Z\" fill=\"#2F3B55\" fill-opacity=\".9\" filter=\"url(#mWash)\"/>\n        <path d=\"M26 104 C30 98 34 95 40 93\" stroke=\"#1C1C1C\" stroke-width=\"1.6\" fill=\"none\" stroke-linecap=\"round\" filter=\"url(#mInk)\" opacity=\".7\"/>\n        <path d=\"M94 104 C90 98 86 95 80 93\" stroke=\"#1C1C1C\" stroke-width=\"1.6\" fill=\"none\" stroke-linecap=\"round\" filter=\"url(#mInk)\" opacity=\".7\"/>\n        <path d=\"M50 79 L50 92 Q60 97 70 92 L70 79 Z\" fill=\"#DDB592\" filter=\"url(#mWash)\"/>\n        <path d=\"M44 90 L60 113\" stroke=\"#F2EBDD\" stroke-width=\"5\" stroke-linecap=\"round\"/><path d=\"M76 90 L60 113\" stroke=\"#F2EBDD\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n        <path d=\"M44 90 L60 113 M76 90 L60 113\" stroke=\"#1C1C1C\" stroke-width=\"1\" fill=\"none\" opacity=\".6\" filter=\"url(#mInk)\"/>\n        <path d=\"M33 52 C27 49 26 62 34 64 Z\" fill=\"url(#mSkin)\" stroke=\"#1C1C1C\" stroke-width=\"1.4\" filter=\"url(#mInk)\"/>\n        <path d=\"M87 52 C93 49 94 62 86 64 Z\" fill=\"url(#mSkin)\" stroke=\"#1C1C1C\" stroke-width=\"1.4\" filter=\"url(#mInk)\"/>\n        <path d=\"M60 21 C80 21 88 37 87 55 C86 73 76 85 60 85 C44 85 34 73 33 55 C32 37 40 21 60 21 Z\" fill=\"url(#mSkin)\" filter=\"url(#mWash)\"/>\n        <g fill=\"none\" stroke=\"#1C1C1C\" stroke-linecap=\"round\" filter=\"url(#mInk)\">\n          <path d=\"M34.5 44 C31.5 58 35 73 47 82\" stroke-width=\"2.2\" opacity=\".8\"/>\n          <path d=\"M85.5 44 C88.5 58 85 73 73 82\" stroke-width=\"2.2\" opacity=\".8\"/>\n          <path d=\"M51 84 Q60 87 69 84\" stroke-width=\"1.6\" opacity=\".6\"/>\n          <path d=\"M45 26 C53 20 68 20 76 27\" stroke-width=\"1.2\" opacity=\".35\"/>\n        </g>\n        <path d=\"M33 47 C29 42 31 35 37 34 C35 39 37 43 39 48 Z\" fill=\"#CFC9BE\" stroke=\"#8e877b\" stroke-width=\".6\" filter=\"url(#mWash)\"/>\n        <path d=\"M87 47 C91 42 89 35 83 34 C85 39 83 43 81 48 Z\" fill=\"#CFC9BE\" stroke=\"#8e877b\" stroke-width=\".6\" filter=\"url(#mWash)\"/>\n        <path d=\"M32 36 C44 30 76 30 88 36 L88 43 C76 37 44 37 32 43 Z\" fill=\"#2F3B55\" filter=\"url(#mWash)\"/>\n        <path d=\"M33 39.5 C45 34 75 34 87 39.5\" stroke=\"#F2EBDD\" stroke-width=\".9\" fill=\"none\" opacity=\".6\"/>\n        <path d=\"M86 37 C95 32 99 39 92 42 C98 45 95 52 88 46 Z\" fill=\"#2F3B55\" filter=\"url(#mWash)\"/>\n        <g fill=\"none\" stroke=\"#1C1C1C\" stroke-width=\".7\" opacity=\".35\" stroke-linecap=\"round\"><path d=\"M34 57 l-3 -1.5 M34 60 l-3 .5 M86 57 l3 -1.5 M86 60 l3 .5\"/></g>\n        <ellipse id=\"mCheekL\" cx=\"42\" cy=\"70\" rx=\"7.5\" ry=\"4.5\" fill=\"url(#mCheek)\" opacity=\".35\"/>\n        <ellipse id=\"mCheekR\" cx=\"78\" cy=\"70\" rx=\"7.5\" ry=\"4.5\" fill=\"url(#mCheek)\" opacity=\".35\"/>\n        <g id=\"mEyeL\" transform=\"translate(47 59)\"></g>\n        <g id=\"mEyeR\" transform=\"translate(73 59) scale(-1 1)\"></g>\n        <g fill=\"none\" stroke-linecap=\"round\">\n          <circle cx=\"48\" cy=\"61\" r=\"8.8\" stroke=\"#3a2614\" stroke-opacity=\".2\" stroke-width=\"2\"/><circle cx=\"74\" cy=\"61\" r=\"8.8\" stroke=\"#3a2614\" stroke-opacity=\".2\" stroke-width=\"2\"/>\n          <g stroke=\"#1C1C1C\" filter=\"url(#mInk)\"><circle cx=\"47\" cy=\"59\" r=\"8.8\" stroke-width=\"1.5\" fill=\"rgba(255,255,255,.07)\"/><circle cx=\"73\" cy=\"59\" r=\"8.8\" stroke-width=\"1.5\" fill=\"rgba(255,255,255,.07)\"/><path d=\"M55.8 58 Q60 56 64.2 58\" stroke-width=\"1.3\"/><path d=\"M38.2 57 L33.5 54 M81.8 57 L86.5 54\" stroke-width=\"1.2\"/></g>\n          <path d=\"M42 54 q2 -2 4 -2.4 M68 54 q2 -2 4 -2.4\" stroke=\"#fff\" stroke-opacity=\".6\" stroke-width=\"1\"/>\n        </g>\n        <g id=\"mBrowL\" transform=\"translate(46 49)\"><path d=\"M-9 1.5 C-7 -4 1 -5 9 -1.5 C4 -.5 -1 0 -7 3.5 Z\" fill=\"#F4EFE6\" stroke=\"#1C1C1C\" stroke-width=\".9\" filter=\"url(#mInk)\"/><path d=\"M-8 1 l-3 1.5 M-5 -1.5 l-2 -2 M0 -2.8 l-.5 -2.2 M5 -2.4 l1 -2\" stroke=\"#6b6358\" stroke-width=\".8\" fill=\"none\" stroke-linecap=\"round\"/></g>\n        <g id=\"mBrowR\" transform=\"translate(74 49) scale(-1 1)\"><path d=\"M-9 1.5 C-7 -4 1 -5 9 -1.5 C4 -.5 -1 0 -7 3.5 Z\" fill=\"#F4EFE6\" stroke=\"#1C1C1C\" stroke-width=\".9\" filter=\"url(#mInk)\"/><path d=\"M-8 1 l-3 1.5 M-5 -1.5 l-2 -2 M0 -2.8 l-.5 -2.2 M5 -2.4 l1 -2\" stroke=\"#6b6358\" stroke-width=\".8\" fill=\"none\" stroke-linecap=\"round\"/></g>\n        <path d=\"M60.5 59 C58.5 64 57 68 61 69.5 C63 69.5 64.2 68.4 63.2 67.2\" fill=\"none\" stroke=\"#1C1C1C\" stroke-width=\"1.6\" stroke-linecap=\"round\" filter=\"url(#mInk)\"/>\n        <path id=\"mMouth\" d=\"M54 79.5 Q60 80.5 66 79.5\" fill=\"none\" stroke=\"#2a1a14\" stroke-width=\"1.7\" stroke-linecap=\"round\" filter=\"url(#mInk)\"/>\n        <path d=\"M47.5 75 C52 71 57.5 71.5 60 74 C62.5 71.5 68 71 72.5 75 C67.5 76.5 63 76.2 60 75.2 C57 76.2 52.5 76.5 47.5 75 Z\" fill=\"#E4DED3\" stroke=\"#7d766a\" stroke-width=\".6\" filter=\"url(#mWash)\"/>\n        <path d=\"M57 84.5 Q60 90 63 84.5\" fill=\"none\" stroke=\"#bdb6aa\" stroke-width=\"2\" stroke-linecap=\"round\" filter=\"url(#mWash)\"/>\n        <path id=\"mSweat\" d=\"M90 44 C92 48 93 50 90.5 51.5 C88 50 88.5 47 90 44 Z\" fill=\"#8fb5cc\" fill-opacity=\".85\" style=\"display:none\"/>\n      </g>\n      <circle cx=\"60\" cy=\"60\" r=\"55\" fill=\"url(#mVig)\"/>\n    </g>\n    <circle cx=\"60\" cy=\"60\" r=\"56.5\" fill=\"none\" stroke=\"#A8843E\" stroke-width=\"2.2\"/>\n    <circle cx=\"60\" cy=\"60\" r=\"59\" fill=\"none\" stroke=\"#1e140f\" stroke-width=\"3.2\"/>\n    <circle cx=\"60\" cy=\"60\" r=\"54.6\" fill=\"none\" stroke=\"#1e140f\" stroke-opacity=\".5\" stroke-width=\"1\"/>\n  </svg>\n  <div class=\"bubble\">\n    <div class=\"nameplate\" id=\"master-who\">源じい</div>\n    <div class=\"bubble-body\">\n      <div class=\"who\"><button type=\"button\" id=\"master-min\" aria-label=\"吹き出しをたたむ\" title=\"たたむ（親方の顔を押すと開く）\">たたむ ×</button></div>\n      <div class=\"say\" id=\"master-say\"></div>\n      <div class=\"choices\" id=\"master-choices\"></div>\n    </div>\n  </div>\n</div>\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n<script>\nsetTimeout(function(){ if(!window.__hankoReady){ var w=document.getElementById('stage'); if(w&&!w.querySelector('.gl-error')){ var d=document.createElement('div'); d.className='gl-error'; d.textContent='3D表示を読み込めませんでした。ページを再読み込みしてください。'; w.appendChild(d);} } }, 9000);\n</script>\n<script type=\"module\">\nimport * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';\n\nconst N=360;                   // 印面の解像度\nconst R=(N/2-6)/(N/2);         // 3D上の印面半径（1単位 ≒ 1cm）\nconst LEN=2.6;                 // 石の長さ\nconst FACE_Y=3.2;              // 印面の高さ（机が0）\nconst DEPTH=.1;              // 彫りの深さ\nconst $=s=>document.querySelector(s);\nconst $$=s=>[...document.querySelectorAll(s)];\nconst clamp=(v,a,b)=>Math.max(a,Math.min(b,v));\nconst pct=v=>Math.round(v*100)+'%';\nconst reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;\nfunction mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}\nfunction hash(s){let h=2166136261;for(const c of String(s)){h^=c.codePointAt(0);h=Math.imul(h,16777619)}return h>>>0}\n\n/* ---------- ノイズ ---------- */\nfunction valueNoise(seed,scale){\n  const rnd=mulberry32(seed), gw=Math.ceil(N/scale)+2, g=new Float32Array(gw*gw);\n  for(let i=0;i<g.length;i++) g[i]=rnd();\n  const o=new Float32Array(N*N);\n  for(let y=0;y<N;y++){ const gy=y/scale, y0=gy|0, fy=gy-y0, sy=fy*fy*(3-2*fy);\n    for(let x=0;x<N;x++){ const gx=x/scale, x0=gx|0, fx=gx-x0, sx=fx*fx*(3-2*fx);\n      const a=g[y0*gw+x0], b=g[y0*gw+x0+1], c=g[(y0+1)*gw+x0], d=g[(y0+1)*gw+x0+1];\n      o[y*N+x]=a+(b-a)*sx+(c-a)*sy+(a-b-c+d)*sx*sy; } }\n  return o;\n}\nfunction fbm(seed){ const a=valueNoise(seed,46), b=valueNoise(seed+7,13), c=valueNoise(seed+13,4), r=mulberry32(seed+21), o=new Float32Array(N*N); for(let i=0;i<o.length;i++) o[i]=a[i]*.45+b[i]*.3+c[i]*.15+r()*.1; return o; }\nfunction boxBlur(src,R){\n  const tmp=new Float32Array(N*N), out=new Float32Array(N*N), w=2*R+1;\n  for(let y=0;y<N;y++){ let s=0; for(let x=-R;x<=R;x++) s+=src[y*N+clamp(x,0,N-1)]; for(let x=0;x<N;x++){ tmp[y*N+x]=s/w; s+=src[y*N+Math.min(N-1,x+R+1)]-src[y*N+Math.max(0,x-R)]; } }\n  for(let x=0;x<N;x++){ let s=0; for(let y=-R;y<=R;y++) s+=tmp[clamp(y,0,N-1)*N+x]; for(let y=0;y<N;y++){ out[y*N+x]=s/w; s+=tmp[Math.min(N-1,y+R+1)*N+x]-tmp[Math.max(0,y-R)*N+x]; } }\n  return out;\n}\nconst stone=fbm(12345), stone2=fbm(777), fine=valueNoise(555,2);\nconst nzAt=(arr,x,y)=>arr[(((y%N)+N)%N)*N+(((x%N)+N)%N)];\n\n/* ---------- 形 ---------- */\nfunction shapePath(ctx,shape,inset){\n  const c=N/2, r=N/2-6-inset; ctx.beginPath();\n  if(shape==='round') ctx.arc(c,c,r,0,Math.PI*2);\n  else if(shape==='square'){ const k=Math.max(2,14-inset*.5); if(ctx.roundRect) ctx.roundRect(c-r,c-r,r*2,r*2,k); else ctx.rect(c-r,c-r,r*2,r*2); }\n  else ctx.ellipse(c,c,r*.74,r,0,0,Math.PI*2);\n}\nfunction inFace(x,z){ // ワールド座標（印面上）\n  if(state.shape==='round') return x*x+z*z<R*R;\n  if(state.shape==='square') return Math.abs(x)<R&&Math.abs(z)<R;\n  return (x/(R*.74))**2+(z/R)**2<1;\n}\nfunction readMask(x){ const d=x.getImageData(0,0,N,N).data, m=new Uint8Array(N*N); for(let i=0;i<N*N;i++) m[i]=d[i*4+3]>110?1:0; return m; }\nfunction shapeMasks(shape){\n  const cv=document.createElement('canvas'); cv.width=cv.height=N; const x=cv.getContext('2d',{willReadFrequently:true});\n  x.fillStyle='#000'; shapePath(x,shape,0); x.fill(); const inside=readMask(x);\n  x.clearRect(0,0,N,N); shapePath(x,shape,11); x.fill(); const core=readMask(x);\n  const ring=new Uint8Array(N*N); let ic=0, rc=0;\n  for(let i=0;i<N*N;i++) if(inside[i]){ ic++; if(!core[i]){ ring[i]=1; rc++; } }\n  return {inside,ring,insideCount:ic,ringCount:rc};\n}\n\n/* ---------- 上司の印（稟議書用） ---------- */\nfunction drawName(x,name){\n  const chars=[...name], n=chars.length, c=N/2, w=(N/2-6)*1.22, h=(N/2-6)*1.62;\n  x.font='800 100px \"Shippori Mincho B1\",\"Hiragino Mincho ProN\",\"Yu Mincho\",serif'; x.fillStyle='#000'; x.strokeStyle='#000';\n  chars.forEach((ch,k)=>{ const m=x.measureText(ch), L=m.actualBoundingBoxLeft||0, Rr=m.actualBoundingBoxRight||100, A=m.actualBoundingBoxAscent||88, D=m.actualBoundingBoxDescent||12;\n    let sx=w*.92/Math.max(1,L+Rr), sy=(h/n)*.92/Math.max(1,A+D); if(sx/sy>2) sx=sy*2;\n    x.save(); x.translate(c,c-h/2+h/n*(k+.5)); x.scale(sx,sy); x.lineWidth=2.4/((sx+sy)/2); x.fillText(ch,-(Rr-L)/2,(A-D)/2); x.strokeText(ch,-(Rr-L)/2,(A-D)/2); x.restore(); });\n}\nfunction bossSurface(name){\n  const cv=document.createElement('canvas'); cv.width=cv.height=N; const x=cv.getContext('2d',{willReadFrequently:true});\n  x.save(); shapePath(x,'round',17); x.clip(); drawName(x,name); x.restore();\n  x.lineWidth=12; x.strokeStyle='#000'; shapePath(x,'round',6); x.stroke(); return readMask(x);\n}\n\n/* ---------- 印影 ---------- */\nfunction makeImpression(surface,ink,pressure,seed){\n  const cv=document.createElement('canvas'); cv.width=cv.height=N; const x=cv.getContext('2d'), img=x.createImageData(N,N), d=img.data;\n  let surf=0; for(let i=0;i<N*N;i++) if(surface[i]) surf++;\n  if(ink<.03||surf===0){ x.putImageData(img,0,0); return {canvas:cv,coverage:0,blot:0}; }\n  const nz=fbm(seed), fn=valueNoise(seed+99,3), r=mulberry32(seed), a=r()*Math.PI*2, dx=Math.cos(a), dy=Math.sin(a);\n  const kas=clamp((.42-ink)/.42,0,1)*.75+clamp((.42-pressure)/.42,0,1)*.6, tilt=.9*clamp(1-pressure,0,1)+.15;\n  const blot=clamp((ink-.8)/.4,0,1)*.9+clamp((pressure-1)/.35,0,1)*.7;\n  const m=new Float32Array(N*N); let hit=0;\n  for(let i=0;i<N*N;i++){ if(!surface[i]) continue; const g=((i%N)/N-.5)*dx+(((i/N)|0)/N-.5)*dy; if(nz[i]>.18+kas+g*tilt*.5){ m[i]=1; hit++; } }\n  let out=m;\n  if(blot>.02){ const Rb=Math.max(1,Math.round(1+blot*4)), b=boxBlur(boxBlur(m,Rb),Rb); out=new Float32Array(N*N); for(let i=0;i<N*N;i++){ const t=.5-blot*.3+(fn[i]-.5)*.3; out[i]=m[i]?1:(b[i]>t?.8:0); } }\n  for(let i=0;i<N*N;i++) if(out[i]>0){ const o=i*4, v=fn[i]; d[o]=186+v*24; d[o+1]=26+v*14; d[o+2]=34+v*12; d[o+3]=(.78+nz[i]*.2)*255*out[i]; }\n  x.putImageData(img,0,0); return {canvas:cv,coverage:hit/surf,blot};\n}\nfunction paintPrint(cv,mask){\n  const x=cv.getContext('2d'), img=x.createImageData(N,N), d=img.data;\n  for(let i=0;i<N*N;i++) if(mask[i]){ const o=i*4, v=stone[i]; d[o]=188+v*20; d[o+1]=28+v*10; d[o+2]=36+v*8; d[o+3]=235; }\n  x.clearRect(0,0,N,N); x.putImageData(img,0,0);\n}\n\n/* ---------- 石 ---------- */\nconst STONES={\n  seiden:{label:'青田石', base:[166,184,138], vein:[98,122,84],  carv:[226,232,208], chip:[0xe4e1c8,0xcfcca6,0xb3b58a], rough:.3, brittle:1, note:'青田石は柔らかくて素直な石じゃ。初めてにはちょうどええ。'},\n  jusan: {label:'寿山石', base:[228,194,152], vein:[172,98,66],   carv:[243,228,206], chip:[0xf1dfc6,0xddbb92,0xc28c62], rough:.28, brittle:.75, note:'寿山石か、ええ石を選んだな。粘りがあって欠けにくい。'},\n  barin: {label:'巴林石', base:[216,178,124], vein:[160,52,44],   carv:[241,224,200], chip:[0xefdcc0,0xd6ad7a,0xb45a46], rough:.26, brittle:1.35, note:'巴林石は硬うて欠けやすい。刀は浅く、何度も入れるんじゃ。'}\n};\nconst SHAPE_LABEL={round:'丸',square:'角',oval:'小判'};\nfunction marble(S,x,y,sx,sy){\n  const n=nzAt(stone,x*sx|0,y*sy|0), n2=nzAt(stone2,x*sx|0,y*sy|0);\n  const v=Math.abs(Math.sin(x*.013+y*.021+(n*2.2+n2*1.4)*4.2));\n  const vein=Math.pow(1-v,9)*.9, s=.9+.18*(n-.5);\n  return [0,1,2].map(k=>S.base[k]*s*(1-vein)+S.vein[k]*vein);\n}\nfunction genStone(key){\n  const S=STONES[key], r=mulberry32(hash(key));\n  const mk=(w,h)=>{ const c=document.createElement('canvas'); c.width=w; c.height=h; return c; };\n  const raw=mk(N,N), wash=mk(N,N), carv=mk(N,N), body=mk(512,512);\n  const fill=(cv,fn)=>{ const x=cv.getContext('2d'), im=x.createImageData(cv.width,cv.height); for(let y=0;y<cv.height;y++) for(let X=0;X<cv.width;X++){ const o=(y*cv.width+X)*4, c=fn(X,y); im.data[o]=c[0]; im.data[o+1]=c[1]; im.data[o+2]=c[2]; im.data[o+3]=255; } x.putImageData(im,0,0); };\n  fill(raw,(x,y)=>marble(S,x,y,1,1).map(v=>v*.97));\n  fill(wash,(x,y)=>{ const n=nzAt(fine,x,y), st=nzAt(stone,x*3,y*.25); const s=.86+.16*(st-.5)+.08*(n-.5); return [198*s,62*s,44*s]; }); // 朱墨（横の刷毛目）\n  fill(carv,(x,y)=>{ const n=nzAt(fine,x,y), m=nzAt(stone,x,y); const s=.8+.38*(n-.5)+.14*(m-.5); return S.carv.map(v=>v*s); });\n  fill(body,(x,y)=>{ const c=marble(S,x,y,N/512*1.4,N/512*.7); return c.map(v=>clamp(v*(1+(r()<.004?-.25:0)),0,255)); });\n  return {raw,wash,carv,body};\n}\n\n/* ---------- 状態 ---------- */\nconst state={\n  step:1, voice:'craft', phase:'paint', shape:'round', mat:'seiden', masks:null, stoneCv:null, paintT:0,\n  tool:'f3', noFlip:false, style:null,\n  carveMs:0, strokes:0, inkStrokes:0, spinDeg:0, regrinds:0, review:null,\n  carved:new Uint8Array(N*N), inkMask:new Uint8Array(N*N), carvedCount:0, rimCount:0, inkCount:0,\n  ink:0, angle:0, pressCount:0, last:null, stamps:[], undo:[]\n};\nconst toolInfo=t=>t==='rotate'?{kind:'rotate',r:0}:t[0]==='f'?{kind:'fude',r:+t.slice(1)*.9}:{kind:'knife',r:+t.slice(1)};\n\n/* ---------- 印面のキャンバス ---------- */\nconst mkC=()=>{ const c=document.createElement('canvas'); c.width=c.height=N; return c; };\nconst Hc=mkC(), hx=Hc.getContext('2d',{willReadFrequently:true});   // 高さ（白=面、黒=彫り）\nconst Ac=mkC(), ax=Ac.getContext('2d');                               // 彫った所のアルファ\nconst Ic=mkC(), ix=Ic.getContext('2d',{willReadFrequently:true});   // 墨（布字）\nconst Cc=mkC(), cx=Cc.getContext('2d');                               // 合成した色\nconst Tc=mkC(), tx=Tc.getContext('2d');\nconst Nc=mkC(), nx=Nc.getContext('2d');                               // 法線\n\n/* ---------- 3D ---------- */\nconst glCv=$('#gl'), stageEl=$('#stage');\nlet renderer=null;\ntry{ renderer=new THREE.WebGLRenderer({canvas:glCv,antialias:true}); }catch(e){}\nwindow.__hankoReady=true; document.querySelectorAll('.gl-error').forEach(e=>e.remove()); // 遅れて読めた時は、出しておいたお詫びを消す\nif(!renderer){ const d=document.createElement('div'); d.className='gl-error'; d.textContent='この端末では3D表示を使えません。'; stageEl.appendChild(d); throw new Error('no webgl'); }\nrenderer.setPixelRatio(Math.min(devicePixelRatio||1,2));\nrenderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap;\nconst scene=new THREE.Scene();\nscene.background=new THREE.Color(0x0b0705); scene.fog=new THREE.FogExp2(0x0b0705,.034);\nconst camera=new THREE.PerspectiveCamera(34,16/9,.1,120);\nscene.add(new THREE.HemisphereLight(0xffe2c0,0x120a06,.28));\nconst lamp=new THREE.SpotLight(0xffc98c,760,0,Math.PI/6.2,.75,2);\nlamp.position.set(-5,12,5); lamp.target.position.set(0,FACE_Y,0); lamp.castShadow=true;\nlamp.shadow.mapSize.set(2048,2048); lamp.shadow.bias=-.0003; lamp.shadow.normalBias=.02; lamp.shadow.camera.near=4; lamp.shadow.camera.far=30;\nscene.add(lamp,lamp.target);\nconst fillL=new THREE.DirectionalLight(0x8fa2bc,.14); fillL.position.set(7,6,-5); scene.add(fillL);\n\nconst heightTex=new THREE.CanvasTexture(Hc), colorTex=new THREE.CanvasTexture(Cc), normalTex=new THREE.CanvasTexture(Nc);\ncolorTex.colorSpace=THREE.SRGBColorSpace; [heightTex,colorTex,normalTex].forEach(t=>t.anisotropy=4);\n\nconst seal=new THREE.Group(); seal.position.y=FACE_Y; scene.add(seal);\nconst faceGeo=new THREE.PlaneGeometry(2,2,240,240); faceGeo.rotateX(-Math.PI/2);\nconst faceMat=new THREE.MeshStandardMaterial({roughnessMap:null,map:colorTex,displacementMap:heightTex,displacementScale:DEPTH,displacementBias:-DEPTH,normalMap:normalTex,normalScale:new THREE.Vector2(1.3,1.3),alphaTest:.5,roughness:.9,metalness:0});\nconst face=new THREE.Mesh(faceGeo,faceMat); face.receiveShadow=true; seal.add(face);\nconst ringGeo=new THREE.RingGeometry(.88,1,48); ringGeo.rotateX(-Math.PI/2);\nconst brushRing=new THREE.Mesh(ringGeo,new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.45,depthTest:false}));\nbrushRing.renderOrder=5; brushRing.visible=false; seal.add(brushRing);\n\n/* 机と道具 */\nfunction canvasTex(w,h,draw,repeat){ const c=document.createElement('canvas'); c.width=w; c.height=h; draw(c.getContext('2d'),w,h); const t=new THREE.CanvasTexture(c); t.colorSpace=THREE.SRGBColorSpace; t.anisotropy=8; if(repeat){ t.wrapS=t.wrapT=THREE.RepeatWrapping; t.repeat.set(repeat[0],repeat[1]); } return t; }\nfunction woodTex(base,seed,w=512,h=512){ return canvasTex(w,h,(x,W,H)=>{ const im=x.createImageData(W,H), r=mulberry32(seed);\n  for(let y=0;y<H;y++) for(let X=0;X<W;X++){ const o=(y*W+X)*4, n=nzAt(stone,X*.7|0,y*.18|0), n2=nzAt(stone2,X|0,y|0); const s=.78+.14*Math.sin(X*.11+n*9)+.1*(n2-.5)+(r()<.002?-.15:0); im.data[o]=base[0]*s; im.data[o+1]=base[1]*s; im.data[o+2]=base[2]*s; im.data[o+3]=255; }\n  x.putImageData(im,0,0); }); }\nconst deskTex=woodTex([88,58,38],3,1024,1024); deskTex.wrapS=deskTex.wrapT=THREE.MirroredRepeatWrapping; deskTex.repeat.set(3,2);\nconst desk=new THREE.Mesh(new THREE.PlaneGeometry(70,46).rotateX(-Math.PI/2),new THREE.MeshStandardMaterial({map:deskTex,roughness:.72}));\ndesk.receiveShadow=true; scene.add(desk);\n// 石のザラつき（細かい凹凸）\nconst grainTex=canvasTex(256,256,(x,W,H)=>{ const im=x.createImageData(W,H), r=mulberry32(77); for(let i=0;i<W*H;i++){ const v=110+r()*90+(r()<.03?-60:0), o=i*4; im.data[o]=im.data[o+1]=im.data[o+2]=v; im.data[o+3]=255; } x.putImageData(im,0,0); },[3,3]);\ngrainTex.colorSpace=THREE.NoColorSpace;\n// 面取りした箱（木目は寸法に合わせて引き伸ばさない）\nfunction bevelBox(w,h,d,mat,bev=.07){\n  const sh=new THREE.Shape(); sh.moveTo(-w/2+bev,-h/2+bev); sh.lineTo(w/2-bev,-h/2+bev); sh.lineTo(w/2-bev,h/2-bev); sh.lineTo(-w/2+bev,h/2-bev); sh.closePath();\n  const g=new THREE.ExtrudeGeometry(sh,{depth:d-bev*2,bevelEnabled:true,bevelThickness:bev,bevelSize:bev,bevelSegments:2,curveSegments:1});\n  g.translate(0,0,-(d-bev*2)/2); g.computeVertexNormals();\n  const m=new THREE.Mesh(g,mat); m.castShadow=m.receiveShadow=true; return m;\n}\nconst viseTex=woodTex([120,64,40],9); viseTex.wrapS=viseTex.wrapT=THREE.MirroredRepeatWrapping; viseTex.repeat.set(.12,.12);\nconst viseMat=new THREE.MeshStandardMaterial({map:viseTex,roughness:.62});\nlet viseGroup=null, viseTops=[], viseJaws=[];\nfunction buildVise(){\n  if(viseGroup){ scene.remove(viseGroup); viseGroup.traverse(o=>o.geometry&&o.geometry.dispose()); }\n  viseGroup=new THREE.Group();\n  const hw=state.shape==='oval'?R*.74:R, add=(w,h,d,x,y,z)=>{ const m=bevelBox(w,h,d,viseMat,Math.min(.08,Math.min(w,h,d)*.12)); m.position.set(x,y,z); viseGroup.add(m); return m; };\n  add(6,.6,3.6,0,.3,0);                                          // 台\n  const jw=1.5, jx=hw+jw/2+.02;\n  const jl=add(jw,1.9,3,-jx,.6+.95,0), jr=add(jw,1.9,3,jx,.6+.95,0);          // 挟み板\n  const wedge=add(.35,1.4,2.4,jx+jw/2+.18,.6+.7,0); wedge.rotation.z=.12; // くさび\n  viseJaws=[[jl,-jx,-1],[jr,jx,1],[wedge,wedge.position.x,1]];\n  viseTops=[{x0:-6/2,x1:6/2,z0:-1.8,z1:1.8,y:.6},{x0:-jx-jw/2,x1:-jx+jw/2,z0:-1.5,z1:1.5,y:2.5},{x0:jx-jw/2,x1:jx+jw/2,z0:-1.5,z1:1.5,y:2.5}];\n  scene.add(viseGroup);\n}\nfunction floorAt(x,z){ let y=0; for(const t of viseTops) if(x>t.x0&&x<t.x1&&z>t.z0&&z<t.z1) y=Math.max(y,t.y); if(inFace(x,z)) y=Math.max(y,FACE_Y); return y; }\nlet bodyGroup=null;\n/* 完成品の鑑賞（鑑定画面） */\nconst showCv=document.getElementById('show3d');\nconst sR=new THREE.WebGLRenderer({canvas:showCv,antialias:true,alpha:true}); sR.setPixelRatio(1); sR.setSize(640,440,false);\nconst sScene=new THREE.Scene(), sCam=new THREE.PerspectiveCamera(30,640/440,.1,50); sCam.position.set(0,2.6,5.6); sCam.lookAt(0,-.7,0);\nsScene.add(new THREE.HemisphereLight(0xfff0dc,0x2a1c14,.9));\n{ const k=new THREE.DirectionalLight(0xffdcb0,2.6); k.position.set(-3,5,3); sScene.add(k); const rl=new THREE.DirectionalLight(0x9fb8e0,1.2); rl.position.set(3,2,-3); sScene.add(rl); }\nconst showGroup=new THREE.Group(); sScene.add(showGroup);\nconst showView={rot:.6,tilt:.25,drag:null};\nfunction rebuildShow(){\n  showGroup.clear();\n  showGroup.add(new THREE.Mesh(faceGeo,faceMat));\n  if(bodyGroup) bodyGroup.children.forEach(c=>{ const m=new THREE.Mesh(c.geometry,c.material); m.position.copy(c.position); m.rotation.copy(c.rotation); m.scale.copy(c.scale); showGroup.add(m); });\n}\nshowCv.addEventListener('pointerdown',e=>{ showCv.setPointerCapture(e.pointerId); showView.drag={x:e.clientX,y:e.clientY}; });\nshowCv.addEventListener('pointermove',e=>{ if(!showView.drag) return; showView.rot+=(e.clientX-showView.drag.x)*.01; showView.tilt=clamp(showView.tilt+(e.clientY-showView.drag.y)*.006,-.6,1.1); showView.drag={x:e.clientX,y:e.clientY}; });\nshowCv.addEventListener('pointerup',()=>showView.drag=null); showCv.addEventListener('pointercancel',()=>showView.drag=null);\nfunction updateShow(dt){\n  if(showCv.offsetParent===null) return;\n  if(!showView.drag&&!reduceMotion) showView.rot+=dt*.5;\n  showGroup.rotation.set(showView.tilt,showView.rot,0);\n  sR.render(sScene,sCam);\n}\nfunction buildBody(){\n  if(bodyGroup){ seal.remove(bodyGroup); bodyGroup.traverse(o=>o.geometry&&o.geometry.dispose()); }\n  bodyGroup=new THREE.Group();\n  const S=STONES[state.mat], tex=new THREE.CanvasTexture(state.stoneCv.body); tex.colorSpace=THREE.SRGBColorSpace; tex.wrapS=tex.wrapT=THREE.RepeatWrapping;\n  const mat=new THREE.MeshStandardMaterial({map:tex,bumpMap:grainTex,bumpScale:.4,roughness:Math.min(.84,S.rough+.42),metalness:0});\n  let side;\n  if(state.shape==='square'){ const g=new THREE.BoxGeometry(2*R,LEN,2*R); g.translate(0,-LEN/2,0); side=new THREE.Mesh(g,[mat,mat,new THREE.MeshBasicMaterial({visible:false}),mat,mat,mat]); }\n  else { const g=new THREE.CylinderGeometry(R,R,LEN,96,1,true); g.translate(0,-LEN/2,0); if(state.shape==='oval') g.scale(.74,1,1); side=new THREE.Mesh(g,mat); }\n  if(state.shape!=='square'){ const cg=new THREE.CircleGeometry(R,96); cg.rotateX(Math.PI/2); cg.translate(0,-LEN,0); if(state.shape==='oval') cg.scale(.74,1,1); const cap=new THREE.Mesh(cg,mat); cap.receiveShadow=true; bodyGroup.add(cap); } // 石の尻（押す時に上から見える）\n  side.castShadow=side.receiveShadow=true; bodyGroup.add(side);\n  const dot=new THREE.Mesh(new THREE.SphereGeometry(.05,16,12),new THREE.MeshStandardMaterial({color:0xc21f2b,roughness:.4}));\n  dot.position.set(0,-.25,-R); bodyGroup.add(dot);                // アタリ（印面の上）\n  seal.add(bodyGroup);\n}\nlet deskClutter=[];\nfunction buildProps(){\n  const g=new THREE.Group();\n  const cast=m=>{ m.castShadow=m.receiveShadow=true; return m; };\n  // 印稿の和紙\n  const paperTex=canvasTex(1024,720,(x,W,H)=>{\n    x.fillStyle='#f2ecdf'; x.fillRect(0,0,W,H); const r=mulberry32(5);\n    for(let k=0;k<500;k++){ x.strokeStyle=`rgba(120,100,70,${.03+r()*.05})`; x.lineWidth=.6+r(); x.beginPath(); const a=r()*W, b=r()*H; x.moveTo(a,b); x.lineTo(a+(r()-.5)*40,b+(r()-.5)*40); x.stroke(); }\n    x.fillStyle='#3a302a'; x.font='400 54px \"Yuji Syuku\",serif'; x.fillText('印稿',60,90);\n    for(let k=0;k<3;k++){ const cx0=230+k*280, cy0=380;\n      x.strokeStyle='rgba(190,40,40,.85)'; x.lineWidth=7; x.beginPath(); if(k===1) x.rect(cx0-95,cy0-95,190,190); else x.arc(cx0,cy0,98,0,Math.PI*2); x.stroke();\n      x.strokeStyle='rgba(30,24,20,.85)'; x.lineWidth=9; x.lineCap='round';\n      for(let s=0;s<5;s++){ x.beginPath(); const y0=cy0-60+s*28+r()*6; x.moveTo(cx0-55+r()*20,y0); x.lineTo(cx0+55-r()*20,y0+(r()-.5)*10); x.stroke(); }\n      x.beginPath(); x.moveTo(cx0+(r()-.5)*20,cy0-70); x.lineTo(cx0+(r()-.5)*20,cy0+70); x.stroke();\n      x.strokeStyle='rgba(80,70,60,.4)'; x.lineWidth=1.5; x.beginPath(); x.moveTo(cx0-110,cy0+130); x.lineTo(cx0+110,cy0+130); x.stroke(); }\n  });\n  const paper=cast(new THREE.Mesh(new THREE.PlaneGeometry(10,7).rotateX(-Math.PI/2),new THREE.MeshStandardMaterial({map:paperTex,roughness:.95})));\n  paper.position.set(-8.6,.012,3.2); paper.rotation.y=.18; g.add(paper);\n  // 硯と墨\n  const suzuri=cast(new THREE.Mesh(new THREE.BoxGeometry(3.2,.7,4.8),new THREE.MeshStandardMaterial({color:0x26272a,roughness:.5})));\n  suzuri.position.set(7.6,.35,2.8); suzuri.rotation.y=-.2; g.add(suzuri);\n  const sumi=new THREE.Mesh(new THREE.PlaneGeometry(2.4,3).rotateX(-Math.PI/2),new THREE.MeshStandardMaterial({color:0x08080a,roughness:.08}));\n  sumi.position.set(7.6,.712,2.6); sumi.rotation.y=-.2; g.add(sumi);\n  const bar=cast(new THREE.Mesh(new THREE.BoxGeometry(.7,.5,2.6),new THREE.MeshStandardMaterial({color:0x1a1a1c,roughness:.6})));\n  bar.position.set(9.9,.25,1.2); bar.rotation.y=.5; g.add(bar); deskClutter=[suzuri,sumi,bar];\n  // 朱肉\n  const potMat=new THREE.MeshPhysicalMaterial({color:0xf3efe6,roughness:.25,clearcoat:.6});\n  const pot=cast(new THREE.Mesh(new THREE.CylinderGeometry(1.7,1.8,1,48),potMat)); pot.position.set(6.4,.5,-3.4); // 作業中は使わない朱肉は置かない（押印用は別にある）\n  const shu=new THREE.Mesh(new THREE.CircleGeometry(1.45,48).rotateX(-Math.PI/2),new THREE.MeshStandardMaterial({color:0xb2141f,roughness:.9})); shu.position.set(6.4,.98,-3.4);\n  // 筆（置いてある）\n  const brush=new THREE.Group();\n  const bamboo=new THREE.MeshStandardMaterial({color:0xb08a52,roughness:.5}), hair=new THREE.MeshStandardMaterial({color:0x111111,roughness:.8});\n  const bh=cast(new THREE.Mesh(new THREE.CylinderGeometry(.12,.12,6,16),bamboo)); bh.rotation.z=Math.PI/2; brush.add(bh);\n  const bt=cast(new THREE.Mesh(new THREE.ConeGeometry(.16,.9,16),hair)); bt.rotation.z=Math.PI/2; bt.position.x=-3.4; brush.add(bt);\n  // （筆は筆掛けに移した）\n  // 予備の印刀\n\n  // 奥の棚と壁\n  const wall=new THREE.Mesh(new THREE.PlaneGeometry(80,30),new THREE.MeshStandardMaterial({color:0x2a2018,roughness:.95})); wall.position.set(0,12,-16); g.add(wall);\n  const shelfMat=new THREE.MeshStandardMaterial({color:0x3a2a1c,roughness:.8});\n  for(let s=0;s<3;s++){ const sh=cast(new THREE.Mesh(new THREE.BoxGeometry(30,.4,3),shelfMat)); sh.position.set(0,5+s*4.5,-14.4); g.add(sh);\n    for(let b=0;b<12;b++){ const box=cast(new THREE.Mesh(new THREE.BoxGeometry(1.6,2.2+((b*7+s)%3)*.5,2),new THREE.MeshStandardMaterial({color:[0x5a3e2a,0x7a5a3a,0x463226][(b+s)%3],roughness:.85}))); box.position.set(-13+b*2.3,5.2+s*4.5+box.geometry.parameters.height/2,-14.4); g.add(box); } }\n  scene.add(g);\n}\nfunction makeKnife(scale=1,active=true){\n  const k=new THREE.Group();\n  const steel=new THREE.MeshStandardMaterial({color:0xc9ccd0,metalness:.9,roughness:.28});\n  const blade=new THREE.Mesh(new THREE.BoxGeometry(.18*scale,.62,.045),steel); blade.position.y=.31; k.add(blade);\n  const edge=new THREE.Mesh(new THREE.BoxGeometry(.18*scale,.08,.03),new THREE.MeshStandardMaterial({color:0xf2f4f6,metalness:1,roughness:.12})); edge.position.y=.04; edge.rotation.z=.35; k.add(edge);\n  const ferr=new THREE.Mesh(new THREE.CylinderGeometry(.1,.1,.14,20),new THREE.MeshStandardMaterial({color:0x8a6a3a,metalness:.8,roughness:.35})); ferr.position.y=.68; k.add(ferr);\n  const cordTex=canvasTex(64,256,(x,W,H)=>{ for(let y=0;y<H;y+=6){ x.fillStyle=y%12?'#2b2a33':'#3b3a46'; x.fillRect(0,y,W,6);} },[1,6]);\n  const handle=new THREE.Mesh(new THREE.CylinderGeometry(.095,.09,1.5,20),new THREE.MeshStandardMaterial({map:cordTex,roughness:.85})); handle.position.y=.75+.75; k.add(handle);\n  k.traverse(o=>{ if(o.isMesh) o.castShadow=true; });\n  if(!active) k.scale.setScalar(1);\n  return k;\n}\nfunction makeFude(){\n  const f=new THREE.Group();\n  const tip=new THREE.Mesh(new THREE.ConeGeometry(.1,.45,16),new THREE.MeshStandardMaterial({color:0x0c0c0c,roughness:.7})); tip.rotation.x=Math.PI; tip.position.y=.225; f.add(tip);\n  const h=new THREE.Mesh(new THREE.CylinderGeometry(.075,.075,2.2,16),new THREE.MeshStandardMaterial({color:0xb08a52,roughness:.5})); h.position.y=.45+1.1; f.add(h);\n  f.traverse(o=>{ if(o.isMesh) o.castShadow=true; });\n  return f;\n}\n/* 作業台の道具（クリックで持ち替える） */\nconst rackPick=[], rackItems={};\nconst TOOL_LABEL={bell:'呼び鈴（できたと思ったら鳴らす）',pad:'朱肉（クリックでトントン）',f6:'筆・太',f3:'筆・中',f2:'筆・細',k14:'印刀・大（荒彫り）',k7:'印刀・中',k3:'印刀・小（仕上げ）',k1:'印刀・極細'};\nfunction buildRack(){\n  const wood=new THREE.MeshStandardMaterial({color:0x4e321f,roughness:.6});\n  const box=(w,h,d,m)=>{ const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m); o.castShadow=o.receiveShadow=true; return o; };\n  const pickBox=(w,h,d,tool,parent,pos)=>{ const p=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),new THREE.MeshBasicMaterial({visible:false})); p.position.copy(pos); p.userData.tool=tool; parent.add(p); rackPick.push(p); };\n  // 筆掛け（左）\n  const fk=new THREE.Group(); fk.position.set(-4.3,0,.5); fk.rotation.y=.18; fk.scale.setScalar(.74); scene.add(fk);\n  const b0=box(3,.3,1.1,wood); b0.position.y=.15; fk.add(b0);\n  for(const x of [-1.3,1.3]){ const p=box(.22,4.2,.22,wood); p.position.set(x,2.25,0); fk.add(p); }\n  const bar=box(2.9,.2,.24,wood); bar.position.y=4.3; fk.add(bar);\n  [['f6',.15,2.2,-.75],['f3',.11,1.95,0],['f2',.075,1.7,.72]].forEach(([t,r,len,x])=>{\n    const g=new THREE.Group(); g.position.set(x,4.18,0); fk.add(g);\n    const bamboo=new THREE.MeshStandardMaterial({color:0xb08a52,roughness:.45}), hair=new THREE.MeshStandardMaterial({color:0x111111,roughness:.75});\n    const loop=new THREE.Mesh(new THREE.TorusGeometry(.07,.012,6,16),new THREE.MeshStandardMaterial({color:0xc21f2b})); loop.position.y=-.02; g.add(loop);\n    const h=new THREE.Mesh(new THREE.CylinderGeometry(r,r*.92,len,16),bamboo); h.position.y=-.1-len/2; h.castShadow=true; g.add(h);\n    const tip=new THREE.Mesh(new THREE.ConeGeometry(r*1.35,len*.32,16),hair); tip.rotation.x=Math.PI; tip.position.y=-.1-len-len*.16; tip.castShadow=true; g.add(tip);\n    rackItems[t]=g; pickBox(.5,len*1.4+.2,.5,t,fk,new THREE.Vector3(x,4.1-(len*1.3)/2,0));\n  });\n  // 刀立て（右）\n  const kt=new THREE.Group(); kt.position.set(3.7,0,-1.3); kt.rotation.y=.5; scene.add(kt);\n  const blk=box(3.9,1.1,1.45,wood); blk.position.y=.55; kt.add(blk);\n  [['k14',1.5,-1.5],['k7',1.15,-.92],['k3',.85,-.36],['k1',.6,.18]].forEach(([t,s,x],i)=>{\n    const k=makeKnife(s); k.position.set(x,.98,0); k.rotation.z=(i-1.5)*.06; k.scale.set(.9+s*.15,1,.9+s*.15); kt.add(k);\n    rackItems[t]=k; pickBox(.5,2.6,.6,t,kt,new THREE.Vector3(x,1.95,0));\n  });\n  // 呼び鈴（完成したら自分で鳴らす）\n  const bell=new THREE.Group(); bell.position.set(1.2,1.1,0); kt.add(bell);\n  const brass=new THREE.MeshStandardMaterial({color:0xc9a24a,metalness:.9,roughness:.25});\n  const bb=new THREE.Mesh(new THREE.CylinderGeometry(.6,.66,.18,32),new THREE.MeshStandardMaterial({color:0x2a1c14,roughness:.5})); bb.position.y=.09; bb.castShadow=true; bell.add(bb);\n  const dome=new THREE.Mesh(new THREE.SphereGeometry(.5,32,16,0,Math.PI*2,0,Math.PI/2),brass); dome.position.y=.18; dome.castShadow=true; bell.add(dome);\n  const knob=new THREE.Mesh(new THREE.SphereGeometry(.09,16,12),brass); knob.position.y=.72; bell.add(knob);\n  rackItems.bell=bell; pickBox(1.4,1.2,1.4,'bell',bell,new THREE.Vector3(0,.4,0));\n}\nfunction updateRack(){ for(const t in rackItems) if(t!=='bell') rackItems[t].visible=(t!==state.tool); }\nconst ray3=new THREE.Raycaster();\nfunction rackHit(cx,cy){\n  const r=glCv.getBoundingClientRect(); ray3.setFromCamera(new THREE.Vector2((cx-r.left)/r.width*2-1,-(cy-r.top)/r.height*2+1),camera);\n  const h=ray3.intersectObjects(rackPick,false)[0]; return h?h.object.userData.tool:null;\n}\nlet rackHover=null;\nfunction setRackHover(t,cx,cy){\n  if(rackHover&&rackHover!==t) highlight(rackHover,false);\n  rackHover=t; if(t) highlight(t,true);\n  const tip=$('#tip3d');\n  if(t){ const r=stageEl.getBoundingClientRect(); tip.textContent=TOOL_LABEL[t]+(t===state.tool?'（手に持っている）':''); tip.style.left=(cx-r.left)+'px'; tip.style.top=(cy-r.top)+'px'; tip.hidden=false; }\n  else tip.hidden=true;\n}\nfunction highlight(t,on){ const g=rackItems[t]; if(!g) return; g.traverse(o=>{ if(o.isMesh&&o.material&&'emissive' in o.material){ o.material.emissive.setHex(on?0x553311:0x000000); } }); }\nfunction pickTool(t){\n  ensureAudio(); noise(1800,2,.06,.05);\n  if(t==='bell'){ ringBell(); return; }\n  if(t==='pad'){ if(state.phase==='press') dip(); return; }\n  if(state.phase==='press'){ say('今は押す番じゃ。彫り直すなら「彫りに戻る」と言え。',{force:true,mood:'thinking'}); return; }\n  const isFude=t[0]==='f';\n  if(state.phase==='paint'){ say('まだ朱を塗っとる。ちょっと待て。',{force:true,mood:'worried'}); return; }\n  if(state.phase==='fuji'&&!isFude){ state.pendingKnife=t; askStyle(); return; }\n  if((state.phase==='carve'||state.phase==='review')&&isFude){\n    say('筆に持ち替えるか？布字を書き足すんじゃな。',{force:true,mood:'thinking',choices:[{label:'書き足す',primary:true,fn:()=>{ setPhase('fuji'); selectTool(t); }},{label:'やめとく',fn:()=>say('うむ。',{force:true})}]}); return;\n  }\n  if(state.phase==='review') setPhase('carve');\n  noteSwap(); selectTool(t);\n  const tips={k14:'大刀は荒彫り用じゃ。広いところを一気に落とせ。',k3:'小刀は仕上げ用じゃ。線の際を整えろ。',k1:'極細か。そいつは髪の毛一本ぶんしか彫れんぞ。…気に入った。',f6:'太筆は太い線向きじゃ。',f2:'細筆は細かい字を書くときに使え。'};\n  if(tips[t]) say(tips[t],{key:'tool-'+t,once:true});\n}\nconst knife=makeKnife(1), fude=makeFude(); knife.visible=fude.visible=false; scene.add(knife,fude);\n// 手元の道具は半透明にして、刃先の下が見えるように（影も落とさない）\nconst toolMats=[];\n[knife,fude].forEach(t=>t.traverse(o=>{ if(o.isMesh){ o.castShadow=false; o.material=o.material.clone(); o.material.transparent=true; o.material.depthWrite=false; toolMats.push(o.material); } }));\nfunction setToolAlpha(a){ for(const m of toolMats) m.opacity+=(a-m.opacity)*.35; }\n\n/* 削りかす（石の粒）と粉 */\nconst MAXC=900;\nconst chipMesh=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1,0),new THREE.MeshStandardMaterial({roughness:.9}),MAXC);\nchipMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage); chipMesh.castShadow=true; chipMesh.receiveShadow=true; chipMesh.count=0; chipMesh.frustumCulled=false;\nfor(let i=0;i<MAXC;i++) chipMesh.setColorAt(i,new THREE.Color(1,1,1));\nscene.add(chipMesh);\nconst chips=[];\nconst MAXD=1400, dustPos=new Float32Array(MAXD*3).fill(-100), dustGeo=new THREE.BufferGeometry();\ndustGeo.setAttribute('position',new THREE.BufferAttribute(dustPos,3));\nconst dustMat=new THREE.PointsMaterial({size:.032,color:0xd9cfbd,transparent:true,opacity:.42,depthWrite:false});\nconst dust=new THREE.Points(dustGeo,dustMat); dust.frustumCulled=false; scene.add(dust);\nconst dusts=[]; let dustHead=0;\nconst _m=new THREE.Matrix4(), _q=new THREE.Quaternion(), _s=new THREE.Vector3(), _c=new THREE.Color(), _e=new THREE.Euler();\nlet chipSpawned=0;\nfunction spawnChips(wx,wz,dx,dz,r,count){\n  const S=STONES[state.mat], k=r/7; chipSpawned+=count;\n  for(let n=0;n<count;n++){\n    if(chips.length>=MAXC) chips.shift();\n    const side=Math.random()<.5?-1:1, sp=(.6+Math.random()*1.6)*(.7+k*.35);\n    const size=(.01+Math.random()*.028)*(.45+k*.75);\n    chips.push({p:new THREE.Vector3(wx+(Math.random()-.5)*r/N,FACE_Y+.02,wz+(Math.random()-.5)*r/N),\n      v:new THREE.Vector3(-dz*side*sp+dx*.4*Math.random()+(Math.random()-.5)*.6, (1+Math.random()*2.2)*(.8+k*.25), dx*side*sp+dz*.4*Math.random()+(Math.random()-.5)*.6),\n      rot:new THREE.Euler(Math.random()*6,Math.random()*6,Math.random()*6), w:new THREE.Vector3((Math.random()-.5)*14,(Math.random()-.5)*14,(Math.random()-.5)*14),\n      s:new THREE.Vector3(size*(.7+Math.random()*.6),size*(.4+Math.random()*.5),size*(.7+Math.random()*.6)),\n      col:S.chip[(Math.random()*3)|0], rest:false});\n  }\n  for(let n=0;n<Math.ceil(count*.6);n++){\n    const d=dusts[dustHead]||(dusts[dustHead]={p:new THREE.Vector3(),v:new THREE.Vector3(),life:0});\n    d.p.set(wx+(Math.random()-.5)*r/N*2,FACE_Y+.02,wz+(Math.random()-.5)*r/N*2); d.v.set((Math.random()-.5)*.8,.3+Math.random()*.9,(Math.random()-.5)*.8); d.life=1;\n    dustHead=(dustHead+1)%MAXD;\n  }\n}\nfunction stepParticles(dt){\n  const G=7.5;\n  for(let i=0;i<chips.length;i++){\n    const c=chips[i];\n    if(!c.rest){\n      c.v.y-=G*dt; c.p.addScaledVector(c.v,dt); c.rot.x+=c.w.x*dt; c.rot.y+=c.w.y*dt; c.rot.z+=c.w.z*dt;\n      const fy=floorAt(c.p.x,c.p.z)+c.s.y;\n      if(c.p.y<fy){\n        if(fy-c.p.y>.25&&c.v.y<0&&floorAt(c.p.x,c.p.z)>0){ /* 側面に当たった：外へ弾く */ c.v.x*=-.3; c.v.z*=-.3; c.p.y=Math.max(c.p.y,0); }\n        else { c.p.y=fy; c.v.y*=-.25; c.v.x*=.5; c.v.z*=.5; c.w.multiplyScalar(.5); if(Math.abs(c.v.y)<.35){ c.v.set(0,0,0); c.rest=true; } }\n      }\n    }\n    _q.setFromEuler(c.rot); _m.compose(c.p,_q,c.s); chipMesh.setMatrixAt(i,_m); _c.setHex(c.col); chipMesh.setColorAt(i,_c);\n  }\n  chipMesh.count=chips.length; chipMesh.instanceMatrix.needsUpdate=true; if(chipMesh.instanceColor) chipMesh.instanceColor.needsUpdate=true;\n  for(let i=0;i<dusts.length;i++){\n    const d=dusts[i]; if(!d||d.life<=0){ dustPos[i*3+1]=-100; continue; }\n    d.v.multiplyScalar(.97); d.v.y-=.35*dt; d.p.addScaledVector(d.v,dt); d.life-=dt*.6;\n    dustPos[i*3]=d.p.x; dustPos[i*3+1]=d.life>0?d.p.y:-100; dustPos[i*3+2]=d.p.z;\n  }\n  dustGeo.attributes.position.needsUpdate=true;\n}\nfunction chipsOnFace(){ let n=0; for(const c of chips) if(c.rest&&c.p.y>FACE_Y-.05) n++; return n; }\nfunction blow(){\n  let any=0;\n  for(const c of chips){ if(c.p.y>FACE_Y-.3||Math.hypot(c.p.x,c.p.z)<2.5){ const a=Math.atan2(c.p.z,c.p.x)+(Math.random()-.5)*.8, sp=2.5+Math.random()*3.5; c.v.set(Math.cos(a)*sp,1+Math.random()*2,Math.sin(a)*sp); c.w.set((Math.random()-.5)*16,(Math.random()-.5)*16,(Math.random()-.5)*16); c.rest=false; any++; } }\n  for(let n=0;n<55;n++){ const d=dusts[dustHead]||(dusts[dustHead]={p:new THREE.Vector3(),v:new THREE.Vector3(),life:0}); const a=Math.random()*Math.PI*2, r=Math.random()*R; d.p.set(Math.cos(a)*r,FACE_Y+.03,Math.sin(a)*r); d.v.set(Math.cos(a)*(1+Math.random()*2),.4+Math.random(),Math.sin(a)*(1+Math.random()*2)); d.life=1; dustHead=(dustHead+1)%MAXD; }\n  whoosh(); return any;\n}\n\n/* カメラ */\nconst view={az:0,elev:.74,dist:10.5,tAz:0,tElev:.74,tDist:10.5,auto:false};\nconst TGT=new THREE.Vector3(0,FACE_Y-.2,0); view.tgtT=TGT.clone();\nlet camMoved=false, shake=0;\nfunction applyCam(){ const ce=Math.cos(view.elev); camera.position.set(TGT.x+view.dist*ce*Math.sin(view.az),TGT.y+view.dist*Math.sin(view.elev),TGT.z+view.dist*ce*Math.cos(view.az)); camera.lookAt(TGT); camera.updateMatrixWorld(); }\n// 書く・彫る瞬間はカメラを正面（2πの倍数）へ戻す。斜めのまま書くと、押した印影で字が傾くため\nfunction snapFront(){\n  const tgt=Math.round(view.az/(Math.PI*2))*Math.PI*2;\n  if(Math.abs(view.az-tgt)<.015&&Math.abs(view.tAz-tgt)<.015) return false;\n  view.az=view.tAz=tgt; applyCam(); return true;\n}\nfunction updateCamera(dt){\n  if(view.auto){ const d=.4*dt; view.tAz+=d; if(carving) state.spinDeg+=d*180/Math.PI; }\n  const pa=view.az, pe=view.elev, pd=view.dist;\n  view.az+=(view.tAz-view.az)*.25; view.elev+=(view.tElev-view.elev)*.18; view.dist+=(view.tDist-view.dist)*.18;\n  camMoved=Math.abs(pa-view.az)+Math.abs(pe-view.elev)+Math.abs(pd-view.dist)>1e-5;\n  TGT.lerp(view.tgtT,.12); scene.fog.density+=((state.phase==='press'?.011:.034)-scene.fog.density)*.08;\n  applyCam();\n  if(shake>.01&&!reduceMotion){ camera.position.x+=(Math.random()-.5)*shake*.022; camera.position.y+=(Math.random()-.5)*shake*.018; } shake*=.82;\n}\nfunction resize(){\n  const r=stageEl.getBoundingClientRect(); if(!r.width) return;\n  const was=camera.aspect<1;\n  renderer.setSize(r.width,r.height,false); camera.aspect=r.width/r.height; camera.updateProjectionMatrix();\n  try{ if(P.active&&!P.auto) framePress(); }catch(e){} /* 起動直後は P がまだ無い。押印中は画面の大きさが変わるたびに合わせ直す */\n}\nnew ResizeObserver(resize).observe(stageEl);\n\n/* ---------- 印面の準備と合成 ---------- */\nlet texDirty=false, carveDirty=null;\nfunction compose(){\n  cx.clearRect(0,0,N,N); cx.save(); shapePath(cx,state.shape,0); cx.clip();\n  cx.drawImage(state.stoneCv.raw,0,0);\n  if(state.paintT>0){\n    cx.save(); cx.beginPath(); cx.rect(0,0,N*clamp(state.paintT,0,1)+2,N); cx.clip(); cx.drawImage(state.stoneCv.wash,0,0); cx.restore();\n  }\n  cx.drawImage(Ic,0,0);\n  tx.globalCompositeOperation='copy'; tx.drawImage(state.stoneCv.carv,0,0);\n  tx.globalCompositeOperation='destination-in'; tx.drawImage(Ac,0,0); tx.globalCompositeOperation='source-over';\n  cx.drawImage(Tc,0,0); cx.restore();\n  colorTex.needsUpdate=true;\n}\nfunction resetFace(){\n  hx.fillStyle='#fff'; hx.fillRect(0,0,N,N); ax.clearRect(0,0,N,N);\n  nx.fillStyle='rgb(128,128,255)'; nx.fillRect(0,0,N,N);\n  heightTex.needsUpdate=normalTex.needsUpdate=true;\n  state.carved=new Uint8Array(N*N); state.carvedCount=0; state.rimCount=0; state.undo=[]; $('#btn-undo').disabled=true;\n  compose(); updateStats();\n}\nfunction newStock(shape,mat){\n  state.shape=shape; state.mat=mat; state.masks=shapeMasks(shape); state.stoneCv=genStone(mat);\n  ix.clearRect(0,0,N,N);\n  Object.assign(state,{carveMs:0,strokes:0,inkStrokes:0,spinDeg:0,regrinds:0,review:null,style:null,fineStrokes:0,obsMax:0});\n  chips.length=0;\n  buildBody(); buildVise(); resetFace(); resetDoc();\n  setPhase('paint'); texDirty=true;\n}\n/* ---------- 工程（朱を塗る → 布字 → 彫り → 見せる） ---------- */\nfunction setPhase(p){\n  state.phase=p; document.body.dataset.phase=p;\n  $$('#tray [data-phase]').forEach(el=>el.hidden=el.dataset.phase!==(p==='paint'?'fuji':p==='review'?'carve':p));\n  if(p==='paint'){\n    $('#phase-now').textContent='朱を塗る'; $('#phase-hint').textContent='親方が印面に朱墨を塗っています。';\n    state.paintT=0; startPaint();\n  } else if(p==='fuji'){\n    $('#phase-now').textContent='布字（筆で下書き）';\n    $('#phase-hint').textContent='朱を塗った印面に、墨で字や絵を書きます。書けたら親方が声をかけてくれます。';\n    selectTool('f3');\n  } else if(p==='carve'){\n    $('#phase-now').textContent=state.style==='haku'?'彫り（白文：墨の字を彫る）':state.style==='shu'?'彫り（朱文：墨の字を残す）':'彫り（下書きなし）';\n    $('#phase-hint').textContent=state.style==='haku'?'墨で書いた線の上を彫ります。':state.style==='shu'?'墨の線を残して、まわりの朱を彫り落とします。':'思うままに彫ってください。';\n    selectTool(state.pendingKnife||'k7'); state.pendingKnife=null;\n  } else if(p==='press'){\n    $('#phase-now').textContent='押印'; $('#phase-hint').textContent='朱肉をつけて稟議書に押す。';\n  } else if(p==='review'){\n    $('#phase-now').textContent='親方の検分';\n    $('#phase-hint').textContent='評価をもらいました。';\n  }\n  $('#hud-phase').textContent='工程：'+$('#phase-now').textContent.replace(/（.*）/,'');\n  updateStats(); $('#hud-done').hidden=!(p==='fuji'||p==='carve'||p==='review'); $('#hud-done').textContent=p==='fuji'?'書けた → 彫りへ':'呼び鈴を鳴らす（完成）'; syncActs(); $('#hud-bow').hidden=p!=='press'; if(p==='press') syncBowPill(); if(p!=='press') $('#hud-submit').hidden=true; $('#hud-tip').hidden=true;\n  updateStats(); updateBigHint();\n}\nconst CH={\n  done:{label:'彫りに進む',primary:true,fn:()=>askStyle()},\n  more:{label:'まだ書く',fn:()=>say('ゆっくりでええ。',{force:true,mood:'happy'})},\n  show:{label:'親方に見せる',primary:true,fn:()=>review()},\n  keep:{label:'まだ彫る',fn:()=>say('納得いくまで彫れ。それが職人じゃ。',{force:true,mood:'proud'})},\n  back:{label:'布字に戻る',fn:()=>{ setPhase('fuji'); say('書き足すか。ええぞ、墨は何度でも書ける。',{force:true}); }}\n};\nfunction shapeTip(){ return {square:'…角は四隅が命じゃ。隅まで神経を通せ。',oval:'…小判は縦長じゃ。字の上下を詰めすぎるな。'}[state.shape]||''; }\nfunction askStyle(){\n  const has=inkAmount()>0;\n  if(has) say('どれ…よう書けとる。で、どう彫る？墨の字を彫るか（白文）、字を残してまわりを彫るか（朱文）。',{force:true,mood:'thinking',choices:[\n    {label:'字を彫る（白文）',primary:true,fn:()=>{ state.style='haku'; setPhase('carve'); say('白文じゃな。墨の線をなぞるように刀を入れろ。線からはみ出すなよ。'+shapeTip(),{force:true,mood:'happy'}); }},\n    {label:'字を残す（朱文）',fn:()=>{ state.style='shu'; setPhase('carve'); say('朱文か、手間のかかる方を選んだな。墨の線には刀を当てるな。まわりを落としていけ。'+shapeTip(),{force:true,mood:'surprised'}); }},\n    CH.more]});\n  else say('こら、何も書いとらんじゃないか。いきなり彫るやつがあるか。',{force:true,mood:'angry',choices:[\n    {label:'筆で書く',primary:true,fn:()=>{ setPhase('fuji'); say('それでええ。',{force:true,mood:'happy'}); }},\n    {label:'下書きなしで彫る',fn:()=>{ state.style=null; setPhase('carve'); say('…度胸だけは認めてやる。好きにせい。',{force:true,mood:'worried'}); }}]});\n}\nlet paintStart=0;\nfunction startPaint(){\n  paintStart=performance.now(); state.paintArmed=false;\n  if(!state.started||howtoOpen||SHOW.stage) return;\n  state.paintArmed=true; // 朱を塗るのは、ここで合図が出てから（据え付け中や遊び方の表示中に勝手に進まない）\n  const nCut=+(lsGet('hanko.count')||0);\n  const byCount={1:'二本目か。手が少し覚えとるはずじゃ。',2:'三本目。そろそろ癖が出てくる頃じゃ。',4:'五本目か。…弟子入りでもする気か。',9:'十本目…お主、もう半分職人じゃ。',19:'二十本目。わしの若い頃より彫っとるかもしれん。'}[nCut];\n  if(master.said.has('intro')){ say((byCount||pick(['おかえり。もう一本いくか。','また来たな。今度はもっとええのを彫れよ。','懲りんやつじゃな。気に入った。','…ほう、まだやるか。ええ目をしとる。']))+'まずは朱を塗るぞ。',{force:true,mood:'happy'}); }\n  else if(nCut>0){ master.said.add('intro'); say((byCount||pick(['また来たか。前の石はどうした？','おう、久しぶりじゃな。','来たか。茶はまだ入っとらんぞ。']))+'…まずは朱を塗るぞ。',{force:true,mood:'happy'}); }\n  if(!master.said.has('intro')){ const h=new Date().getHours(); const g=h>=5&&h<11?'おはよう。朝の石はよう冷えとる。':h<17?'よう来たな。':h<22?'こんな時間によう来たな。仕事帰りか？':'夜中に彫りに来るとは、物好きじゃな。わしも眠れんでな。'; say(g+'まずは印面に朱墨を塗るところからじゃ。見とけ。',{force:true,key:'intro'}); }\n  if(reduceMotion){ state.paintT=1; compose(); setTimeout(()=>finishPaint(),400); }\n}\nfunction finishPaint(){\n  if(state.phase!=='paint') return;\n  state.paintT=1; compose(); fude.visible=false;\n  setPhase('fuji');\n  setTimeout(()=>{ if(!master.said.has('fujiIntro')){ say(innerWidth<700?'次は布字じゃ。筆の太さは下の札で替えられる。…押せば左右が逆になる。手鏡を見ながら書け。':'次は布字じゃ。筆の太さは下の札か、左の筆掛けで替えられる。…押せば左右が逆になる。手鏡を見ながら書け。',{force:true,key:'fujiIntro'}); setTimeout(()=>{ if(state.inkStrokes===0) say(STONES[state.mat].note+({square:'角印は角が難しいぞ。',oval:'小判は縦長じゃ。配置をよう考えろ。',round:''}[state.shape]),{key:'stone-'+state.mat+state.shape,once:true}); },9000); } else say('塗れたぞ。布字からやり直しじゃ。',{force:true}); },600);\n}\n\n/* ---------- 入力（書く・彫る・回す） ---------- */\nfunction hitUV(clientX,clientY){\n  const r=glCv.getBoundingClientRect(), ndc=new THREE.Vector2((clientX-r.left)/r.width*2-1,-(clientY-r.top)/r.height*2+1);\n  const ray=new THREE.Raycaster(); ray.setFromCamera(ndc,camera);\n  const o=ray.ray.origin, d=ray.ray.direction; if(Math.abs(d.y)<1e-6) return null;\n  const t=(FACE_Y-o.y)/d.y; if(t<0) return null;\n  const wx=o.x+d.x*t, wz=o.z+d.z*t;\n  return {x:(wx+1)/2*N, y:(wz+1)/2*N, wx, wz};\n}\nconst insideAt=p=>{ const x=p.x|0, y=p.y|0; return x>=0&&y>=0&&x<N&&y<N&&state.masks.inside[y*N+x]===1; };\nfunction selectTool(v){ const el=document.querySelector(`input[name=tool][value=\"${v}\"]`); if(el){ el.checked=true; state.tool=v; } fude.visible=knife.visible=brushRing.visible=false; updateHud(); updateRack(); }\nconst OBS=[[0,'素人',''],[1.5,'見習い','ほう、少しは様になってきたな。'],[3,'職人気質','お主、目つきが変わってきたな。'],[5,'執念','もう晩飯の時間じゃぞ…まだやるんか。'],[8,'狂気の域','…わしより執念深いやつは初めて見た。']];\nfunction obsessionScore(ms){ return (ms??state.carveMs)/60000+state.strokes/30+state.regrinds*1.5+state.spinDeg/720+state.inkStrokes/20+(state.fineStrokes||0)/25; }\nfunction obsessionLevel(s){ let L=0; OBS.forEach((o,i)=>{ if(s>=o[0]) L=i; }); return L; }\nfunction updateObsession(ms){\n  const s=obsessionScore(ms), L=obsessionLevel(s), el=$('#hud-obs');\n  el.innerHTML='執着：<b>'+OBS[L][1]+'</b>'+OBS.map((o,i)=>i?`<i class=\"${i<=L?'on':''}\"></i>`:'').join('');\n  if(L>(state.obsMax||0)){ state.obsMax=L; if(OBS[L][2]) say(OBS[L][2],{force:true,key:'obs'+L,once:true,mood:L>=4?'surprised':'proud'}); }\n}\nfunction updateHud(){\n  const t=state.tool, ti=toolInfo(t);\n  // 道具の太さは画面下の札で直接選べる（寄ったまま作業台へ手を伸ばさなくていい）\n  const f=state.phase==='fuji'||state.phase==='paint', list=f?[['f6','太'],['f3','中'],['f2','細']]:[['k14','大'],['k7','中'],['k3','小'],['k1','極細']];\n  if(state.phase!=='press') $('#hud-tool').innerHTML=ti.kind==='rotate'?'見回す':`<span class=\"lb\">${f?'筆':'印刀'}</span>`+list.map(([v,l])=>`<button type=\"button\" data-tool=\"${v}\"${v===t?' class=\"on\" aria-pressed=\"true\"':' aria-pressed=\"false\"'}>${l}</button>`).join('');\n  updateBigHint();\n  $('#hud-tip').textContent=state.phase==='carve'||state.phase==='review'?'印刀は作業台の刀立てから ／ 左ドラッグで彫る ／ 右ドラッグで見回す ／ Spaceでかすを吹く ／ ホイールで寄る':'筆は左の筆掛けから ／ 左ドラッグで書く ／ 右ドラッグで見回す';\n}\nconst COARSE=matchMedia('(pointer: coarse)').matches;\nlet hintAnchor=null; // 合図を出す場所（ワールド座標）\nfunction updateBigHint(){ const h=$('#bighint'); let t=''; hintAnchor=null; if(state.step===1){\n  if(state.phase==='fuji'&&state.inkStrokes===0) t=COARSE?'① 赤い印面を指でなぞって、筆で字を書く':'① 赤い印面を左ドラッグでなぞって、筆で字を書く';\n  else if(state.phase==='fuji') t='書けたら、右下の「書けた → 彫りへ」';\n  else if(state.phase==='carve'&&state.strokes===0) t='② '+(state.style==='shu'?'墨の線のまわりを':'墨の線を')+(COARSE?'指でなぞって彫る（何度もなぞると深くなる）':'左ドラッグでなぞって彫る（何度もなぞると深くなる）');\n  else if(state.phase==='press'&&P.active&&!P.auto){\n    if(state.ink<.2){ t=COARSE?'① 朱肉をトントン（タップ）':'① 朱肉をクリックしてトントン'; hintAnchor={x:pressPot.position.x,y:1.2,z:pressPot.position.z+1.9}; }\n    else if(!state.last){ const c=docToWorld(boxCenter(3).x,boxCenter(3).y); t='② 担当欄を長押しで押す'; hintAnchor={x:c.wx,y:.1,z:c.wz+1.6}; }\n  }\n} if(t&&!hintAnchor) hintAnchor={x:0,y:FACE_Y,z:R*1.25}; if(h.textContent!==t) h.textContent=t; h.hidden=!t; }\n// 合図の位置合わせ：印面の手前の縁の「すぐ外」に置く（印面の上には重ねない）\nconst _hv=new THREE.Vector3();\nfunction placeOverlays(){\n  const h=$('#bighint'), sr=stageEl.getBoundingClientRect();\n  if(!h.hidden&&hintAnchor){\n    _hv.set(hintAnchor.x,hintAnchor.y,hintAnchor.z).project(camera);\n    let x=(_hv.x+1)/2*sr.width, y=(1-_hv.y)/2*sr.height+10;\n    const hw=h.offsetWidth/2, hh=h.offsetHeight, hudTop=sr.height-(($('#hud').offsetHeight||40)+24);\n    x=clamp(x,hw+8,sr.width-hw-8); let up=false; if(y+hh>hudTop){ y=hudTop-hh; up=true; } y=Math.max(8,y);\n    h.style.left=x+'px'; h.style.top=y+'px'; h.classList.toggle('up',up);\n  }\n  // 石が画面の外に出たら、縁に矢印（押すと真ん中に戻す）\n  const ea=$('#edge-arrow'), work=state.step===1&&(state.phase==='fuji'||state.phase==='carve'||state.phase==='review')&&!SHOW.on&&!SHOW.stage;\n  let show=false;\n  if(work){\n    _hv.set(0,FACE_Y,0).project(camera);\n    const behind=_hv.z>1, px=(_hv.x+1)/2*sr.width, py=(1-_hv.y)/2*sr.height, m=40;\n    if(behind||px<-10||px>sr.width+10||py<-10||py>sr.height+10){\n      show=true; let dx=px-sr.width/2, dy=py-sr.height/2; if(behind){ dx=-dx; dy=-dy; }\n      const k=Math.min((sr.width/2-m-60)/Math.max(1e-3,Math.abs(dx)),(sr.height/2-m-30)/Math.max(1e-3,Math.abs(dy)));\n      ea.style.left=(sr.width/2+dx*k)+'px'; ea.style.top=(sr.height/2+dy*k)+'px';\n      ea.querySelector('.ar').style.transform=`rotate(${Math.atan2(dy,dx)}rad)`;\n    }\n  }\n  if(ea.hidden===show) ea.hidden=!show;\n}\n$('#edge-arrow').addEventListener('click',()=>{ view.tgtT.set(0,FACE_Y-.2,0); view.tDist=10.5; view.tElev=.74; view.tAz=Math.round(view.az/(Math.PI*2))*Math.PI*2; view.auto=false; });\nfunction noteSwap(){ if(bump('swap',15000)>=4) talk('toolSwap',{force:true,mood:'thinking'}); }\nfunction cycleTool(){ noteSwap(); const f=state.phase==='fuji'||state.phase==='paint', list=f?['f6','f3','f2']:['k14','k7','k3','k1']; const i=list.indexOf(state.tool); selectTool(list[(i+1)%list.length]); if(state.tool==='k1') say('極細の刀か。そいつは髪の毛一本ぶんしか彫れんぞ。…気に入った。',{key:'k1tool',once:true,mood:'surprised'}); }\n$$('input[name=tool]').forEach(el=>el.addEventListener('change',()=>{ state.tool=document.querySelector('input[name=tool]:checked').value; updateHud(); }));\n$('#hud-tool').addEventListener('click',e=>{ if(state.phase==='press'){ dip(); return; } const b=e.target.closest('[data-tool]'); if(b){ if(b.dataset.tool!==state.tool){ noteSwap(); selectTool(b.dataset.tool); if(state.tool==='k1') say('極細の刀か。そいつは髪の毛一本ぶんしか彫れんぞ。…気に入った。',{key:'k1tool',once:true,mood:'surprised'}); } return; } cycleTool(); });\n$('#hud-done').addEventListener('click',()=>{ if(state.phase==='fuji') askStyle(); else ringBell(); });\n$('#bow-l').addEventListener('click',e=>{ e.stopPropagation(); nudgeBow(-6); }); $('#bow-r').addEventListener('click',e=>{ e.stopPropagation(); nudgeBow(6); });\n$('#act-wipe').addEventListener('click',()=>{ if(!inkAmount()) return; say('全部拭いて書き直すか？',{force:true,mood:'thinking',choices:[{label:'拭く',fn:()=>$('#btn-wipe').click()},{label:'やめとく',primary:true,fn:()=>say('そうか。',{force:true})}]}); });\n$('#act-near').addEventListener('click',()=>{ view.tDist=clamp(view.tDist*.72,1.5,24); if(view.tDist<1.8) talk('zoomNear',{gap:30000}); });\n$('#act-far').addEventListener('click',()=>{ view.tDist=clamp(view.tDist*1.38,1.5,24); });\n$('#act-blow').addEventListener('click',()=>$('#btn-blow').click());\n$('#act-top').addEventListener('click',()=>{ if(view.tElev>1.2) $('#v-tilt').click(); else $('#v-top').click(); });\n$('#act-grind').addEventListener('click',()=>say('研ぎ直すと、彫ったのも下書きも全部消えるぞ。ええか？',{force:true,mood:'worried',choices:[{label:'研ぎ直す',fn:()=>$('#btn-grind').click()},{label:'やめとく',primary:true,fn:()=>say('そうか。続けろ。',{force:true})}]}));\nfunction syncBlowPill(){ const b=$('#act-blow'); if(!b) return; b.classList.remove('cool'); void b.offsetWidth; b.classList.add('cool'); }\nfunction syncActs(){ const p=state.phase; $$('#hud-acts .act, #hud-view .act').forEach(b=>{ b.hidden=!b.dataset.ph.split(' ').includes(p); }); }\nfunction repress(){ goStep(2); try{ newPaper(); }catch(e){} say(pick(['もう一枚じゃな。今度はどう押す？','押し直しか。紙はなんぼでもある。','よし、新しい稟議書じゃ。']),{force:true,mood:'happy'}); }\nfunction syncDock(){ const ready=!$('#btn-cert').hidden&&!kanteiBusy; $('#d-cert').disabled=!ready; $('#d-x').disabled=!ready; $('#d-cert').innerHTML=ready?'鑑定書<span class=\"lg\">を画像で</span>保存':'鑑定中…'; }\n$('#d-cert').addEventListener('click',()=>$('#btn-cert').click());\n$('#d-x').addEventListener('click',()=>shareX());\n$('#d-repress').addEventListener('click',()=>repress());\n$('#d-again').addEventListener('click',()=>restartAll());\n[['d-ex-straight','ex-straight'],['d-ex-bow','ex-bow'],['d-ex-doc','ex-doc']].forEach(([a,b])=>$('#'+a).addEventListener('click',()=>{ $('#'+b).click(); $('#d-more').open=false; }));\ndocument.addEventListener('click',e=>{ const m=$('#d-more'); if(m.open&&!m.contains(e.target)) m.open=false; });\nfunction submitKantei(){ if(!state.last) return; endPress(); goStep(3); }\n$('#hud-submit').addEventListener('click',submitKantei); $('#hud-submit').addEventListener('keydown',e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); submitKantei(); } });\n$('#hud-tool').addEventListener('keydown',e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); cycleTool(); } });\nfunction addDirty(x0,y0,x1,y1){ if(!carveDirty) carveDirty={x0,y0,x1,y1}; else { carveDirty.x0=Math.min(carveDirty.x0,x0); carveDirty.y0=Math.min(carveDirty.y0,y0); carveDirty.x1=Math.max(carveDirty.x1,x1); carveDirty.y1=Math.max(carveDirty.y1,y1); } }\nlet carving=null, rotating=null, lastClient=null, spawnAcc=0;\n// 一刀ごとの「もう削った」格子。新しく刃が当たった印面の量（残りの深さで重み付け）を返す\nconst CG=90, CGS=N/CG; let cutGrid=null;\nfunction newCutAmount(a,b,r){\n  if(!cutGrid) return 0;\n  const L=Math.hypot(b.x-a.x,b.y-a.y), steps=Math.max(1,Math.ceil(L/CGS)), rr=r+.8, ins=state.masks.inside, base=strokeBase&&strokeBase.data;\n  let amt=0;\n  for(let i=0;i<=steps;i++){\n    const x=a.x+(b.x-a.x)*i/steps, y=a.y+(b.y-a.y)*i/steps;\n    const gx0=Math.max(0,Math.floor((x-rr)/CGS)), gx1=Math.min(CG-1,Math.floor((x+rr)/CGS)), gy0=Math.max(0,Math.floor((y-rr)/CGS)), gy1=Math.min(CG-1,Math.floor((y+rr)/CGS));\n    for(let gy=gy0;gy<=gy1;gy++) for(let gx=gx0;gx<=gx1;gx++){\n      const k=gy*CG+gx; if(cutGrid[k]) continue;\n      const cx=(gx+.5)*CGS, cy=(gy+.5)*CGS; if((cx-x)*(cx-x)+(cy-y)*(cy-y)>rr*rr) continue;\n      cutGrid[k]=1; const pi=(cy|0)*N+(cx|0); if(ins[pi]!==1) continue;\n      const h=base?base[pi*4]/255:1; if(h>.06) amt+=h;   // 削り切って底に近い所はほぼ出ない\n    }\n  }\n  return amt;\n}\nfunction strokeSeg(a,b){\n  const ti=toolInfo(state.tool), r=ti.r;\n  const line=(ctx,style)=>{ ctx.save(); shapePath(ctx,state.shape,0); ctx.clip(); ctx.strokeStyle=style; ctx.lineWidth=r*2; ctx.lineCap='round'; ctx.lineJoin='round'; ctx.beginPath(); ctx.moveTo(a.x,a.y); ctx.lineTo(b.x+.01,b.y); ctx.stroke(); ctx.restore(); };\n  // 印刀は平らな刃：刃幅ぶんの帯を引きずる。始めと終わりは角（butt）、曲がり目だけ刃を回すので丸く埋める\n  // 一刀ぶんの軌跡をまとめて引き直す（曲がり目は丸く、端は角のまま）\n  const blade=(ctx,P)=>{ if(P.length<2) return; ctx.save(); shapePath(ctx,state.shape,0); ctx.clip(); ctx.strokeStyle='#000'; ctx.lineWidth=r*2; ctx.lineCap='butt'; ctx.lineJoin='round'; ctx.beginPath(); ctx.moveTo(P[0].x,P[0].y); for(let i=1;i<P.length;i++) ctx.lineTo(P[i].x,P[i].y); ctx.stroke(); ctx.restore(); };\n  if(ti.kind==='fude'){ line(ix,'rgba(16,13,11,.94)'); }\n  else {\n    const P=carving?(carving.pts||(carving.pts=[{x:a.x,y:a.y}])):[{x:a.x,y:a.y}];\n    const lp=P[P.length-1]; if(Math.hypot(b.x-lp.x,b.y-lp.y)>=1.5) P.push({x:b.x,y:b.y});\n    // 角の向きが手ぶれで乱れないよう、刃幅より短い書き出しは方向が決まるまで待つ\n    const Q=P.length>=2&&Math.hypot(P[P.length-1].x-P[0].x,P[P.length-1].y-P[0].y)>=Math.min(r,3)?P:[];\n    blade(sx,Q); blade(ax,Q);\n    if(Q.length&&carving&&!carving.bladeOn){ carving.bladeOn=1; let X0=1e9,Y0=1e9,X1=-1e9,Y1=-1e9; for(const q of P){ X0=Math.min(X0,q.x); Y0=Math.min(Y0,q.y); X1=Math.max(X1,q.x); Y1=Math.max(Y1,q.y); } addDirty(X0-r-3,Y0-r-3,X1+r+3,Y1+r+3); deepen(X0-r-3,Y0-r-3,X1+r+3,Y1+r+3); } const x0=Math.min(a.x,b.x)-r-3, y0=Math.min(a.y,b.y)-r-3, x1=Math.max(a.x,b.x)+r+3, y1=Math.max(a.y,b.y)+r+3; addDirty(x0,y0,x1,y1); deepen(x0,y0,x1,y1);\n    const dist=Math.hypot(b.x-a.x,b.y-a.y);\n    // かすは「実際に削れた分」だけ出す（印面の外・同じ一刀でなぞり直した所・削り切った所からは出ない）\n    const cut=newCutAmount(a,b,r); spawnAcc+=cut;\n    const unit=Math.max(2.4,r*r/9);\n    if(spawnAcc>unit){ const n=Math.min(8,Math.round(spawnAcc/unit)); spawnAcc=0; const L=dist||1; spawnChips(b.wx,b.wz,(b.x-a.x)/L,(b.y-a.y)/L,r,n); }\n    const sp=dist/Math.max(1,performance.now()-(carving.lt||performance.now())); carving.lt=performance.now(); if(sp>1.6) carving.fast=(carving.fast||0)+1;\n    carving.sp=sp; if(cut>0) shake=Math.min(.3,shake+.012+r*.0015); carving.cutNow=cut;\n    // 溝の縁が欠ける（石の欠け）：刃が大きいほど、速いほど、硬い石ほど欠ける\n    const br=STONES[state.mat].brittle, L=dist||1, px=-(b.y-a.y)/L, py=(b.x-a.x)/L;\n    const pChip=clamp(.08+(r/7)*.18*br+clamp(sp-.6,0,2)*.25*br,0,.9)*Math.min(1,dist/(r*.6)+.15)*(cut>0?1:0);\n    if(Math.random()<pChip){\n      const n=1+(Math.random()<.35*br?1:0);\n      for(let k=0;k<n;k++){\n        const t=Math.random(), side=Math.random()<.5?-1:1, d=r*(.75+Math.random()*.4), cr=Math.max(1.2,r*(.14+Math.random()*.26)*(r>=14?1.3:1));\n        const cxp=a.x+(b.x-a.x)*t+px*side*d, cyp=a.y+(b.y-a.y)*t+py*side*d;\n        const poly=(ctx)=>{ ctx.save(); shapePath(ctx,state.shape,0); ctx.clip(); ctx.fillStyle='#000'; ctx.beginPath(); const m=5+(Math.random()*3|0); for(let j=0;j<m;j++){ const an=j/m*Math.PI*2, rr=cr*(.55+Math.random()*.6); const X=cxp+Math.cos(an)*rr*(1+.4*Math.abs(px)), Y=cyp+Math.sin(an)*rr*(1+.4*Math.abs(py)); j?ctx.lineTo(X,Y):ctx.moveTo(X,Y); } ctx.closePath(); ctx.fill(); ctx.restore(); };\n        poly(sx); poly(ax); deepen(cxp-cr*2,cyp-cr*2,cxp+cr*2,cyp+cr*2);\n        addDirty(cxp-cr*2,cyp-cr*2,cxp+cr*2,cyp+cr*2);\n        if(Math.random()<.6&&state.masks.inside[(clamp(cyp|0,0,N-1))*N+clamp(cxp|0,0,N-1)]===1) spawnChips(cxp/N*2-1,cyp/N*2-1,px*side,py*side,Math.max(4,r*.8),1);\n        if(Math.random()<.5) noise(5200+Math.random()*1500,4,.05,.03);\n      }\n    }\n  }\n  texDirty=true;\n}\n// 1回の刀（ストローク）で彫る形を Sc に描き、刀を入れる前の高さ（strokeBase）に一度だけ重ねる\n// → 同じ所に何度も刀を入れると、そのたびに溝が深くなる\nconst Sc=mkC(), sx=Sc.getContext('2d'); let strokeBase=null;\nconst CUT=.55;\nfunction deepen(x0,y0,x1,y1){\n  if(!strokeBase) return;\n  x0=clamp(Math.floor(x0),0,N); y0=clamp(Math.floor(y0),0,N); x1=clamp(Math.ceil(x1),0,N); y1=clamp(Math.ceil(y1),0,N);\n  const w=x1-x0, h=y1-y0; if(w<=0||h<=0) return;\n  hx.putImageData(strokeBase,0,0,x0,y0,w,h);\n  hx.save(); hx.beginPath(); hx.rect(x0,y0,w,h); hx.clip(); hx.globalAlpha=CUT; hx.drawImage(Sc,0,0); hx.restore();\n}\nfunction pushUndo(){ state.undo.push({h:hx.getImageData(0,0,N,N),a:ax.getImageData(0,0,N,N),i:ix.getImageData(0,0,N,N)}); if(state.undo.length>25) state.undo.shift(); $('#btn-undo').disabled=false; }\n$('#btn-undo').addEventListener('click',()=>{\n  if(bump('undo',20000)>=4) talk('undoMany',{force:true,mood:'worried'});\n  const s=state.undo.pop(); if(!s) return;\n  hx.putImageData(s.h,0,0); ax.putImageData(s.a,0,0); ix.putImageData(s.i,0,0); updateNormals(0,0,N,N);\n  heightTex.needsUpdate=normalTex.needsUpdate=true; compose(); $('#btn-undo').disabled=!state.undo.length; updateStats();\n  if(!say('戻せるのは今だけじゃぞ。本物の石は戻らんからな。',{key:'undo',once:true})) say(pick(['…まあ、ええ。','迷いは線に出る。戻すなら潔くな。','今のは見んかったことにしてやる。']),{key:'undo2',gap:40000});\n});\n$('#btn-wipe').addEventListener('click',()=>{ pushUndo(); ix.clearRect(0,0,N,N); compose(); updateStats(); say('拭いたか。書き直しは何度でもええ。',{key:'wipe',once:true}); });\nlet blowReady=0; const BLOW_CD=1500;\n$('#btn-blow').addEventListener('click',()=>{ const now=performance.now(); if(now<blowReady){ if(bump('blowCd',4000)>=3) say(pick(['息が続かん。少し待て。','そう何度も吹けるか。肺は一組しかないんじゃ。']),{key:'blowcd',gap:20000,mood:'worried'}); return; } blowReady=now+BLOW_CD; syncBlowPill(); ensureAudio(); blow(); if(bump('blow',20000)>=4) talk('blowMany',{force:true,mood:'worried'}); else if(!say('そうじゃ。かすを吹かんと線が見えんからな。',{key:'blow',once:true})) say(pick(['フッ。…そう、それでええ。','かすの下に本当の線がある。','吹いたら、よう見い。']),{key:'blow2',gap:45000}); });\n$('#btn-grind').addEventListener('click',()=>{\n  ensureAudio(); pushUndo(); state.regrinds++; grindSound(); blow();\n  hx.fillStyle='#fff'; hx.fillRect(0,0,N,N); ax.clearRect(0,0,N,N); ix.clearRect(0,0,N,N); nx.fillStyle='rgb(128,128,255)'; nx.fillRect(0,0,N,N);\n  heightTex.needsUpdate=normalTex.needsUpdate=true; state.paintT=0; compose(); state.review=null;\n  setPhase('paint');\n  if(state.regrinds===1) say('研ぎ直しか。恥じゃない。わしも若い頃は何十回も研いだ。',{force:true}); else talk('regrindMany',{force:true,gap:0,mood:'surprised'});\n});\n\nglCv.addEventListener('contextmenu',e=>e.preventDefault());\nconst touches=new Map(); let pinch=null;\nfunction undoSilently(){ const s=state.undo.pop(); if(!s) return; hx.putImageData(s.h,0,0); ax.putImageData(s.a,0,0); ix.putImageData(s.i,0,0); updateNormals(0,0,N,N); heightTex.needsUpdate=normalTex.needsUpdate=true; compose(); }\nfunction pinchInfo(){ const p=[...touches.values()]; return {d:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),mx:(p[0].x+p[1].x)/2,my:(p[0].y+p[1].y)/2}; }\nglCv.addEventListener('pointerdown',e=>{\n  if(e.pointerType!=='touch') return;\n  touches.set(e.pointerId,{x:e.clientX,y:e.clientY});\n  if(touches.size===2){\n    if(carving){ const k=carving.kind; carving=null; undoSilently(); if(k==='fude') state.inkStrokes=Math.max(0,state.inkStrokes-1); else state.strokes=Math.max(0,state.strokes-1); }\n    rotating=null; const i=pinchInfo(); pinch={d0:i.d,dist0:view.tDist,mx:i.mx,my:i.my};\n    e.stopImmediatePropagation();\n  }\n},true);\nglCv.addEventListener('pointermove',e=>{\n  if(e.pointerType!=='touch'||!touches.has(e.pointerId)) return;\n  touches.set(e.pointerId,{x:e.clientX,y:e.clientY});\n  if(pinch&&touches.size>=2){\n    const i=pinchInfo(); view.tDist=clamp(pinch.dist0*pinch.d0/Math.max(20,i.d),1.5,24);\n    const dx=i.mx-pinch.mx, dy=i.my-pinch.my; pinch.mx=i.mx; pinch.my=i.my;\n    view.tAz-=dx*.008; view.tElev=clamp(view.tElev+dy*.005,.15,1.55); state.spinDeg+=Math.abs(dx*.008)*180/Math.PI;\n    e.stopImmediatePropagation();\n  }\n},true);\nconst touchUp=e=>{ touches.delete(e.pointerId); if(touches.size<2&&pinch){ pinch=null; rotating=null; } };\nglCv.addEventListener('pointerup',touchUp,true); glCv.addEventListener('pointercancel',touchUp,true);\nglCv.addEventListener('pointerdown',e=>{\n  if(pinch) return;\n  if(napping){ lastActive=performance.now(); wakeUp(); }\n  e.preventDefault(); ensureAudio();\n  if(e.button===0){ const rt=rackHit(e.clientX,e.clientY); if(rt){ setRackHover(null); pickTool(rt); return; } }\n  if(state.phase==='press'&&e.button===0){ glCv.setPointerCapture(e.pointerId); lastClient={x:e.clientX,y:e.clientY}; if(pressDown(e)) return; }\n  glCv.setPointerCapture(e.pointerId);\n  lastClient={x:e.clientX,y:e.clientY};\n  const ti=toolInfo(state.tool);\n  if(e.button===0&&ti.kind!=='rotate'&&(state.phase==='fuji'||state.phase==='carve'&&!state.style)&&!view.auto){\n    if(snapFront()&&hitUV(e.clientX,e.clientY)) say('書く時は正面からじゃ。斜めのまま書くと、押した時に字が傾くぞ。',{key:'front',once:true});\n  }\n  const p=(e.button===0&&ti.kind!=='rotate'&&(state.phase==='fuji'||state.phase==='carve'))?hitUV(e.clientX,e.clientY):null;\n  if(p&&insideAt(p)){\n    pushUndo(); if(ti.kind==='fude') state.inkStrokes++; else { state.strokes++; if(ti.r<=1) state.fineStrokes=(state.fineStrokes||0)+1; } if(state.inkStrokes+state.strokes<=2) updateBigHint();\n    if(ti.kind==='knife'){ sx.clearRect(0,0,N,N); strokeBase=state.undo[state.undo.length-1].h; cutGrid=new Uint8Array(CG*CG); spawnAcc=0; }\n    carving={last:p,t:performance.now(),kind:ti.kind,startRim:state.rimCount,touch:e.pointerType==='touch'}; strokeSeg(p,p);\n    if(ti.kind==='knife') scrape();\n    onStrokeStart(ti.kind);\n  } else {\n    rotating={x:e.clientX,y:e.clientY};\n    if(ti.kind!=='rotate'&&state.phase==='paint') say('まだ塗っとる途中じゃ。ちょっと待て。',{key:'wait'});\n  }\n});\nfunction handleMove(x,y){\n  lastClient={x,y};\n  if(carving){ carveTo(x,y); return; }\n  if(!rotating&&state.step===1) setRackHover(rackHit(x,y),x,y);\n  if(rotating){\n    const dx=x-rotating.x, dy=y-rotating.y; rotating={x,y};\n    view.tAz-=dx*.008; state.spinDeg+=Math.abs(dx*.008)*180/Math.PI;\n    view.tElev=clamp(view.tElev+dy*.005,.15,1.55);\n  }\n}\nglCv.addEventListener('pointermove',e=>{\n  const evs=e.getCoalescedEvents?e.getCoalescedEvents():null;\n  if(evs&&evs.length) for(const ev of evs) handleMove(ev.clientX,ev.clientY); else handleMove(e.clientX,e.clientY);\n});\nfunction carveTo(x,y){\n  const p=hitUV(x,y); if(!p) return;\n  if(Math.hypot(p.x-carving.last.x,p.y-carving.last.y)<.5) return;\n  carving.len=(carving.len||0)+Math.hypot(p.x-carving.last.x,p.y-carving.last.y);\n  strokeSeg(carving.last,p); carving.last=p; if(carving.kind==='knife') scrape();\n}\nfunction endPointer(){\n  strokeBase=null; cutGrid=null;\n  if(carving){ state.carveMs+=performance.now()-carving.t; const c=carving; carving=null; updateStats(); onStrokeEnd(c); }\n  rotating=null;\n}\nglCv.addEventListener('pointerup',()=>{ pressUp(); endPointer(); }); glCv.addEventListener('pointercancel',()=>{ pressUp(); endPointer(); });\nglCv.addEventListener('pointerleave',()=>{ if(!carving) lastClient=null; setRackHover(null); });\nfunction nudgeBow(d){ state.angle=clamp(state.angle+d,-90,90); $('#angle').value=state.angle; const b=judgeBow(state.angle); if(b.name==='敬礼') say('そう、その角度じゃ。',{key:'bowok',gap:20000}); else if(state.angle>20) talk('pressBack',{gap:15000,mood:'angry'}); else if(state.angle<-60) talk('pressDeep',{gap:15000,mood:'surprised'}); syncBowPill(); }\nfunction syncBowPill(){ const el=$('#hud-bow-v'); if(el) el.textContent=`${fmtAngle(state.angle)}・${judgeBow(state.angle).name}`; }\nglCv.addEventListener('wheel',e=>{ e.preventDefault(); if(state.phase==='press'&&!e.shiftKey){ nudgeBow(e.deltaY>0?3:-3); return; } view.tDist=clamp(view.tDist*Math.exp(e.deltaY*.0012),1.5,state.phase==='press'?40:24); if(state.phase!=='press'){ if(view.tDist<1.8) talk('zoomNear',{gap:30000}); else if(view.tDist>19) talk('zoomFar',{gap:30000}); } },{passive:false});\n$('#v-tilt').addEventListener('click',()=>{ view.tElev=.74; view.tDist=10.5; });\n$('#v-top').addEventListener('click',()=>{ view.tElev=1.55; view.tDist=6; say('そう、真上から見るのは大事じゃ。線の歪みがよう分かる。',{key:'top',once:true}); });\n$('#v-near').addEventListener('click',()=>{ view.tDist=clamp(view.tDist*.75,1.5,24); });\n$('#v-far').addEventListener('click',()=>{ view.tDist=clamp(view.tDist*1.33,3.2,24); });\n$('#v-spin').addEventListener('click',e=>{ view.auto=!view.auto; if(view.auto) state.usedRokuro=true; e.currentTarget.setAttribute('aria-pressed',String(view.auto)); if(view.auto) say('ろくろ回しなんぞ教えとらんが…まあ好きにせい。',{key:'spin',once:true}); });\ndocument.addEventListener('keydown',e=>{\n  if(howtoOpen){ if(e.key==='Escape'){ e.preventDefault(); closeHowto(); } return; }\n  if(e.target.closest('textarea,select,input[type=text]')) return;\n  if(napping){ lastActive=performance.now(); wakeUp(); }\n  if(e.key==='Enter'&&master.choices&&!e.target.closest('button')){ e.preventDefault(); pickChoice(master.choices.find(c=>c.primary)||master.choices[0]); return; }\n  if(e.target.closest('input[type=range]')) return;\n  if(state.step!==1||e.ctrlKey&&e.key.toLowerCase()!=='z'||e.metaKey&&e.key.toLowerCase()!=='z'||e.altKey) return;\n  const k=e.key.toLowerCase();\n  if(k==='1'||k==='2'||k==='3'){ noteSwap(); const f=state.phase==='fuji'||state.phase==='paint'; selectTool((f?['f6','f3','f2']:['k14','k7','k3'])[+k-1]); }\n  else if(k==='4'&&(state.phase==='carve'||state.phase==='review')){ selectTool('k1'); say('極細の刀か。そいつは髪の毛一本ぶんしか彫れんぞ。…気に入った。',{key:'k1tool',once:true,mood:'surprised'}); }\n  else if(state.phase==='press'&&(k==='arrowleft'||k==='arrowright')){ e.preventDefault(); nudgeBow(k==='arrowleft'?-3:3); }\n  else if(k===' '){ if(e.target.closest('button')) return; e.preventDefault(); if(e.repeat) return; if(state.phase==='carve'||state.phase==='review') $('#btn-blow').click(); }\n  else if(k==='t'){ if(view.tElev>1.2) $('#v-tilt').click(); else $('#v-top').click(); if(bump('top',10000)>=4) talk('topSpam',{force:true}); }\n  else if(k==='r'){ $('#v-spin').click(); }\n});\n\n/* 道具モデルを手元へ */\nconst _up=new THREE.Vector3(0,1,0), _dir=new THREE.Vector3(), _tc=new THREE.Vector3();\nfunction placeTool(now){\n  if(SHOW.on||SHOW.stage){ fude.visible=false; knife.visible=false; brushRing.visible=false; return; }\n  const ti=toolInfo(state.tool);\n  let p=null;\n  if(state.phase==='paint'){\n    const t=state.started?clamp((now-paintStart)/2200,0,1):0;\n    fude.visible=true; knife.visible=false; brushRing.visible=false;\n    const wx=-R+2*R*t, wz=Math.sin(t*40)*R*.75*Math.sqrt(Math.max(0,1-(wx/R)**2));\n    fude.position.set(wx,FACE_Y+.01,wz); _dir.set(.3,1,.4).normalize(); fude.quaternion.setFromUnitVectors(_up,_dir);\n    return;\n  }\n  if(lastClient&&ti.kind!=='rotate'&&!rotating&&(state.phase==='fuji'||state.phase==='carve')) p=hitUV(lastClient.x,lastClient.y);\n  // 印面の上にある時だけ道具を見せる（彫りながら外へ出た時も、縁から少し出たら消す）\n  const show=p&&(insideAt(p)||carving&&Math.abs(p.wx)<R*1.06&&Math.abs(p.wz)<R*1.06);\n  const model=ti.kind==='fude'?fude:knife;\n  knife.visible=fude.visible=false; brushRing.visible=false;\n  glCv.style.cursor=rackHover?'pointer':show?'none':(rotating?'grabbing':'grab');\n  if(rackHover){ knife.visible=fude.visible=false; brushRing.visible=false; return; }\n  if(!show) return;\n  model.visible=true;\n  const sink=carving&&ti.kind==='knife'?-.03:0;\n  model.position.set(p.wx,FACE_Y+.005+sink,p.wz);\n  _tc.copy(camera.position).sub(model.position); _tc.y=0; _tc.normalize();\n  // 柄は奥（カメラと反対側）へ倒す。手前に倒すと柄で刃先が隠れる\n  _dir.set(-_tc.x*.55,1,-_tc.z*.55).normalize();\n  model.quaternion.setFromUnitVectors(_up,_dir);\n  setToolAlpha(carving?.32:.6);\n  if(ti.kind==='knife') knife.scale.set(Math.max(.45,ti.r/7)**.6,1,1);\n  brushRing.visible=true; const s=ti.r/(N/2); brushRing.scale.set(s,1,s); brushRing.position.set(p.wx,.004,p.wz);\n}\n\n/* 法線の更新 */\nfunction updateNormals(x0,y0,x1,y1){\n  x0=clamp(Math.floor(x0)-2,0,N-1); y0=clamp(Math.floor(y0)-2,0,N-1); x1=clamp(Math.ceil(x1)+2,0,N); y1=clamp(Math.ceil(y1)+2,0,N);\n  const w=x1-x0, h=y1-y0; if(w<=0||h<=0) return;\n  const src=hx.getImageData(x0,y0,w,h).data, out=nx.createImageData(w,h), S=2.4/255;\n  const H=(x,y)=>src[(clamp(y,0,h-1)*w+clamp(x,0,w-1))*4];\n  for(let y=0;y<h;y++) for(let x=0;x<w;x++){ const a=(H(x-1,y)-H(x+1,y))*S, b=(H(x,y+1)-H(x,y-1))*S, l=Math.hypot(a,b,1), o=(y*w+x)*4; out.data[o]=(a/l*.5+.5)*255; out.data[o+1]=(b/l*.5+.5)*255; out.data[o+2]=255/l; out.data[o+3]=255; }\n  nx.putImageData(out,x0,y0);\n}\n\n/* ---------- 集計 ---------- */\nfunction fmtTime(ms){ const s=Math.round(ms/1000); return s<60?`${s}秒`:`${Math.floor(s/60)}分${s%60}秒`; }\nfunction inkAmount(){ const d=ix.getImageData(0,0,N,N).data; let n=0; for(let i=3;i<d.length;i+=16) if(d[i]>100) n++; return n; }\nfunction readMasks(){\n  const h=hx.getImageData(0,0,N,N).data, k=ix.getImageData(0,0,N,N).data, M=state.masks;\n  const c=new Uint8Array(N*N), ink=new Uint8Array(N*N); let cc=0, rc=0, ic=0;\n  for(let i=0;i<N*N;i++){ if(!M.inside[i]) continue; if(h[i*4]<128){ c[i]=1; cc++; if(M.ring[i]) rc++; } if(k[i*4+3]>100){ ink[i]=1; ic++; } }\n  Object.assign(state,{carved:c,inkMask:ink,carvedCount:cc,rimCount:rc,inkCount:ic});\n}\nfunction dilate(m,r){ const b=boxBlur(Float32Array.from(m),r), o=new Uint8Array(N*N); for(let i=0;i<N*N;i++) o[i]=b[i]>.02?1:0; return o; }\nfunction accuracy(){\n  // 布字に対する彫りの正確さ\n  const M=state.masks, C=state.carved, K=state.inkMask;\n  if(!state.style||!state.inkCount) return {prog:null,spill:null};\n  if(state.style==='haku'){\n    const Kd=dilate(K,6); let hit=0, out=0; // 刃の幅ぶんは許容\n    for(let i=0;i<N*N;i++){ if(!C[i]) continue; if(K[i]) hit++; if(!Kd[i]) out++; }\n    return {prog:hit/state.inkCount, spill:state.carvedCount?out/state.carvedCount:0};\n  } else {\n    let done=0, total=0, cut=0;\n    for(let i=0;i<N*N;i++){ if(!M.inside[i]) continue; if(K[i]){ if(C[i]) cut++; } else { total++; if(C[i]) done++; } }\n    return {prog:total?done/total:0, spill:cut/state.inkCount};\n  }\n}\nfunction printSurface(){\n  const M=state.masks, C=state.carved, s=new Uint8Array(N*N);\n  for(let y=0;y<N;y++) for(let x=0;x<N;x++){ const src=state.noFlip?(y*N+x):(y*N+(N-1-x)); s[y*N+x]=M.inside[src]&&!C[src]?1:0; }\n  return s;\n}\nfunction updateStats(){\n  if(!state.masks) return;\n  readMasks();\n  const M=state.masks, A=accuracy(), rimF=state.rimCount/Math.max(1,M.ringCount);\n  const ms=state.carveMs+(carving?performance.now()-carving.t:0);\n  $('#lb-spill').textContent=state.style==='shu'?'墨の線の欠け':'はみ出し';\n  $('#st-prog').textContent=A.prog==null?'―':pct(Math.min(1,A.prog));\n  $('#st-spill').textContent=A.spill==null?'―':(A.spill*100).toFixed(1)+'%';\n  $('#row-spill').classList.toggle('bad',A.spill!=null&&A.spill>.12);\n  $('#st-rim').textContent=(rimF*100).toFixed(1)+'%'; $('#row-rim').classList.toggle('bad',rimF>.08);\n  $('#st-area').textContent=pct(state.carvedCount/M.insideCount);\n  { const hp=$('#hud-prog'), on=state.phase==='carve'||state.phase==='review'; hp.hidden=!on;\n    if(on) hp.innerHTML=A.prog!=null?`下書きの彫れ<b>${pct(Math.min(1,A.prog))}</b>`:`彫った面積<b>${pct(state.carvedCount/M.insideCount)}</b>`; }\n  $('#st-time').textContent=fmtTime(ms); $('#st-strokes').textContent=state.strokes+'刀'; $('#st-ink').textContent=state.inkStrokes+'筆';\n  $('#st-spin').textContent=Math.round(state.spinDeg)+'°'; $('#st-grind').textContent=state.regrinds+'回';\n  $('#st-grade').textContent=state.review?state.review.grade:'―';\n  updateObsession(ms);\n  state.acc=A; state.rimF=rimF;\n  // 手鏡：布字の段階では墨、彫りの段階では印影\n  const pv=$('#pv');\n  if(state.phase==='fuji'||state.phase==='paint'){\n    const x=pv.getContext('2d'); x.clearRect(0,0,N,N); x.save(); if(!state.noFlip){ x.translate(N,0); x.scale(-1,1); } x.drawImage(Cc,0,0); x.restore();\n  } else paintPrint(pv,printSurface());\n}\n$('#noflip').addEventListener('change',e=>{ state.noFlip=e.target.checked; updateStats(); if(state.noFlip) say('反転なしか。本物の印鑑ではありえんが、まあ遊びじゃからな。',{key:'noflip',once:true}); });\n\n/* ---------- 親方（水墨画風のSVG） ---------- */\nconst faceCv=$('#master-face');\nconst EYES={\n  open:'<path d=\"M-4.2 -2.2 Q0 -4.4 4.2 -2.2\" stroke=\"#1C1C1C\" stroke-width=\"1.3\" fill=\"none\" stroke-linecap=\"round\"/><circle class=\"pupil\" r=\"1.9\" fill=\"#1C1C1C\"/>',\n  smile:'<path d=\"M-4.4 1 Q0 -3.4 4.4 1\" stroke=\"#1C1C1C\" stroke-width=\"1.8\" fill=\"none\" stroke-linecap=\"round\"/>',\n  shut:'<path d=\"M-4.2 .3 Q0 1.4 4.2 .3\" stroke=\"#1C1C1C\" stroke-width=\"1.6\" fill=\"none\" stroke-linecap=\"round\"/>',\n  wide:'<circle r=\"3.6\" stroke=\"#1C1C1C\" stroke-width=\"1\" fill=\"#fbf8f0\"/><circle class=\"pupil\" r=\"1.7\" fill=\"#1C1C1C\"/>',\n  angry:'<path d=\"M-4.4 -4 L4.2 -1\" stroke=\"#1C1C1C\" stroke-width=\"1.6\" fill=\"none\" stroke-linecap=\"round\"/><circle class=\"pupil\" r=\"1.8\" cy=\".4\" fill=\"#1C1C1C\"/>',\n  worry:'<path d=\"M-4.2 -1.2 L4.2 -3.8\" stroke=\"#1C1C1C\" stroke-width=\"1.3\" fill=\"none\" stroke-linecap=\"round\"/><circle class=\"pupil\" r=\"1.8\" cy=\".3\" fill=\"#1C1C1C\"/>'\n};\nconst MOUTH={\n  neutral:'M54 79.5 Q60 80.5 66 79.5', happy:'M53 78.4 Q60 83.4 67 78.4', proud:'M54 78.8 Q60 82.2 66 78.8',\n  angry:'M53.5 81.2 Q60 77.2 66.5 81.2', thinking:'M54.5 80.2 Q58 78.6 66 79.4', worried:'M53.5 80.2 Q56.8 78.4 60 80.2 Q63.2 82 66.5 80.2',\n  laugh:'M53 77.6 Q60 87 67 77.6 Q60 80.4 53 77.6 Z', surprised:'M57 79.6 a3 3.6 0 1 0 6 0 a3 3.6 0 1 0 -6 0 Z',\n  talk:'M55 78.4 Q60 84.6 65 78.4 Q60 80.2 55 78.4 Z'\n};\nconst MOODS={ // 眉 [下げ, 傾き]、目、口、頬、汗、仕草\n  neutral:  {brow:[0,0],     browR:null, eye:'open',  mouth:'neutral',  cheek:.32, sweat:0, gest:null},\n  happy:    {brow:[-1,-5],   browR:null, eye:'smile', mouth:'happy',    cheek:.7,  sweat:0, gest:'nod'},\n  laugh:    {brow:[-2,-8],   browR:null, eye:'smile', mouth:'laugh',    cheek:.9,  sweat:0, gest:'bob'},\n  proud:    {brow:[-1,0],    browR:null, eye:'shut',  mouth:'proud',    cheek:.5,  sweat:0, gest:'nod'},\n  angry:    {brow:[2.4,15],  browR:null, eye:'angry', mouth:'angry',    cheek:.95, sweat:0, gest:'shake'},\n  surprised:{brow:[-5,-4],   browR:null, eye:'wide',  mouth:'surprised',cheek:.25, sweat:0, gest:'back'},\n  thinking: {brow:[-3,-7],   browR:[1,6],eye:'open',  mouth:'thinking', cheek:.3,  sweat:0, gest:'tilt'},\n  worried:  {brow:[-2,-15],  browR:null, eye:'worry', mouth:'worried',  cheek:.25, sweat:1, gest:'tilt'}\n};\nconst mood={}; // 互換用\nlet moodName='neutral', moodUntil=0, talking=false, lookX=.5, lookY=-.3, mouseSeen=0, blinkT=2.5, blinkOn=0, talkT=0, talkOpen=false, applied=null;\nconst mEl={eL:$('#mEyeL'),eR:$('#mEyeR'),bL:$('#mBrowL'),bR:$('#mBrowR'),mouth:$('#mMouth'),cL:$('#mCheekL'),cR:$('#mCheekR'),sweat:$('#mSweat')};\nfunction gesture(name){ if(!name||reduceMotion) return; faceCv.classList.remove('nod','shake','bob','tilt','back'); void faceCv.getBoundingClientRect(); faceCv.classList.add(name); }\nfaceCv.addEventListener('animationend',()=>{ if(!faceCv.classList.contains('tilt')) faceCv.classList.remove('nod','shake','bob','back'); });\nfunction applyMood(force){\n  const M=MOODS[moodName]||MOODS.neutral, key=moodName+(blinkOn?'b':'');\n  if(applied===key&&!force) return; applied=key;\n  const [dy,rot]=M.brow, [dyR,rotR]=M.browR||M.brow;\n  mEl.bL.setAttribute('transform',`translate(46 ${49+dy}) rotate(${rot})`);\n  mEl.bR.setAttribute('transform',`translate(74 ${49+dyR}) scale(-1 1) rotate(${rotR})`);\n  const eye=blinkOn&&M.eye!=='smile'&&M.eye!=='shut'?'shut':M.eye;\n  mEl.eL.innerHTML=EYES[eye]; mEl.eR.innerHTML=EYES[eye];\n  mEl.cL.setAttribute('opacity',M.cheek); mEl.cR.setAttribute('opacity',M.cheek);\n  mEl.sweat.style.display=M.sweat?'':'none';\n  setMouth();\n}\nfunction setMouth(){\n  const M=MOODS[moodName]||MOODS.neutral, open=talkOpen&&M.mouth!=='laugh'&&M.mouth!=='surprised';\n  const d=open?MOUTH.talk:MOUTH[M.mouth]; const filled=open||M.mouth==='laugh'||M.mouth==='surprised';\n  mEl.mouth.setAttribute('d',d); mEl.mouth.setAttribute('fill',filled?'#4a1d16':'none');\n}\nfunction setMood(name,dur=4000){ if(!MOODS[name]) name='neutral'; const ch=name!==moodName; moodName=name; moodUntil=performance.now()+dur; applyMood(true); if(ch||name!=='neutral') gesture(MOODS[name].gest); if(name!=='thinking'&&name!=='worried') faceCv.classList.remove('tilt'); }\ndocument.addEventListener('pointermove',e=>{\n  const r=faceCv.getBoundingClientRect(); if(!r.width) return;\n  lookX=clamp((e.clientX-(r.left+r.width/2))/450,-1,1); lookY=clamp(-(e.clientY-(r.top+r.height/2))/450,-1,1); mouseSeen=performance.now();\n},{passive:true});\nfunction updateMaster(dt,t){\n  if(faceCv.getBoundingClientRect().width===0) return;\n  if(performance.now()>moodUntil&&moodName!=='neutral'){ moodName='neutral'; faceCv.classList.remove('tilt'); applyMood(true); }\n  blinkT-=dt; if(blinkT<0){ blinkOn=.13; blinkT=2+Math.random()*3.5; } if(blinkOn>0){ blinkOn=Math.max(0,blinkOn-dt); }\n  applyMood(false);\n  if(talking){ talkT-=dt; if(talkT<0){ talkT=.09+Math.random()*.08; talkOpen=!talkOpen; setMouth(); } } else if(talkOpen){ talkOpen=false; setMouth(); }\n  const idle=performance.now()-mouseSeen>3000, lx=idle?Math.sin(t*.4)*.4+.3:lookX, ly=idle?-.25+Math.sin(t*.3)*.1:lookY;\n  faceCv.querySelectorAll('.pupil').forEach((p,i)=>p.setAttribute('transform',`translate(${(i?-1:1)*lx*1.6} ${-ly*1.2+(moodName==='thinking'?-1.2:0)})`));\n}\napplyMood(true);\nasync function masterPortrait(moodFor){\n  const keep=[moodName,moodUntil,talking,talkOpen,blinkOn]; talking=false; talkOpen=false; blinkOn=0;\n  moodName=moodFor; applyMood(true);\n  const s=new XMLSerializer().serializeToString(faceCv);\n  [moodName,moodUntil,talking,talkOpen,blinkOn]=keep; applyMood(true);\n  const img=new Image(); img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(s.replace('<svg ','<svg width=\"480\" height=\"480\" '));\n  await img.decode(); return img;\n}\n\n/* ---------- 親方のおしゃべり（場面ごと・言い回しのバリエーション） ---------- */\nfunction lsGet(k){ try{ return localStorage.getItem(k); }catch(e){ return null; } }\nfunction lsSet(k,v){ try{ localStorage.setItem(k,v); }catch(e){} }\nconst pick=a=>a[Math.floor(Math.random()*a.length)];\nconst TALK={\n  spin1:['目が回るじゃろ。','そんなに回してどうする。石が酔うぞ。','ろくろ職人にでもなるつもりか？','回せばええってもんじゃない。'],\n  spin2:['まだ回すんか…わしの方が目が回ってきた。','回しすぎじゃ！石が溶けてバターになるぞ。','お主、前世は扇風機か？'],\n  toolSwap:['筆をコロコロ変えるな。迷いが線に出るぞ。','そんなに持ち替えて、手品でも見せる気か。','道具は少ない方が腕は上がるもんじゃ。','決めた道具で最後までやり切れ。'],\n  overCarve:['彫りすぎじゃ！印面がなくなるぞ。','おいおい、残す所も残さんと押せんぞ。','石が「もうやめて」と言うとる。','そこまで削ったら、もはや更地じゃ。'],\n  undoMany:['戻しすぎじゃ。人生は戻せんぞ。','そのボタン、すり減っとらんか？','迷うのは悪くない。が、戻すのはもう十分じゃ。'],\n  tinyTaps:['つつくな。刀は引くもんじゃ。','キツツキか、お主は。','小刻みすぎる。もっと一息で引け。'],\n  longStroke:['ほう、一気に引いたな。思い切りがええ。','長い線じゃ。よう息が続いたな。','その勢い、嫌いじゃない。'],\n  inkHeavy:['墨を塗りすぎじゃ。印面が真っ黒になるぞ。','書道教室じゃないぞ、ここは。','そんなに書いたら、どこを彫るんじゃ。'],\n  blowMany:['吹きすぎじゃ。酸欠で倒れるぞ。','そんなに吹いたら、わしのヒゲまで飛ぶわ。','ふーふー言うて、ラーメンでも冷ましとるんか。'],\n  zoomNear:['近すぎる。鼻が石につくぞ。','そんなに顔を近づけて…石とキスでもする気か。','近う寄りすぎじゃ。'],\n  zoomFar:['遠すぎじゃ。老眼か？わしでもそこまで離さん。','そこからじゃ何も見えんじゃろ。','遠くから見守っとるんか。'],\n  bellSpam:['鳴らしすぎじゃ！聞こえとる！','チンチンうるさいわ。','鈴で遊ぶな。'],\n  faceClick:['なんじゃ、わしの顔に何かついとるか？','つつくな。','…照れるじゃろ。','今忙しいんじゃ。','わしの顔より石を見い。','メガネが曲がるじゃろ。'],\n  longSession:['もう10分か。茶でも入れるか。','肩が凝ったじゃろ。ちょっと伸びせい。','集中しとるな。ええ顔じゃ。'],\n  hoverIdle:['刀を構えたまま固まっとるな。','迷っとるなら、まず一刀入れてみい。','考えすぎじゃ。手を動かせ。'],\n  pressBack:['上司に喧嘩売る気か？','その角度は反抗期じゃ。','そっちは上司と反対じゃぞ。'],\n  pressDeep:['土下座かい。何をやらかした。','そこまで下げんでええ。','頭を下げすぎて床が見えとるぞ。'],\n  topSpam:['上から見たり横から見たり、忙しいのう。','カメラマンにでもなるんか。'],\n  fineMany:['極細で何刀目じゃ…その根気、どこから来る。','髪の毛を一本ずつ彫っとるようなもんじゃ。'],\n  regrindMany:['また研ぐんか。石がどんどん短くなるぞ。','研ぎ直しの回数で日本記録を狙っとるんか。','もはや研ぐのが趣味じゃな。'],\n  inkEmpty:['墨がないのに書いとるつもりか？','筆、乾いとるぞ。'],\n  dip:['トン、トン…そう、軽うにな。','朱は薄く、均一にじゃ。','叩くんじゃない。置くんじゃ。','…もう一度。']\n};\nconst evCount={}, evTimes={};\nfunction bump(ev,win){ const now=performance.now(); const a=(evTimes[ev]=(evTimes[ev]||[]).filter(t=>now-t<win)); a.push(now); return a.length; }\nfunction talk(ev,{force=false,gap=20000,mood=null}={}){\n  const L=TALK[ev]; if(!L) return false;\n  const used=(master.used||(master.used={}))[ev]||(master.used[ev]=[]);\n  let pool=L.map((_,i)=>i).filter(i=>!used.includes(i)); if(!pool.length){ used.length=0; pool=L.map((_,i)=>i); }\n  const i=pool[Math.floor(Math.random()*pool.length)];\n  const ok=say(L[i],{key:'ev-'+ev,gap,force,mood}); if(ok) used.push(i); return ok;\n}\n/* ギャル口調 */\nconst GAL=[[/なんじゃ/g,'え、なにそれ'],[/喝！/g,'ぴえん超えてぱおん！'],[/こら！/g,'ちょ待って！'],[/うむ/g,'それな'],[/いかん/g,'無理ぽ'],[/よか/g,'エモい'],[/ええ/g,'いい感じ'],\n  [/わしの/g,'ウチの'],[/わしは/g,'ウチは'],[/わしも/g,'ウチも'],[/わし/g,'ウチ'],[/お主/g,'きみ'],[/じゃな。/g,'じゃん？'],[/じゃな/g,'じゃん'],[/じゃぞ/g,'だよ〜'],[/じゃろ/g,'っしょ'],[/じゃ。/g,'じゃん♪'],[/じゃ！/g,'じゃん！マジで！'],[/じゃ(?!ん)/g,'じゃん'],\n  [/しとる/g,'してる'],[/っとる/g,'ってる'],[/とる/g,'てる'],[/せい。/g,'しよ？'],[/せい/g,'しよ'],[/のう/g,'じゃん'],[/ぞ。/g,'よ。'],[/ぞ！/g,'よ！'],[/んか。/g,'の？'],[/んか？/g,'の？'],[/かのう/g,'かな〜']];\nconst GAL_TAIL=['','','','マジ卍','、それな','〜','（笑）','、ヤバくね','、テンアゲ↑'];\nconst GAL_RATE=.05; // ギャル口調は「たまに」\nfunction galify(t){\n  if(!t) return t;\n  let s=t; for(const [a,b] of GAL) s=s.replace(a,b);\n  const tail=GAL_TAIL[Math.floor(Math.random()*GAL_TAIL.length)]; if(tail&&s.length<70) s=s.replace(/([。！？♪〜]?)$/,tail+'$1');\n  return s;\n}\nfunction voiceNote(){ return Math.random()<.3?'今回はなぜか、孫の口癖がうつって若者のギャル語（「〜じゃん」「マジ」「エモい」「ヤバい」「それな」など）がところどころ混ざってしまう。':''; }\n\n/* ---------- 親方 ---------- */\nconst masterEl=$('#master'), sayEl=$('#master-say');\nconst master={last:0,said:new Set(),timer:null,lastKey:{},choices:null};\nfunction inferMood(t){\n  if(/喝|こら|いかん|削っとる|はみ出しとる|当たっとる|どうする|やりすぎ|！$/.test(t)&&!/よか|ええ/.test(t)) return 'angry';\n  if(/なんじゃ|まさか|ほう|おっ/.test(t)) return 'surprised';\n  if(/文句なし|見事|天晴/.test(t)) return 'laugh';\n  if(/よか|ええ|そうじゃ|うむ|それでええ|上手い|見えてきた/.test(t)) return 'happy';\n  if(/？|迷/.test(t)) return 'thinking';\n  if(/焦るな|ちょっと待て|気を付け|注意/.test(t)) return 'worried';\n  return 'neutral';\n}\nfunction say(text,{force=false,key=null,once=false,gap=0,mood=null,choices=null}={}){\n  const now=performance.now();\n  if(once&&key&&master.said.has(key)) return false;\n  if(key&&gap&&master.lastKey[key]&&now-master.lastKey[key]<gap) return false;\n  if(!force&&(now-master.last<4200||master.choices)) return false;\n  const gal=Math.random()<GAL_RATE&&!napping&&[...text].length>4&&!choices; // 操作の案内（選択肢つき）は崩さない\n  if(gal){ text=galify(text); if(!master.said.has('galExcuse')){ master.said.add('galExcuse'); const said=text; setTimeout(()=>{ if(sayEl.textContent===said){ sayEl.textContent=said+'　…ゴホン。今のは忘れてくれ。孫の口癖がうつってしもうた。'; freshen(); setMood('worried'); } },Math.max(2600,[...text].length*70)); } } /* 指示を消さないよう、言い訳は後ろに付け足す */\n  master.last=now; if(key){ master.said.add(key); master.lastKey[key]=now; }\n  masterEl.classList.remove('min');\n  setMood(mood||inferMood(text),Math.max(3500,[...text].length*90));\n  if(choices||!master.choices) setChoices(choices); // 一言の割り込みでは、出ている選択肢（提出など）を消さない\n  clearInterval(master.timer);\n  showLine(text);\n  return true;\n}\nfunction freshen(){ sayEl.classList.remove('fresh'); void sayEl.offsetWidth; sayEl.classList.add('fresh'); }\nfunction speakFor(n){ // 文字数ぶん、口を動かしてモゴモゴ言う\n  clearInterval(master.timer); talking=!reduceMotion; let i=0;\n  master.timer=setInterval(()=>{ i+=2; if(i%4===0) babble(); if(i>=n){ clearInterval(master.timer); talking=false; } },55);\n}\nfunction showLine(text){ sayEl.textContent=text; freshen(); speakFor([...text].length); gesture('nod'); autoFold([...text].length); }\n// スマホでは、選択肢のない一言は読み終わる頃に吹き出しをたたむ（顔を押せば開く）\nfunction autoFold(n){ clearTimeout(master.foldT); if(innerWidth>=700) return; master.foldT=setTimeout(()=>{ if(!master.choices&&innerWidth<700&&state.step===1&&!carving) masterEl.classList.add('min'); else if(!master.choices&&innerWidth<700&&state.step===1) autoFold(4); },2400+n*120); }\nfunction sayHTML(html,talk=true){ clearInterval(master.timer); masterEl.classList.remove('min'); sayEl.innerHTML=html; master.last=performance.now(); talking=talk&&!reduceMotion; }\n(()=>{ const box=$('#master-choices'); box.classList.remove('choices'); box.classList.add('choice-bar'); stageEl.appendChild(box); })();\n// 帯の高さに合わせて、返事の帯を操作の帯のすぐ上に置く\nfunction placeChoiceBar(){ const h=$('#hud'); stageEl.style.setProperty('--choice-bottom',((h&&h.offsetHeight)||40)+26+'px'); }\nfunction setChoices(list){\n  placeChoiceBar(); const box=$('#master-choices'); box.innerHTML=''; master.choices=list&&list.length?list:null;\n  if(!master.choices) return;\n  master.choices.forEach(c=>{ const b=document.createElement('button'); b.type='button'; if(c.primary) b.className='primary'; b.textContent=c.label; if(c.primary){ const k=document.createElement('kbd'); k.textContent='Enter'; b.appendChild(k); } b.addEventListener('click',()=>pickChoice(c)); box.appendChild(b); });\n}\nfunction pickChoice(c){ setChoices(null); master.last=0; c.fn(); }\n$('#master-min').addEventListener('click',()=>masterEl.classList.add('min'));\n$('#master-face').addEventListener('click',()=>{ masterEl.classList.remove('min'); const n=bump('face',8000); talk('faceClick',{force:true,gap:0,mood:n>=3?'angry':['surprised','happy','thinking'][n%3]}); });\nlet lastActive=performance.now();\nfunction onStrokeStart(kind){\n  lastActive=performance.now(); updateBigHint();\n  if(kind==='fude'){\n    say('筆は立てて持て。手首じゃなく、腕で書くんじゃ。',{key:'fude1',once:true});\n    if(state.inkStrokes===4) say('手鏡を見てみい。押した時はあっちの向きになる。字なら鏡文字で書くんじゃぞ。',{key:'mirror',once:true});\n  } else {\n    if(state.strokes===1) say('刀を入れたな。力まんでよか。石の目に沿って、すっと引け。',{key:'k1',once:true,force:true});\n  }\n}\nfunction onStrokeEnd(c){\n  lastActive=performance.now();\n  const dur=performance.now()-c.t;\n  if(c.kind==='fude'){ if(state.inkCount/state.masks.insideCount>.35) talk('inkHeavy',{gap:30000,mood:'worried'}); return; }\n  if(c.kind!=='knife') return;\n  if(dur<160){ if(bump('tap',8000)>=5&&talk('tinyTaps',{force:true,mood:'worried'})) return; }\n  if(c.len>420&&talk('longStroke',{gap:45000,mood:'happy'})) return;\n  if((state.fineStrokes||0)>0&&state.fineStrokes%25===0&&talk('fineMany',{force:true,gap:0,mood:'surprised'})) return;\n  { const area=state.carvedCount/state.masks.insideCount; if(state.style!=='shu'&&area>.55&&talk('overCarve',{gap:30000,mood:'angry'})) return; }\n  const A=state.acc||{}, rimNew=state.rimCount-c.startRim;\n  if(rimNew>25&&say('こら！外枠に刀が当たっとる。枠が欠けたら縁起が悪かぞ。',{key:'rim',gap:25000})) return;\n  if(A.spill!=null&&A.spill>.15&&say(state.style==='shu'?'墨の線を削っとるぞ！朱文は線が命じゃ。':'墨からはみ出しとる！線の内側を彫れ。',{key:'spill',gap:25000})) return;\n  if(c.fast>3&&say('焦るな焦るな。石は逃げん。',{key:'fast',gap:30000})) return;\n  if(c.kind==='knife'&&toolInfo(state.tool).r>=14&&A.prog!=null&&A.prog>.6&&say('仕上げに大刀はいかん。小刀に持ち替えろ。',{key:'bigknife',once:true})) return;\n  if(A.prog!=null){\n    if(A.prog>.9&&say(pick(['ほぼ彫れたな。最後は真上から見て、線の太さを揃えろ。','あと少しじゃ。ここで欲張ると線が太る。','…ええとこまで来た。仕上げは息を止めて引け。']),{key:'p90',once:true})) return;\n    if(A.prog>.6&&say(pick(['半分は越えたな。ここからが本番じゃ。','折り返しじゃ。疲れた時ほど刀が滑る。','字が石から起きてきたな。']),{key:'p60',once:true})) return;\n    if(A.prog>.3&&say(pick(['うむ、形が見えてきた。','ほう、字の骨が出てきた。','その調子じゃ。急がんでええ。']),{key:'p30',once:true})) return;\n  }\n  if(chipsOnFace()>70&&say('かすが溜まっとる。「フッと吹く」で飛ばせ。線が見えんぞ。',{key:'chips',gap:40000})) return;\n  if(state.spinDeg>360&&say('そう、石を回して、刀を入れやすい向きにするんじゃ。',{key:'rot',once:true})) return;\n  const idle=['…うむ。','その刀の入り方、悪くない。','石の粉の匂い、ええじゃろ。','線は一本ずつじゃ。全部いっぺんに見るな。','手首が固い。肩で引け。','音が変わったら、石の目が変わった合図じゃ。','焦るな。石の目を読むんじゃ。','ほう、なかなか思い切りのいい線だ。','端の欠けも味になる。','…ええ音じゃ。','ええ音じゃ。石が素直に削れとる。','刀は寝かせすぎるな。立てすぎてもいかん。','息を止めるな。呼吸に合わせて刀を進めろ。','角は一気に行かず、両側から刀を入れるんじゃ。','縁が少し欠けるのは味じゃ。気にしすぎるな。','わしの師匠は、一本の線に一晩かけた。','手首で彫るな、肘から動かせ。','たまには手鏡を見い。押した姿を想像するんじゃ。'];\n  if(state.strokes%7===0) say(idle[(state.strokes/7|0)%idle.length],{key:'idle'+((state.strokes/7|0)%idle.length),gap:60000});\n}\n// 布字：手が止まって2.5秒たったら「書けたか？」と聞く（迷子にさせない）\nsetInterval(()=>{\n  if(!state.started||SHOW.on||SHOW.stage||state.step!==1||carving||master.choices||state.phase!=='fuji'||!state.inkStrokes||howtoOpen) return;\n  if(performance.now()-lastActive>2500&&inkAmount()>20)\n    say(pick(['書けたか？','ほう、それを彫るんか。書けたなら言え。','下書きはそれでええか？']),{force:true,key:'askDone',gap:25000,mood:'thinking',choices:[CH.done,CH.more]});\n},600);\nsetInterval(()=>{\n  if(!state.started||SHOW.on||SHOW.stage) return; // 入門画面や据え付け中は黙っとく\n  if(state.step===2||state.step===1&&!carving) weirdEvent();\n  if(state.step!==1||carving) return;\n  const quiet=performance.now()-lastActive;\n  checkNap(quiet);\n  { const lvl=state.spinDeg>2400?2:state.spinDeg>900?1:0; if(lvl>(state.spinTalk||0)){ state.spinTalk=lvl; talk(lvl===2?'spin2':'spin1',{force:true,gap:0,mood:'surprised'}); } }\n  if(state.startT){ const m=(performance.now()-state.startT)/60000; if(m>10&&!state.lt10){ state.lt10=1; talk('longSession',{force:true}); } if(m>20&&!state.lt20){ state.lt20=1; talk('longSession',{force:true}); } }\n  if(state.phase==='carve'&&quiet>9000&&quiet<20000&&lastClient){ const p=hitUV(lastClient.x,lastClient.y); if(p&&insideAt(p)) talk('hoverIdle',{gap:40000,mood:'thinking'}); }\n  if(!master.choices&&state.phase==='carve'&&quiet>4500){\n    const A=state.acc||{}, area=state.carvedCount/state.masks.insideCount;\n    if((A.prog!=null&&A.prog>.5)||(A.prog==null&&area>.06)||state.strokes>=12) say('できたと思ったら、そこの呼び鈴を鳴らせ。完成かどうかは、お主が決めることじゃ。',{key:'bellhint',once:true,mood:'happy'});\n  }\n  if(state.phase==='carve'&&quiet>25000) { say('手が止まっとるな。迷うたら真上から見てみい。',{key:'stuck',gap:60000}); }\n  if(state.phase==='fuji'&&quiet>30000&&state.inkStrokes===0) say('何を書くか迷っとるのか？自分の名前でも、好きな字でも、絵でもええ。',{key:'fujiStuck',gap:60000});\n},4000);\n\n\n/* 親方のボケ・くしゃみ・居眠り */\nconst WEIRD=[\n  ['そういえば昨日、桜島の灰でおにぎりを握る夢を見た。','thinking'],\n  ['わしの若い頃は、印鑑一本で家が建ったもんじゃ。…いや、言いすぎた。','happy'],\n  ['…今の音、聞こえたか？石が「くすぐったい」と言うとる。','surprised'],\n  ['この印床、わしより年上じゃ。','proud'],\n  ['ハンコの「ハン」は、半分の「ハン」…ではない。たぶん。','thinking'],\n  ['弟子に「ハンコってスマホで押せないんですか」と聞かれた日のことは忘れん。','worried'],\n  ['芋けんぴを食べながら彫ると、線が甘くなるぞ。経験談じゃ。','happy'],\n  ['…すまん、今ちょっと入れ歯がずれた。','worried'],\n  ['昔、上司の印を逆さに押して出世した男がおった。理由は誰も知らん。','thinking'],\n  ['わしの夢は、桜島にでっかい印鑑を押すことじゃ。','proud'],\n  ['この石は二億歳くらいじゃ。お主よりだいぶ先輩じゃぞ。','happy'],\n  ['ちなみにわしの実印、自分で彫ったら名前を一字間違えとった。四十年使っとる。','laugh'],\n  ['…腹減ったな。黒豚まん食いたい。','worried'],\n  ['ふむ…お主、前世はハンコじゃったかもしれん。','thinking'],\n  ['このハチマキ、実は家内の手ぬぐいじゃ。内緒にしといてくれ。','laugh'],\n  ['朱肉と明太子を間違えたことが一度だけある。一度だけじゃ。','surprised'],\n  ['石と話せるようになったら一人前じゃ。わしはまだ相槌しか打てん。','proud'],\n  ['最近の若いもんは、印鑑を「押す」じゃなくて「タップ」するらしいな。','worried'],\n  ['…この店、Wi-Fiあるんか？と聞かれたことがある。印房にあるわけなかろう。…あるけどな。','laugh'],\n  ['昨日、猫に朱肉を踏まれた。床が判子だらけじゃ。肉球の。','happy'],\n  ['わしの彫った印で、婚姻届が三百枚は出とる。離婚届は…数えとらん。','thinking'],\n  ['印鑑は「押す」もんじゃない。「捺す」もんじゃ。…どっちでもええか。','thinking'],\n  ['孫が「じいちゃんの店、エモい」と言うとった。褒められとるんか？','worried'],\n  ['三十年前、この刀で鰹節を削ったことがある。家内にえらい怒られた。','laugh'],\n  ['…今、石が笑った気がせんかったか。','surprised']\n];\nlet weirdNext=performance.now()+60000+Math.random()*60000, napping=false;\nfunction weirdEvent(){\n  const now=performance.now();\n  if(now<weirdNext||master.choices||now-master.last<9000) return;\n  weirdNext=now+70000+Math.random()*80000;\n  if(state.step===1&&state.phase==='carve'&&Math.random()<.22){ sneeze(); return; }\n  if(sampleNs&&state.step===1&&state.phase==='carve'&&Math.random()<.35){ aiBoke(); return; }\n  const pool=WEIRD.filter(w=>!master.said.has('w:'+w[0])); const w=(pool.length?pool:WEIRD)[Math.floor(Math.random()*(pool.length||WEIRD.length))];\n  say(w[0],{key:'w:'+w[0],mood:w[1]});\n}\nfunction sneeze(){\n  say('は…はっ…',{force:true,mood:'surprised'});\n  setTimeout(()=>{ say('へっくしょん！！',{force:true,mood:'angry'}); shake=1; blow(); noise(900,.5,.18,.35,'lowpass'); setTimeout(()=>say('…すまん。かすが全部飛んだな。ちょうどええ。',{force:true,mood:'happy'}),1800); },1300);\n}\nasync function aiBoke(){\n  try{\n    const w=document.createElement('canvas'); w.width=w.height=N; const x=w.getContext('2d'); x.fillStyle='#fff'; x.fillRect(0,0,N,N); x.drawImage(Cc,0,0);\n    const opts={modelTier:'quick'}; try{ const lim=await sampleNs.limits(); if(lim&&lim.images) opts.images=[await toBlob(w)]; }catch(_){}\n    const res=await sampleNs('あなたは鹿児島の印房の70代の親方「源じい」。弟子が石の印面を彫っている最中（画像は今の印面）。作業とほぼ関係ない、ちょっとズレた・とぼけた独り言を1つだけ言う。少し鹿児島弁（「〜じゃ」「よか」程度）。'+voiceNote()+'30字以内、話し言葉のみ、かぎかっこ不要。人を傷つける内容は禁止。',opts);\n    if(res&&res.text) say(res.text.trim().replace(/^「|」$/g,''),{mood:'thinking'});\n  }catch(e){ const w=WEIRD[Math.floor(Math.random()*WEIRD.length)]; say(w[0],{mood:w[1]}); }\n}\nfunction checkNap(quiet){\n  if(state.step!==1||napping||master.choices||carving) return;\n  if(quiet>50000&&performance.now()-master.last>20000){ napping=true; say('……すぅ……すぅ……',{force:true,mood:'proud'}); moodUntil=performance.now()+600000; talking=false; }\n}\nfunction wakeUp(){\n  if(!napping) return; napping=false;\n  say(['はっ！寝とらんぞ。目を閉じて石の声を聞いとったんじゃ。','…ん？おお、すまん。で、どこまで彫った？','いかん、ちょっと桜島が噴火する夢を見とった。'][Math.floor(Math.random()*3)],{force:true,mood:'surprised'});\n}\n\n/* 検分（親方に見せる） */\nfunction reviewScore(){\n  const A=state.acc||{}, secs=state.carveMs/1000, area=state.carvedCount/state.masks.insideCount;\n  let s;\n  if(A.prog==null) s=45+Math.min(15,secs/20)-(area<.03?30:0);\n  else s=100-(1-Math.min(1,A.prog))*55-A.spill*140;\n  s-=state.rimF*160; s+=Math.min(8,state.strokes/20);\n  // 甘すぎ防止：数秒で彫っただけなら最高でも「良」、字が簡単（布字が少ない）なら「秀」は出さない\n  const capped={fast:false,easy:false};\n  if(secs<25){ if(s>70) capped.fast=true; s=Math.min(s,70); }\n  const inkFrac=state.inkCount/Math.max(1,state.masks.insideCount);\n  if(state.inkStrokes&&inkFrac<.07){ if(s>80) capped.easy=true; s=Math.min(s,80); }\n  s=clamp(Math.round(s),0,100);\n  const grade=s>=88?'秀':s>=74?'優':s>=58?'良':s>=40?'可':'喝';\n  return {score:s,grade,capped,inkFrac};\n}\nfunction reviewText(){\n  const A=state.acc||{}, secs=Math.round(state.carveMs/1000), area=state.carvedCount/state.masks.insideCount, R=reviewScore(), grade=R.grade;\n  const t=[]; const fast=secs<25&&state.strokes>0;\n  // 1. 下書きとの関係\n  if(!state.inkStrokes) t.push(pick(['下書きなしで彫ったな。度胸はある。だが、次は布字からやれ。','いきなり刀か。…石に聞いてから彫れ、と昔わしも言われた。','下書きなしとはな。職人の真似事にしては肝が据わっとる。']));\n  else if(A.prog!=null&&A.prog<.5) t.push(pick([`布字の${pct(1-A.prog)}がまだ彫れとらん。途中で見せに来るな。`,`まだ${pct(1-A.prog)}も残っとる。腹八分目にも早いぞ。`,`半分も彫れとらんな。墨がまだ笑っとる。`]));\n  else if(A.prog!=null) t.push(A.prog>.95?pick([`布字の${pct(Math.min(1,A.prog))}まで彫れとる。`,'墨の線は、ほぼ刀が拾うたな。','下書きの線を、よう最後まで追うた。']):pick([`布字の${pct(A.prog)}まで彫れとる。`,`${pct(A.prog)}か。あと一息ってとこじゃ。`]));\n  // 2. はみ出し\n  if(A.spill!=null) t.push(A.spill>.15?(state.style==='shu'?pick(['墨の線をだいぶ削ってしもうたな。','朱文で線を削るのは、自分の名前を消すのと同じじゃ。']):pick(['墨からのはみ出しが多い。線の内側を狙え。','刀が線の外へ散歩しとる。','はみ出しが目立つ。刀先を見るな、線の先を見ろ。'])):A.spill<.04?pick(['線の外に刀が出とらん。ええ手じゃ。','はみ出しがほとんどない。手が落ち着いとる。','刀が線の中に収まっとる。これは褒めとくぞ。']):pick(['はみ出しは少しある。気にするほどではない。','ちいとはみ出しとるが、味のうちじゃ。']));\n  // 3. 外枠・面積・研ぎ直し・形\n  if(state.rimF>.06) t.push(pick(['外枠が欠けとる。印は枠が締まっとらんといかん。','枠が欠けると、運も逃げる…と言うのは迷信じゃが、見た目は締まらん。']));\n  if(area<.03) t.push(pick(['ほとんど彫っとらんぞ。これじゃ朱のかたまりが押されるだけじゃ。','これは印か？朱肉の見本か？']));\n  else if(state.style!=='shu'&&area>.5) t.push('彫りすぎて、残す所が少ない。押したら白い面になるぞ。');\n  if(R.capped&&R.capped.easy) t.push(pick(['字が簡単じゃから、腕の見せ所が少なかったな。','画数が少ない字は、ごまかしが利かんぶん難しいんじゃがな。…次はもっと込み入った字に挑め。']));\n  if(state.regrinds) t.push(pick([`${state.regrinds}回も研ぎ直した根性は認める。`,`研ぎ直し${state.regrinds}回。諦めの悪さは職人向きじゃ。`]));\n  if(state.shape==='square'&&area>.03) t.push(pick(['角印は四隅が勝負じゃ。','角の印は、隅に気が抜けやすい。']));\n  // 4. 時間（早すぎる場合は、締めも合わせる）\n  if(secs>180) t.push(pick([`${fmtTime(secs*1000)}も向き合ったか。その執念は印に出る。`,`${fmtTime(secs*1000)}か。茶が三杯は冷めたな。`]));\n  else if(fast) t.push(pick(['しかし早すぎる。もっと石と向き合え。','ずいぶん早う仕上げたな。速さは褒めんぞ。','あっという間じゃったな。石の方が驚いとる。']));\n  // 5. 締め\n  const close={\n    秀:['…文句なしじゃ。うちで働かんか。','よか。…今のは、わしの若い頃より上手い。','…何も言うことはない。押してこい。'],\n    優:['よか出来じゃ。胸を張って押してこい。','ええ印じゃ。上司も文句は言えんじゃろ。','しっかり彫れとる。あとは押し方じゃ。'],\n    良:fast?['筋は悪くない。次は時間をかけてみい。','手は動く。あとは急がんことじゃ。','形にはなっとる。次はもう少し石と話せ。']:['まあまあじゃ。押してみればわかる。','悪くはない。が、良くもない。伸びしろじゃ。','このくらいが一番楽しい頃じゃ。'],\n    可:['ギリギリ印鑑と呼べる。','印鑑…と呼んでやらんこともない。','押せば何とかなる。たぶんな。'],\n    喝:['喝！ …と言いたいが、最初はみんなこんなもんじゃ。','喝じゃ！ …まあ、刀を持っただけ偉い。','喝！ わしの最初の一本も、こんなもんじゃった。']\n  }[grade];\n  t.push(pick(close));\n  return t.join('');\n}\nfunction ding(){ if(!actx||muted) return; try{ const t=actx.currentTime; [[1568,.16],[3136,.06],[4704,.03]].forEach(([f,v])=>{ const o=actx.createOscillator(), g=actx.createGain(); o.type='sine'; o.frequency.value=f; g.gain.setValueAtTime(.0001,t); g.gain.exponentialRampToValueAtTime(v,t+.005); g.gain.exponentialRampToValueAtTime(.0001,t+1.6); o.connect(g).connect(actx.destination); o.start(t); o.stop(t+1.7); }); }catch(e){} }\nfunction ringBell(){\n  ensureAudio(); ding();\n  if(bump('bell',10000)>=3){ talk('bellSpam',{force:true,gap:0,mood:'angry'}); return; }\n  if(state.phase==='paint'||state.phase==='fuji'){ say(state.phase==='fuji'?'まだ一刀も入っとらんじゃろ。まずは刀を取れ。':'まだ朱を塗っとる。',{force:true,mood:'surprised'}); return; }\n  if(state.phase==='press'){ say('もう押す段じゃ。',{force:true}); return; }\n  if(state.strokes===0){ say('鈴を鳴らすのは彫ってからじゃ。',{force:true,mood:'worried'}); return; }\n  say(pick(['ほう、完成か。見せてみい。','できたか。どれ、持ってこい。','鈴が鳴ったな。…見せてみい。']),{force:true,mood:'thinking',choices:[{label:'親方に見せる',primary:true,fn:()=>review()},{label:'やっぱりまだ彫る',fn:()=>say('納得いくまで彫れ。完成はお主が決めることじゃ。',{force:true,mood:'proud'})}]});\n}\nconst GRADES=['秀','優','良','可','喝'];\nasync function review(selfGrade=null){\n  updateStats();\n  const r=reviewScore(); state.review=r; state.selfGrade=selfGrade; setPhase('review');\n  setChoices(null); setMood('thinking',4000); sayHTML('<span class=\"thinking\">どれ、見せてみい…</span>',false);\n  blow(); view.tElev=1.55; view.tDist=5.6;\n  await new Promise(res=>setTimeout(res,reduceMotion?0:1100));\n  sayHTML('<span class=\"thinking\">ふっ…（かすを吹いて、和紙に試し押し）</span>',false); thump(140,50,.35,.16);\n  const trial=makeImpression(printSurface(),.62,.78,(Math.random()*1e9)|0).canvas.toDataURL('image/png');\n  const head=`<img class=\"trial\" src=\"${trial}\" alt=\"親方の試し押し\"><span class=\"grade\">${r.grade}</span>`;\n  await new Promise(res=>setTimeout(res,reduceMotion?0:900));\n  sayHTML(head+'<span class=\"thinking\">…</span>',false);\n  let text=null, fromAI=false;\n  if(sampleNs){\n    try{\n      const opts={modelTier:'quick',onText:({text})=>{ sayHTML(head+esc(text)); }};\n      try{ const lim=await sampleNs.limits(); if(lim&&lim.images){ const w=document.createElement('canvas'); w.width=w.height=N; const x=w.getContext('2d'); x.fillStyle='#fff'; x.fillRect(0,0,N,N); x.drawImage(Cc,0,0); opts.images=[await toBlob(w)]; } }catch(_){}\n      const A=state.acc||{};\n      const data={工程:state.style==='haku'?'白文（墨の字を彫る）':state.style==='shu'?'朱文（墨の字を残す）':'下書きなし',布字の彫り進み:A.prog==null?'―':pct(Math.min(1,A.prog)),はみ出しや線の欠け:A.spill==null?'―':pct(A.spill),外枠の欠け:pct(state.rimF),彫った面積:pct(state.carvedCount/state.masks.insideCount),彫った時間:fmtTime(state.carveMs),刀数:state.strokes,筆数:state.inkStrokes,研ぎ直し:state.regrinds,評価:r.grade};\n      const res=await sampleNs(`あなたは鹿児島の小さな印房の親方「源じい」。70代の職人で、口は悪いが面倒見がいい。少しだけ鹿児島弁が混じる（「よか」「〜じゃ」「〜ど」程度）。${voiceNote()}\n弟子が初めて石の印材を彫り、見せに来た。画像は彫り上がった印面を真上から見たもの（朱が塗られた面が残った部分、白っぽい所が彫った所、黒い線は筆の下書き）。\nまず何を彫ったのか（字・絵・模様）を見立てて一言触れ、次に数字に具体的に触れながら、職人らしく褒めるところと直すところを言うこと。最後は短い励まし。\n評価は「${r.grade}」で確定しているので、その評価と矛盾しないように。話し言葉のみ、120〜170字、改行なし、記号の見出しは使わない。\n書き方の決まり：前置きなしで本題から書く。計測データの数字を2つ以上そのまま引用する。データと画像にないこと（性格の断定、過去の出来事、実績の数字）は作らない。「素晴らしい」「圧倒的」「魂」「宿る」のような大げさな言葉や抽象語は使わず、何がどうなっているかを書く。同じ内容の言い換えや、最後のまとめ・呼びかけは書かない。\n計測：${JSON.stringify(data)}`,opts);\n      if(res&&res.text){ text=res.text.trim(); fromAI=true; }\n    }catch(err){ if(err&&(err.code==='not_granted'||err.code==='unavailable')){ sampleNs=null; updateEngine(); } }\n  }\n  if(!text) text=reviewText();\n  if(!fromAI&&Math.random()<GAL_RATE) text=galify(text);\n  if(!fromAI){ sayHTML(head+esc(text),false); freshen(); speakFor([...text].length); await new Promise(r=>setTimeout(r,reduceMotion?0:Math.min(2200,[...text].length*40))); }\n  sayHTML(head+esc(text),false);\n  setMood({秀:'laugh',優:'proud',良:'happy',可:'worried',喝:'angry'}[r.grade],6000);\n  setChoices([{label:'稟議書に押しに行く',primary:true,fn:()=>startPress()},{label:'もう少し彫る',fn:()=>{ setPhase('carve'); say('納得いくまで彫れ。それが職人じゃ。',{force:true,mood:'proud'}); }},{label:'研ぎ直して最初から',fn:()=>$('#btn-grind').click()},{label:'別の石・形で彫る',fn:()=>openShelf()}]);\n  $('#st-grade').textContent=r.grade;\n}\n\n/* ---------- 音 ---------- */\nlet actx=null, noiseBuf=null, muted=false, lastScrape=0;\nfunction ensureAudio(){ if(actx||muted) return; try{ actx=new (window.AudioContext||window.webkitAudioContext)(); const len=Math.floor(actx.sampleRate*.6); noiseBuf=actx.createBuffer(1,len,actx.sampleRate); const ch=noiseBuf.getChannelData(0); for(let i=0;i<len;i++) ch[i]=Math.random()*2-1; startAmbience(); }catch(e){ actx=null; } }\nlet ambT=null, tickN=0;\nfunction babble(){ // 親方のモゴモゴ声\n  if(!actx||muted||napping) return;\n  const galUp=0;\n  try{ const t=actx.currentTime, o=actx.createOscillator(), f=actx.createBiquadFilter(), g=actx.createGain(); o.type='sawtooth';\n    const base=(moodName==='angry'?130:moodName==='surprised'?150:100)+Math.random()*35+galUp; o.frequency.setValueAtTime(base,t); o.frequency.linearRampToValueAtTime(base*(.8+Math.random()*.35),t+.08);\n    f.type='bandpass'; f.frequency.value=450+Math.random()*650; f.Q.value=2.5;\n    g.gain.setValueAtTime(.0001,t); g.gain.exponentialRampToValueAtTime(moodName==='angry'?.07:.045,t+.012); g.gain.exponentialRampToValueAtTime(.0001,t+.085);\n    o.connect(f).connect(g).connect(actx.destination); o.start(t); o.stop(t+.1); }catch(e){}\n}\nfunction startAmbience(){\n  if(ambT) return;\n  ambT=setInterval(()=>{ // 柱時計のカチ、コチ\n    if(!actx||muted||document.hidden) return;\n    tickN++; noise(tickN%2?2600:2200,9,.018,.025);\n    if(napping&&tickN%3===0) noise(260,.6,.05,1.3,'lowpass'); // いびき\n    if(state.step===1&&Math.random()<.012) noise(180,.5,.03,1.4,'lowpass'); // 遠くを車が通る\n  },1000);\n}\nfunction noise(freq,q,vol,dur,type='bandpass'){\n  if(!actx||muted) return;\n  try{ const t=actx.currentTime, src=actx.createBufferSource(), f=actx.createBiquadFilter(), g=actx.createGain(); src.buffer=noiseBuf; f.type=type; f.frequency.value=freq; f.Q.value=q;\n    g.gain.setValueAtTime(.0001,t); g.gain.exponentialRampToValueAtTime(vol,t+Math.min(.01,dur/4)); g.gain.exponentialRampToValueAtTime(.0001,t+dur);\n    src.connect(f).connect(g).connect(actx.destination); src.start(t); src.stop(t+dur+.02); }catch(e){}\n}\nfunction scrape(){ if(carving&&carving.cutNow===0) return; const now=performance.now(), sp=carving&&carving.sp?clamp(carving.sp,.3,2.2):1; if(now-lastScrape<70/Math.sqrt(sp)) return; lastScrape=now; const r=toolInfo(state.tool).r, br=STONES[state.mat].brittle; noise((3400-r*90)*(.85+br*.15)+Math.random()*1500+sp*500,1.6,(.05+r*.004)*(.6+sp*.45),.045); if(Math.random()<.25+br*.15) noise(6200,3,.035*sp,.02); }\nfunction whoosh(){ noise(700,.6,.12,.45,'lowpass'); }\nfunction grindSound(){ for(let k=0;k<6;k++) setTimeout(()=>noise(1400+Math.random()*400,.8,.08,.18),k*140); }\nfunction thump(f0,f1,vol,dur){ if(!actx||muted) return; try{ const t=actx.currentTime, o=actx.createOscillator(), g=actx.createGain(); o.type='sine'; o.frequency.setValueAtTime(f0,t); o.frequency.exponentialRampToValueAtTime(f1,t+dur); g.gain.setValueAtTime(.0001,t); g.gain.exponentialRampToValueAtTime(vol,t+.006); g.gain.exponentialRampToValueAtTime(.0001,t+dur); o.connect(g).connect(actx.destination); o.start(t); o.stop(t+dur+.02); }catch(e){} }\n$('#sound').addEventListener('click',e=>{ muted=!muted; e.currentTarget.textContent=muted?'音：オフ':'音：オン'; e.currentTarget.setAttribute('aria-pressed',String(!muted)); if(!muted) ensureAudio(); });\n\n/* ---------- 描画ループ ---------- */\n\nlet prevT=performance.now(), statT=0; const perf={acc:0,n:0,level:0};\n/* ---------- 入門：宙で回る石 → 印床に据える ---------- */\nconst SHOW={on:true,lift:2.4,jaw:1,t:0,seat:null,stage:0};\nfunction setShowcase(on){\n  SHOW.on=on;\n  if(on){ SHOW.seat=null; SHOW.stage=0; view.tgtT.set(0,FACE_Y+(innerWidth<700?.55:1.05),0); view.tElev=.18; view.tDist=innerWidth<700?16:12.5; view.tAz=Math.round(view.tAz/(Math.PI*2))*Math.PI*2+.5; lamp.target.position.set(0,FACE_Y+2,0); }\n}\nfunction seatStone(cb){\n  SHOW.on=false; SHOW.seat=cb||(()=>{}); SHOW.stage=1;\n  view.tgtT.set(0,FACE_Y-.2,0); view.tElev=.74; view.tDist=10.5; view.tAz=Math.round(view.tAz/(Math.PI*2))*Math.PI*2; lamp.target.position.set(0,FACE_Y,0);\n  if(reduceMotion){ SHOW.lift=0; SHOW.jaw=0; }\n  whoosh();\n}\nfunction updateShowcase(dt){\n  SHOW.t+=dt;\n  if(SHOW.on){\n    SHOW.lift+=(2.4-SHOW.lift)*Math.min(1,dt*3); SHOW.jaw+=(1-SHOW.jaw)*Math.min(1,dt*4);\n    seal.rotation.y=(seal.rotation.y+dt*.55)%(Math.PI*2);\n    seal.rotation.x+=(.42-seal.rotation.x)*Math.min(1,dt*3);\n    seal.position.y=FACE_Y+SHOW.lift+Math.sin(SHOW.t*1.4)*.07;\n  } else if(SHOW.stage===1){ // 向きを戻しながら下ろす\n    const ry=seal.rotation.y, tgt=ry>Math.PI?Math.PI*2:0;\n    seal.rotation.y+=(tgt-ry)*Math.min(1,dt*5); seal.rotation.x+=(0-seal.rotation.x)*Math.min(1,dt*6);\n    SHOW.lift=Math.max(0,SHOW.lift-dt*(1.2+SHOW.lift*1.6));\n    seal.position.y=FACE_Y+SHOW.lift;\n    if(SHOW.lift<=0&&Math.abs(seal.rotation.x)<.01&&Math.abs(tgt-seal.rotation.y)<.01){ seal.rotation.set(0,0,0); seal.position.y=FACE_Y; SHOW.stage=2; thump(90,50,.35,.14); }\n  } else if(SHOW.stage===2){ // 挟み板を締める\n    SHOW.jaw=Math.max(0,SHOW.jaw-dt*4.5);\n    if(SHOW.jaw<=0){ SHOW.stage=0; shake=.7; thump(170,60,.55,.12); noise(1800,1.2,.18,.08); puffDust(26); const cb=SHOW.seat; SHOW.seat=null; setTimeout(cb,280); }\n  }\n  for(const [m,x0,dir] of viseJaws) m.position.x=x0+dir*SHOW.jaw*1.1;\n}\nfunction puffDust(n){ for(let k=0;k<n;k++){ const d=dusts[dustHead]||(dusts[dustHead]={p:new THREE.Vector3(),v:new THREE.Vector3(),life:0}); const side=k%2?1:-1; d.p.set(side*(R+.1),FACE_Y-.6-Math.random()*.6,(Math.random()-.5)*2.4); d.v.set(side*(.6+Math.random()),.3+Math.random()*.8,(Math.random()-.5)*.8); d.life=1; dustHead=(dustHead+1)%MAXD; } }\nfunction loop(now){\n  requestAnimationFrame(loop);\n  const rawDt=Math.min(.25,Math.max(0,(now-prevT)/1000)), dt=Math.min(.05,rawDt); prevT=now;\n  updateMaster(dt,now/1000);\n  if(state.step===3) updateShow(dt);\n  if(state.step!==1) return;\n  if(state.phase==='paint'&&state.started&&state.paintArmed&&!SHOW.stage&&!SHOW.on&&!howtoOpen){\n    state.paintT=clamp((now-paintStart)/2200,0,1); compose();\n    if(state.paintT>=1) finishPaint();\n  }\n  if(SHOW.on||SHOW.stage) updateShowcase(rawDt); // 重い端末でも据え付けが間延びしないよう実時間で\n  updateCamera(dt);\n  if(carving&&lastClient&&(view.auto||camMoved)) carveTo(lastClient.x,lastClient.y);\n  if(texDirty){\n    if(carveDirty){ updateNormals(carveDirty.x0,carveDirty.y0,carveDirty.x1,carveDirty.y1); carveDirty=null; heightTex.needsUpdate=normalTex.needsUpdate=true; }\n    compose(); texDirty=false;\n  }\n  if(now-statT>250){ statT=now; if(carving) updateStats(); }\n  stepParticles(dt);\n  if(state.phase==='press') updatePress(dt,now); else placeTool(now);\n  perf.acc+=dt; perf.n++;\n  if(perf.acc>2){ const avg=perf.acc/perf.n; perf.acc=0; perf.n=0;\n    if(avg>.034&&perf.level<2){ perf.level++; if(perf.level===1){ renderer.setPixelRatio(1); resize(); } else { lamp.shadow.mapSize.set(1024,1024); if(lamp.shadow.map){ lamp.shadow.map.dispose(); lamp.shadow.map=null; } } } }\n  renderer.render(scene,camera);\n  placeOverlays(); drawLoupe();\n}\nconst loupeCv=$('#loupe'), loupeX=loupeCv.getContext('2d');\nfunction drawLoupe(){\n  const on=!!(carving&&carving.touch&&lastClient);\n  if(loupeCv.hidden===on) loupeCv.hidden=!on;\n  if(!on) return;\n  const sr=stageEl.getBoundingClientRect(), gr=glCv.getBoundingClientRect(), pr=glCv.width/gr.width;\n  const fx=lastClient.x-gr.left, fy=lastClient.y-gr.top, src=46*pr; // 指の周り約92pxを2.6倍で見せる\n  loupeX.drawImage(glCv,fx*pr-src,fy*pr-src,src*2,src*2,0,0,240,240);\n  loupeX.strokeStyle='rgba(255,255,255,.9)'; loupeX.lineWidth=2; loupeX.beginPath(); loupeX.arc(120,120,5,0,Math.PI*2); loupeX.stroke();\n  // 指の反対側の上へ。上が詰まっていれば横へ\n  let lx=lastClient.x-sr.left+(lastClient.x-sr.left>sr.width/2?-150:30), ly=lastClient.y-sr.top-170;\n  if(ly<8) ly=lastClient.y-sr.top+50;\n  loupeCv.style.left=clamp(lx,6,sr.width-126)+'px'; loupeCv.style.top=clamp(ly,6,sr.height-126)+'px';\n}\n\n/* ---------- 二 押す ---------- */\nconst DW=960, DH=600, STAMP=86;\nconst BOX={w:104,h:136,head:30,y:44}, LABELS=['社長','部長','課長','担当'];\nconst boxX=k=>DW-44-(4-k)*BOX.w;\nconst boxCenter=k=>({x:boxX(k)+BOX.w/2,y:BOX.y+BOX.head+(BOX.h-BOX.head)/2});\nfunction boxIndexAt(x,y){ for(let k=0;k<4;k++){ const bx=boxX(k); if(x>=bx&&x<bx+BOX.w&&y>=BOX.y+BOX.head&&y<BOX.y+BOX.h) return k; } return -1; }\nconst docCv=$('#doc'), dctx=docCv.getContext('2d'), docBase=document.createElement('canvas'); docBase.width=DW; docBase.height=DH;\nlet bossImps=[];\nfunction cvPt(cv,e){ const r=cv.getBoundingClientRect(); return {x:(e.clientX-r.left)/r.width*cv.width,y:(e.clientY-r.top)/r.height*cv.height}; }\nfunction drawImp(ctx,cv,x,y,angle,S){ ctx.save(); ctx.translate(x,y); ctx.rotate(angle*Math.PI/180); ctx.globalCompositeOperation='multiply'; ctx.drawImage(cv,-S/2,-S/2,S,S); ctx.restore(); }\nfunction buildDocBase(){\n  const x=docBase.getContext('2d'), r=mulberry32(7), G='\"Zen Kaku Gothic New\",\"Hiragino Sans\",sans-serif';\n  x.fillStyle='#f7f2e7'; x.fillRect(0,0,DW,DH);\n  for(let k=0;k<900;k++){ x.strokeStyle=`rgba(120,100,70,${.04+r()*.07})`; x.lineWidth=.5+r()*1.2; x.beginPath(); const sx=r()*DW, sy=r()*DH; x.moveTo(sx,sy); x.quadraticCurveTo(sx+(r()-.5)*30,sy+(r()-.5)*30,sx+(r()-.5)*50,sy+(r()-.5)*50); x.stroke(); }\n  x.fillStyle='#2a2320'; x.font='800 40px \"Shippori Mincho B1\",\"Hiragino Mincho ProN\",serif'; x.fillText('稟　議　書',56,96);\n  x.fillStyle='#4a3f38'; x.font=`400 17px ${G}`;\n  const t=new Date(); x.fillText(`起案日　${t.getFullYear()}年${t.getMonth()+1}月${t.getDate()}日`,58,140);\n  x.fillText('起案者　担当（あなた）',58,172);\n  x.fillText('標記の件について、下記のとおり稟議いたします。',58,226);\n  x.strokeStyle='#8a7a6a'; x.lineWidth=1;\n  let y=282;\n  [['件　名','おやつ（芋けんぴ）購入の件'],['金　額','298円（税込）'],['目　的','午後の集中力を維持するため'],['備　考','至急。おやつの時間（15:00）までにご承認ください']].forEach(([k,v])=>{\n    x.font=`700 16px ${G}`; x.fillStyle='#6b5a4c'; x.fillText(k,58,y);\n    x.font=`400 19px ${G}`; x.fillStyle='#2a2320'; x.fillText(v,150,y);\n    x.beginPath(); x.moveTo(56,y+16); x.lineTo(DW-56,y+16); x.stroke(); y+=62;\n  });\n  x.font=`400 16px ${G}`; x.fillStyle='#4a3f38'; x.textAlign='right'; x.fillText('以上',DW-60,DH-36); x.textAlign='left';\n  for(let k=0;k<4;k++){\n    const bx=boxX(k); x.strokeStyle='#6b5a4c'; x.lineWidth=1.4; x.strokeRect(bx,BOX.y,BOX.w,BOX.h);\n    x.beginPath(); x.moveTo(bx,BOX.y+BOX.head); x.lineTo(bx+BOX.w,BOX.y+BOX.head); x.stroke();\n    x.font=`700 15px ${G}`; x.fillStyle='#4a3f38'; x.textAlign='center'; x.fillText(LABELS[k],bx+BOX.w/2,BOX.y+21); x.textAlign='left';\n  }\n  const angles=[0,-7,-19];\n  bossImps.forEach((cv,k)=>{ const c=boxCenter(k); drawImp(x,cv,c.x+(k-1)*2,c.y+(k%2?3:-2),angles[k],STAMP); });\n}\nlet hover=null, press=null;\nfunction drawDoc(g){\n  dctx.drawImage(docBase,0,0);\n  state.stamps.forEach(s=>{\n    const age=s.t0?performance.now()-s.t0:999;\n    if(age<260){ const k=age/260, sz=STAMP*(1+.14*(1-k)*(1-k)); dctx.save(); dctx.globalAlpha=.25*(1-k); dctx.fillStyle='#000'; dctx.beginPath(); dctx.arc(s.x+3,s.y+4,STAMP*.55*(1-k*.3),0,Math.PI*2); dctx.fill(); dctx.restore(); drawImp(dctx,s.cv,s.x,s.y,s.angle,sz); }\n    else drawImp(dctx,s.cv,s.x,s.y,s.angle,STAMP);\n  });\n  if(g){\n    const sc=STAMP/N;\n    dctx.save(); dctx.translate(g.x,g.y); dctx.rotate(state.angle*Math.PI/180); dctx.scale(sc,sc); dctx.translate(-N/2,-N/2);\n    dctx.setLineDash([22,16]); dctx.lineWidth=1.6/sc; dctx.strokeStyle='rgba(194,31,43,.75)'; shapePath(dctx,state.shape,0); dctx.stroke(); dctx.setLineDash([]);\n    dctx.fillStyle='rgba(194,31,43,.8)'; dctx.beginPath(); dctx.moveTo(N/2-26,-14); dctx.lineTo(N/2+26,-14); dctx.lineTo(N/2,-58); dctx.closePath(); dctx.fill();\n    if(g.p!=null){ dctx.lineWidth=7/sc; dctx.strokeStyle=g.p>1?'rgba(194,31,43,.9)':'rgba(156,119,64,.95)'; dctx.beginPath(); dctx.arc(N/2,N/2,N/2+60,-Math.PI/2,-Math.PI/2+Math.PI*2*Math.min(g.p,1.35)/1.35); dctx.stroke(); }\n    dctx.restore();\n  }\n}\ndocCv.addEventListener('pointermove',e=>{ hover=cvPt(docCv,e); if(!press) drawDoc(hover); });\ndocCv.addEventListener('pointerleave',()=>{ hover=null; if(!press) drawDoc(null); });\ndocCv.addEventListener('pointerdown',e=>{ e.preventDefault(); ensureAudio(); docCv.setPointerCapture(e.pointerId); const p=cvPt(docCv,e); press={x:p.x,y:p.y,t0:performance.now(),p:0}; pressLoop(); });\nfunction pressLoop(){\n  if(!press) return;\n  press.p=Math.min(1.35,(performance.now()-press.t0)/1500);\n  if(!press.cued&&state.pressCount<3){ if(press.p>.25&&!press.c1){ press.c1=1; say('まだじゃ…',{force:true,mood:'thinking'}); } if(press.p>.62){ press.cued=1; say('今じゃ！',{force:true,mood:'surprised'}); } }\n  $('#press-fill').style.width=(press.p/1.35*100)+'%';\n  drawDoc({x:press.x,y:press.y,p:press.p}); requestAnimationFrame(pressLoop);\n}\nfunction releasePress(){\n  if(!press) return;\n  const {x,y,p}=press; press=null;\n  const imp=makeImpression(printSurface(),state.ink,p,(Math.random()*1e9)|0);\n  state.stamps.push({cv:imp.canvas,x,y,angle:state.angle,t0:performance.now()}); state.pressCount++;\n  state.last={imp,ink:state.ink,pressure:p,angle:state.angle,box:boxIndexAt(x,y)}; state.kanteiText=null; $('#btn-cert').hidden=true; $('#btn-x').hidden=true;\n  state.ink=Math.max(0,state.ink-(.2+p*.1));\n  thump(140,50,.4,.16); noise(500,.7,.08,.12,'lowpass'); updateInk(); showResult(); masterOnStamp();\n  if(!reduceMotion){ docCv.animate([{transform:'translateY(0)'},{transform:`translateY(${2+p*3}px)`},{transform:'translateY(0)'}],{duration:160,easing:'ease-out'}); popLoop(); } else drawDoc(hover);\n}\nfunction popLoop(){ drawDoc(press?{x:press.x,y:press.y,p:press.p}:hover); const s=state.stamps[state.stamps.length-1]; if(s&&performance.now()-s.t0<260) requestAnimationFrame(popLoop); }\ndocCv.addEventListener('pointerup',releasePress); docCv.addEventListener('pointercancel',releasePress);\nfunction inkLabel(v){ return v<.03?'空っぽ':v<.4?'少なめ（かすれそう）':v<=.8?'適量':'多すぎ（滲みそう）'; }\nfunction pressLabel(p){ return p<.45?'弱い':p<=1?'適正':'強すぎ'; }\nfunction updateInk(){ $('#ink-fill').style.width=(state.ink/1.2*100)+'%'; $('#ink-val').textContent=`${inkLabel(state.ink)}（${Math.round(state.ink/1.2*100)}）`; }\n$('#pad').addEventListener('click',e=>{ ensureAudio(); state.ink=Math.min(1.2,state.ink+.13+Math.random()*.04); thump(260,120,.18,.07); updateInk(); masterOnPad(); const el=e.currentTarget; el.classList.add('tap'); setTimeout(()=>el.classList.remove('tap'),90); });\nfunction fmtAngle(a){ return a<0?`上司側へ${-a}°`:a>0?`反対側へ${a}°`:'0°'; }\nfunction judgeBow(a){\n  if(a>45) return {name:'のけぞり',score:0,c:'上司に向かってふんぞり返っています。'};\n  if(a>5) return {name:'背を向ける',score:10,c:'上司と反対側に傾いています。反骨精神の表れです。'};\n  if(a>=-5) return {name:'直立不動',score:40,c:'まっすぐです。正しいはずなのに、なぜか生意気に見えるのが日本の会社です。'};\n  if(a>=-14) return {name:'会釈',score:70,c:'軽く頭を下げています。同僚向けの角度です。'};\n  if(a>=-35) return {name:'敬礼',score:100-Math.round(Math.abs(a+25)*1.5),c:'上司へ程よく頭を下げた、模範的なお辞儀ハンコです。'};\n  if(a>=-55) return {name:'最敬礼',score:78,c:'深々と頭を下げています。謝罪案件でしょうか。'};\n  if(a>=-80) return {name:'土下座',score:42,c:'もはや押印ではなく謝罪です。'};\n  return {name:'寝ている',score:5,c:'ハンコが横になって寝ています。'};\n}\n$('#angle').addEventListener('input',e=>{ state.angle=+e.target.value; $('#angle-val').textContent=fmtAngle(state.angle); $('#bow-live').textContent=judgeBow(state.angle).name; drawDoc(press?{x:press.x,y:press.y,p:press.p}:hover); });\nfunction boxLabel(k){ return k===3?'担当欄（正しい欄）':k>=0?`${LABELS[k]}欄（下剋上）`:'枠の外'; }\nfunction showResult(){\n  const L=state.last, b=judgeBow(L.angle), area=state.carvedCount/state.masks.insideCount;\n  $('#result').hidden=false;\n  $('#r-bow').textContent=`${b.name}（${fmtAngle(L.angle)}）`; $('#r-score').textContent=b.score+'点'; $('#r-bow-c').textContent=b.c;\n  let ink, c;\n  if(L.ink<.03){ ink='写っていません'; c='朱肉をつけずに押しました。朱肉をタップしてから押してください。'; }\n  else if(L.imp.coverage<.55){ ink='かすれ'; c='朱肉を足すか、もう少し長く押してください。'; }\n  else if(L.imp.blot>.35){ ink='滲み'; c='朱肉が多すぎるか、力が強すぎます。'; }\n  else { ink='くっきり'; c='きれいに押せました。'; }\n  if(L.ink>=.03&&area<.04) c+=' ほとんど彫っていないので、朱のかたまりのような印影です。';\n  if(state.pressCount>1) c+=` この書類には${state.pressCount}回押しています。`;\n  $('#r-ink').textContent=`${ink}（朱肉 ${inkLabel(L.ink)}／力 ${pressLabel(L.pressure)}）`; $('#r-ink-c').textContent=c;\n  $('#r-box').textContent=boxLabel(L.box);\n}\nfunction resetDoc(){ state.stamps=[]; state.pressCount=0; state.last=null; $('#result').hidden=true; drawDoc(null); }\n$('#btn-newdoc').addEventListener('click',resetDoc);\n\n/* ---------- 三 鑑定 ---------- */\nlet sampleNs=null, downloadsNs=null;\nfunction metrics(){\n  const M=state.masks, C=state.carved, L=state.last, b=judgeBow(L.angle);\n  let mis=0, sx=0, sy=0;\n  for(let y=0;y<N;y++) for(let x=0;x<N;x++){ const i=y*N+x; if(!M.inside[i]) continue; if(C[i]!==C[y*N+(N-1-x)]) mis++; if(C[i]){ sx+=x; sy+=y; } }\n  const cc=state.carvedCount;\n  const sym=cc?clamp(1-mis/(2*cc),0,1):0;\n  const off=cc?Math.hypot(sx/cc-N/2,sy/cc-N/2)/(N/2):0;\n  return {\n    material:STONES[state.mat].label, shape:SHAPE_LABEL[state.shape], area:cc/M.insideCount, rimFrac:state.rimCount/Math.max(1,M.ringCount),\n    sym, off, carveSec:Math.round(state.carveMs/1000), strokes:state.strokes, spinDeg:Math.round(state.spinDeg), noFlip:state.noFlip,\n    ink:L.ink, pressure:L.pressure, coverage:L.imp.coverage, blot:L.imp.blot, angle:L.angle, bowName:b.name, bowScore:b.score, pressCount:state.pressCount, box:L.box,\n    regrinds:state.regrinds, grade:state.review?state.review.grade:'未検分', inkStrokes:state.inkStrokes, style:state.style, rokuro:!!state.usedRokuro, spill:state.acc&&state.acc.spill!=null?state.acc.spill:null\n  };\n}\nfunction fortunes(M){\n  const s=v=>clamp(Math.round(v),1,5);\n  return [['金運',s(5-M.rimFrac*15-(M.area<.04?1.5:0))],['仕事運',s(M.bowScore/20+(M.box===3?0:-1.5))],['恋愛運',M.ink<.03?1:s(M.coverage<.55?2:M.blot>.35?4:M.coverage>.8?5:3)],['執着度',s(1+M.carveSec/30+M.strokes/40+M.spinDeg/720)]];\n}\nfunction titles(M){\n  const t=[], add=(n,w)=>t.push({n,w});\n  if(M.carveSec>=300) add('執念の人',`${fmtTime(M.carveSec*1000)}彫り続けた`);\n  if(M.regrinds>=3) add('七転八起',`${M.regrinds}回研ぎ直した`);\n  else if(M.regrinds>=1) add('研ぎ直しの勇気',`${M.regrinds}回研ぎ直した`);\n  if(M.rokuro||M.spinDeg>=1440) add('輪廻回転',M.rokuro?'ろくろで彫った':`石を${M.spinDeg}°回した`);\n  if(!M.inkStrokes&&M.strokes) add('下書き無用','布字なしで彫った');\n  if(M.strokes>0&&M.strokes<=6&&(M.grade==='秀'||M.grade==='優')) add('一刀入魂',`${M.strokes}刀で${M.grade}`);\n  if(M.grade==='秀') add('親方も認めた','検分で「秀」');\n  if(M.grade==='喝') add('喝の洗礼','親方に喝を入れられた');\n  if(M.spill!=null&&M.spill<.03&&M.strokes>3) add('はみ出しゼロ','墨の線から刀が出なかった');\n  if(M.rimFrac>.1) add('欠けの美学','外枠を欠いた');\n  if(M.area>.85) add('全削無我','印面をほぼ削り落とした');\n  if(M.strokes>0&&M.carveSec<20) add('早彫り','20秒以内に彫り終えた');\n  if((state.fineStrokes||0)>=20) add('極細の鬼',`極細の刀で${state.fineStrokes}刀`);\n  if(obsessionLevel(obsessionScore())>=4) add('狂気の域','執着度が振り切れた');\n  if(M.noFlip) add('初心者印','反転なしで押した');\n  if(M.box>=0&&M.box<3) add('下剋上',`${LABELS[M.box]}の欄に押した`);\n  if(M.box===3&&M.bowName==='敬礼'&&M.bowScore>=90) add('会社員の鑑',`担当欄に、上司側へ${Math.round(-M.angle)}°傾けて押した`);\n  if(M.bowName==='土下座') add('土下座職人','ハンコが土下座した');\n  if(M.angle>5) add('反骨の印','上司に背を向けて押した');\n  if(M.ink<.03) add('無色透明','朱肉なしで押した');\n  else if(M.coverage<.55) add('朱肉ケチ',`印影の${pct(1-M.coverage)}がかすれた`);\n  else if(M.blot>.35) add('朱あふれ','滲んだ印影');\n  if(M.pressCount>=3) add('押しすぎ',`同じ書類に${M.pressCount}回押した`);\n  return t;\n}\nconst TITLE_NAMES=['狂気の域','極細の鬼','執念の人','七転八起','研ぎ直しの勇気','輪廻回転','下書き無用','一刀入魂','親方も認めた','喝の洗礼','はみ出しゼロ','欠けの美学','全削無我','早彫り','初心者印','下剋上','会社員の鑑','土下座職人','反骨の印','無色透明','朱肉ケチ','朱あふれ','押しすぎ'];\nfunction collectTitles(T){\n  let got=[]; try{ got=JSON.parse(localStorage.getItem('hanko-titles')||'[]'); }catch(e){}\n  for(const t of T) if(!got.includes(t.n)) got.push(t.n);\n  try{ localStorage.setItem('hanko-titles',JSON.stringify(got)); }catch(e){}\n  return got;\n}\nfunction renderCollection(got){\n  $('#collect-sum').textContent=`集めた称号　${got.filter(n=>TITLE_NAMES.includes(n)).length} / ${TITLE_NAMES.length}`;\n  $('#collect-list').innerHTML=TITLE_NAMES.map(n=>got.includes(n)?`<li>${esc(n)}</li>`:'<li class=\"lock\">？？？</li>').join('');\n}\nfunction wrapText(x,text,maxW){ const lines=[]; let cur=''; for(const ch of [...text]){ if(ch==='\\n'){ lines.push(cur); cur=''; continue; } if(x.measureText(cur+ch).width>maxW){ lines.push(cur); cur=ch; } else cur+=ch; } if(cur) lines.push(cur); return lines; }\nasync function makeCertificate(){\n  const M=metrics(), T=titles(M), W=1080, H=1350, c=document.createElement('canvas'); c.width=W; c.height=H; const x=c.getContext('2d');\n  const txt=state.kanteiText||templateKantei(M);\n  const sec=k=>{ const m=txt.match(new RegExp('【'+k+'】([^【]*)')); return m?m[1].trim():''; };\n  const sou=sec('印相')||pickSou(M), soukyo=sec('総評'), mitate=sec('見立て');\n  const MIN='\"Shippori Mincho B1\",\"Hiragino Mincho ProN\",\"Yu Mincho\",serif', GO='\"Shippori Mincho B1\",\"Hiragino Mincho ProN\",\"Yu Mincho\",serif', FU='\"Yuji Syuku\",serif';\n  try{ await Promise.all([document.fonts.load('800 60px \"Shippori Mincho B1\"','印相鑑定書'+sou+M.grade+T.map(t=>t.n).join('')+'秀優良可喝未検分'),document.fonts.load('400 30px \"Shippori Mincho B1\"',txt+T.map(t=>t.w).join('')+'青田石寿山石巴林石丸角小判執着時間刀数研ぎ直し回親方評価金運仕事運恋愛運度指導鑑定朱雀院印斎源じいハンコ工房年月日0123456789：・／'),document.fonts.load('400 40px \"Yuji Syuku\"','ハンコ工房称号')]); }catch(e){}\n  x.fillStyle='#f4eee1'; x.fillRect(0,0,W,H);\n  const r=mulberry32(11); for(let k=0;k<1400;k++){ x.strokeStyle=`rgba(120,100,70,${.03+r()*.05})`; x.lineWidth=.6+r()*1.2; x.beginPath(); const sx=r()*W, sy=r()*H; x.moveTo(sx,sy); x.quadraticCurveTo(sx+(r()-.5)*30,sy+(r()-.5)*30,sx+(r()-.5)*60,sy+(r()-.5)*60); x.stroke(); }\n  x.strokeStyle='#b81f2a'; x.lineWidth=6; x.strokeRect(36,36,W-72,H-72); x.lineWidth=2; x.strokeRect(50,50,W-100,H-100);\n  x.textAlign='center'; x.fillStyle='#2a2320'; x.font=`800 76px ${MIN}`; x.fillText('印 相 鑑 定 書',W/2,160);\n  x.font=`500 21px ${GO}`; x.fillStyle='#6f6458'; x.fillText(`${M.material}・${M.shape}　／　執着時間 ${fmtTime(M.carveSec*1000)}　／　${M.strokes}刀　／　研ぎ直し ${M.regrinds}回　／　執着度「${OBS[obsessionLevel(obsessionScore())][1]}」`,W/2,212);\n  // 印影\n  x.save(); x.translate(W/2,520); x.rotate(-.04); x.globalCompositeOperation='multiply'; x.drawImage(state.last.imp.canvas,-250,-250,500,500); x.restore();\n  // 親方の判\n  x.save(); x.translate(W-190,700); x.rotate(-.12); x.strokeStyle='#c21f2b'; x.lineWidth=7; x.strokeRect(-62,-62,124,124); x.fillStyle='#c21f2b'; x.font=`800 84px ${MIN}`; x.textBaseline='middle'; x.fillText(M.grade==='未検分'?'未':M.grade,0,6); x.font=`700 20px ${GO}`; x.fillText('親方の評価',0,92); if(state.selfGrade){ x.fillStyle='#5a3a24'; x.fillText('自己評価 '+state.selfGrade,0,118); } x.restore();\n  x.textBaseline='alphabetic';\n  x.fillStyle='#8c1520'; x.font=`800 64px ${MIN}`; x.fillText(sou,W/2,860);\n  if(mitate){ x.fillStyle='#4a3f38'; x.font=`400 28px ${GO}`; x.fillText(wrapText(x,'見立て：'+mitate,W-220)[0],W/2,906); }\n  // 称号\n  x.font=`400 34px ${FU}`; x.textAlign='left';\n  let tx=110, ty=972; const tags=T.slice(0,6);\n  for(const tg of tags){ const w=x.measureText(tg.n).width+40; if(tx+w>W-110) break; x.fillStyle='#5a3a24'; x.beginPath(); x.roundRect?x.roundRect(tx,ty-38,w,52,6):x.rect(tx,ty-38,w,52); x.fill(); x.fillStyle='#f6e6c8'; x.fillText(tg.n,tx+20,ty); tx+=w+14; }\n  if(!tags.length){ x.fillStyle='#75685d'; x.font=`400 26px ${GO}`; x.fillText('称号なし（次はもっと執着してみよう）',110,ty); }\n  // 運勢\n  const F=fortunes(M); x.font=`700 28px ${GO}`; let fy=ty+80;\n  F.forEach(([k,n],i)=>{ const fx=110+(i%2)*440, yy=fy+Math.floor(i/2)*46; x.fillStyle='#4a3f38'; x.fillText(k,fx,yy); x.fillStyle='#c21f2b'; x.fillText('★'.repeat(n),fx+120,yy); x.fillStyle='#b9a98f'; x.fillText('☆'.repeat(5-n),fx+120+x.measureText('★'.repeat(n)).width,yy); });\n  // 総評\n  x.font=`400 27px ${GO}`; x.fillStyle='#2a2320'; let sy2=fy+112;\n  { const maxL=Math.max(1,Math.min(3,Math.floor((H-136-sy2)/40)+1)); const L=wrapText(x,soukyo||'',W-220); const out=L.slice(0,maxL);\n    if(L.length>maxL){ let t=out[maxL-1]; while(t.length&&x.measureText(t+'…').width>W-220) t=t.slice(0,-1); out[maxL-1]=t.replace(/[、。]$/,'')+'…'; }\n    out.forEach((ln,i)=>x.fillText(ln,110,sy2+i*40)); }\n  x.textAlign='right'; x.font=`400 22px ${GO}`; x.fillStyle='#75685d'; const d=new Date();\n  x.fillText(`${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日　鑑定：朱雀院 印斎　指導：源じい`,W-90,H-82);\n  x.textAlign='left'; x.font=`400 34px ${FU}`; x.fillStyle='#8c1520'; x.fillText('ハンコ工房',90,H-80);\n  // 親方の顔と一言\n  try{\n    const portrait=await masterPortrait({秀:'laugh',優:'proud',良:'happy',可:'worried',喝:'angry'}[M.grade]||'thinking');\n    const fx=90, fy=280, fs=170;\n    x.drawImage(portrait,fx-6,fy-6,fs+12,fs+12);\n    const galQ=Math.random()<.2; const quip=(galQ?{秀:'神すぎて泣いた',優:'エモい出来じゃん',良:'アリよりのアリ',可:'もうちょいガンバ♪',喝:'ぴえん超えてぱおん'}:{秀:'うちで働かんか。',優:'よか出来じゃ。',良:'まあまあじゃ。',可:'精進せい。',喝:'喝！'})[M.grade]||(galQ?'見せてくれなかったじゃん':'わしに見せんかったな。');\n    x.fillStyle='#F4EFE6'; x.fillRect(fx-14,fy+fs+16,fs+28,64); x.strokeStyle='rgba(28,28,28,.7)'; x.lineWidth=1.5; x.strokeRect(fx-14,fy+fs+16,fs+28,64); x.strokeRect(fx-10,fy+fs+20,fs+20,56);\n    x.fillStyle='#2a2320'; x.textAlign='center'; x.font=`400 ${quip.length>9?17:quip.length>6?22:28}px ${FU}`; x.fillText(quip,fx+fs/2,fy+fs+58);\n    x.font=`700 18px ${GO}`; x.fillStyle='#75685d'; x.fillText('源じい（親方）',fx+fs/2,fy-12);\n  }catch(e){}\n  return c;\n}\nfunction esc(s){ return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c])); }\nfunction fmtK(t){ return esc(t).replace(/【([^】]+)】/g,'<span class=\"kh\">【$1】</span>'); }\nfunction renderStep3(){\n  const has=!!state.last;\n  $('#k-empty').hidden=has; $('#k-left').hidden=!has; $('#k-body').hidden=!has; $('#k-body-empty').hidden=has;\n  if(!has) return;\n  const M=metrics();\n  $('#imp-img').src=state.last.imp.canvas.toDataURL('image/png');\n  const chips=[\n    ['印材',`${M.material}・${M.shape}`,false],['彫った面積',pct(M.area),M.area<.04],['外周の欠け',(M.rimFrac*100).toFixed(1)+'%',M.rimFrac>.1],\n    ['左右対称',pct(M.sym),false],['執着時間',fmtTime(M.carveSec*1000),false],['刀数',M.strokes+'刀',false],['回した角度',M.spinDeg+'°',false],\n    ['かすれ',M.ink<.03?'全部':pct(1-M.coverage),M.coverage<.55],['親方の評価',M.grade,M.grade==='喝'||M.grade==='未検分'],['研ぎ直し',M.regrinds+'回',false],\n    ['お辞儀',`${M.bowName}（${M.bowScore}点）`,M.bowScore<50],['押した欄',boxLabel(M.box),M.box!==3]\n  ];\n  // 大事な4つだけ大きく見せ、残りはたたむ\n  const KEY=['親方の評価','お辞儀','執着時間','印材'], li=([k,v,bad])=>`<li class=\"${bad?'bad':''}\">${k} <b>${esc(v)}</b></li>`;\n  $('#k-chips').innerHTML=KEY.map(k=>chips.find(c=>c[0]===k)).filter(Boolean).map(li).join('');\n  $('#k-chips-more').innerHTML=chips.filter(c=>!KEY.includes(c[0])).map(li).join('');\n  const T=titles(M); const col=collectTitles(T); renderCollection(col);\n  $('#k-titles').innerHTML=T.length?T.map(t=>`<li title=\"${esc(t.w)}\">${esc(t.n)}<small>${esc(t.w)}</small></li>`).join(''):'<li class=\"none\">称号なし</li>';\n  $('#k-stars').innerHTML=fortunes(M).map(([k,n])=>`<div>${k}</div><div class=\"st\" aria-label=\"${k} 5段階中${n}\">${'★'.repeat(n)}<span>${'☆'.repeat(5-n)}</span></div>`).join('');\n}\nconst ITEMS=['芋けんぴ','黒水牛の印鑑ケース','桜島大根','白熊（かき氷）','かるかん','黒豚まん','左に傾いた定規','朱肉のフタ','和紙のしおり','青いボールペン','黄色い付箋','観葉植物','白いスニーカー','温かいほうじ茶','電卓','腕時計','マグカップ','折りたたみ傘','ゼムクリップ','ハンカチ','角の丸い消しゴム','ワイヤレスイヤホン','カレーパン','目覚まし時計','手帳','ハンドクリーム','スマホのリング','ポストイット','缶コーヒー','のど飴'];\nfunction pickSou(M){\n  if(M.ink<.03) return '無色透明相';\n  if(M.area<.04) return '白紙無垢相';\n  if(M.regrinds>=3) return '七転八起相';\n  if(M.grade==='秀') return '名工開眼相';\n  if(!M.inkStrokes) return '無計画奔放相';\n  if(M.area>.85) return '全削無我相';\n  if(M.rimFrac>.15) return '欠損流転相';\n  if(M.box>=0&&M.box<3) return '下剋上相';\n  if(M.angle>5) return '叛骨独立相';\n  if(M.spinDeg>1440) return '輪廻回転相';\n  if(M.carveSec>120) return '執念彫琢相';\n  if(M.sym>.8) return '左右均整相';\n  if(M.coverage<.55) return '朧月夜相';\n  if(M.blot>.35) return '朱溢満願相';\n  if(M.bowScore>=85) return '恭順昇進相';\n  return '八方円満相';\n}\nfunction templateKantei(M){\n  const r=mulberry32(hash(''+M.angle+M.strokes+M.carveSec+M.spinDeg+M.material+M.shape));\n  const rp=a=>a[Math.floor(r()*a.length)];\n  const out=[`【印相】${pickSou(M)}`];\n  let s='';\n  // 事実（計測した数字）→ ひとことの見立て、の順。データにない性格の断定や大げさな言葉は使わない\n  const per=M.strokes?Math.round(M.carveSec/M.strokes):0, T=fmtTime(M.carveSec*1000);\n  if(M.carveSec>120) s+=rp([`彫り時間${T}、刀数${M.strokes}。一刀に平均${per}秒かけた計算です。急がない人の印です。`,`${T}かけて${M.strokes}刀。一刀ずつ確かめながら彫った手数です。`]);\n  else if(M.carveSec<20) s+=rp([`彫り時間は${M.carveSec}秒。決めるのが早い相。見直しは後回しにしがちです。`,`${M.carveSec}秒で${M.strokes}刀。カップ麺ができる前に印ができました。`]);\n  else s+=rp([`${M.strokes}刀を${T}で。手数と時間のつり合いが取れた彫りです。`,`彫り時間${T}、刀数${M.strokes}。迷いすぎず、急ぎすぎずの配分です。`]);\n  if(M.spinDeg>720) s+=rp([`彫りながら印材を${M.spinDeg}°回しています。いろんな向きから確かめる人です。`,`回した角度は${M.spinDeg}°。見る向きを変えて考える人です。`]);\n  if(M.area<.04) s+=rp([`彫ったのは印面の${pct(M.area)}だけ。押すとほぼ朱一色になります。`,`印面の${pct(M.area)}しか彫っていません。まだ何を彫るか決めていない相です。`]);\n  else if(M.area>.85) s+=rp([`印面の${pct(M.area)}を削りました。残った線が少ないぶん、一本一本が目立ちます。`,`${pct(M.area)}を削り落とした印面。手放すのが上手な人です。`]);\n  else if(M.sym>.8) s+=rp([`左右対称度は${pct(M.sym)}。左右の釣り合いをそろえたがる人です。`,`左右対称度${pct(M.sym)}。机の上も揃っていそうです。`]);\n  else if(M.off>.25) s+=rp([`彫りが片側に寄っています（中心からのずれ${pct(M.off)}）。好きなものに一直線な時期です。`,`重心が片側に寄った印面（ずれ${pct(M.off)}）。気になることが一つある時期です。`]);\n  if(M.regrinds) s+=rp([`砥石で${M.regrinds}回研ぎ直しています。やり直しを嫌がらない人です。`,`研ぎ直し${M.regrinds}回。一度で決めず、納得するまでやる相です。`]);\n  s+={round:rp(['丸印は角のない形。人付き合いで角を立てない相です。','丸い印は、話の輪に入りやすい相です。']),square:rp(['角印は四隅で締まる形。筋を通す相です。','角の立った印。言うべきことを言える人です。']),oval:rp(['小判形は縦に長い形。名前の通り、お金の話に縁がある相です。','小判の印。財布の中身を数える回数が多い相です。'])}[state.shape]||'';\n  if(M.grade&&M.grade!=='未検分') s+=rp([`親方の評価は「${M.grade}」。`,`親方の見立ては「${M.grade}」。あの頑固者の採点です。`]);\n  if(M.noFlip) s+='反転なしで押したので、印影は書いた向きのまま出ています。';\n  if(M.pressCount>1) s+=rp([`同じ稟議書に${M.pressCount}回押しています。上司は回数を数えています。`,`${M.pressCount}回押し直した稟議書。迷った跡が紙に残っています。`]);\n  out.push('【総評】'+s);\n  out.push('【金運】'+(M.rimFrac>.1?rp([`外周が${pct(M.rimFrac)}欠けています。財布の口が開いたままの相。今月の芋けんぴ代に注意。`,`外枠の欠け${pct(M.rimFrac)}。お金が隙間から出ていく相。小銭入れの穴を確認しましょう。`]):M.rimFrac>.02?rp(['外周に小さな欠け。少しずつ出ていく相なので、サブスクを見直すと吉。','わずかな欠けあり。コンビニの「ついで買い」に気をつけて。']):rp(['外周がしっかり閉じた、お金が逃げにくい堅実な相です。','枠が締まった印面。貯金箱の才能があります。','欠けのない外枠。宝くじより定期預金が吉。'])));\n  let w=`お辞儀角度は${fmtAngle(M.angle)}で「${M.bowName}」。`;\n  if(M.box>=0&&M.box<3) w+=rp([`しかも${LABELS[M.box]}の欄に押しています。出世は早いが敵も多い。`,`${LABELS[M.box]}の欄に押す下剋上の相。来週の会議は荒れます。`]);\n  else if(M.box<0) w+=rp(['枠からはみ出す自由人。組織より独立向きです。','欄の外に押す型破りな相。副業運があります。']);\n  else if(M.bowScore>=85) w+=rp(['上司の懐に入るのが上手い。来期の評価は期待できます。','模範的なお辞儀。稟議は一発で通るでしょう。','角度が完璧。上司のハンコも思わず頭を下げ返す相です。']);\n  else if(M.angle>5) w+=rp(['上司に背を向ける気概あり。転職サイトの通知が増える時期です。','上司と反対へ傾いた反骨の相。ただし決裁は下りません。']);\n  else if(M.angle<-55) w+=rp(['謝り慣れている相。謝る前に確認する癖をつけると運気が上向きます。','頭を下げすぎて床が見えている相。何をやらかしたかは聞きません。']);\n  else w+=rp(['もう少し上司側へ傾けると、稟議の通りが良くなるでしょう。','直立に近いお辞儀。誠実ですが、根回しは苦手かも。']);\n  out.push('【仕事運】'+w);\n  out.push('【恋愛運】'+(M.ink<.03?rp(['朱肉をつけずに押しました。想いを伝える前に、まず準備から。','空押しの相。気持ちは見えないと伝わりません。']):M.coverage<.55?rp([`印影のかすれが${pct(1-M.coverage)}。想いが半分しか伝わっていません。朱肉を足すように、言葉を足しましょう。`,`かすれ${pct(1-M.coverage)}。照れ隠しが過ぎる相です。`]):M.blot>.35?rp(['朱が滲み出るほど情が深い相。重いと言われる前に一呼吸を。','滲むほどの朱。愛情表現は小出しが吉。']):rp(['かすれも滲みも少ない、まっすぐ伝わる相。素直さが吉。','くっきりした印影。言葉より行動で伝わる人です。','ムラのない印影。安定した関係を築ける相です。'])));\n  out.push('【ラッキーアイテム】'+ITEMS[Math.floor(r()*ITEMS.length)]);\n  return out.join('\\n');\n}\nfunction buildPrompt(M){\n  const data={印材:M.material,形:M.shape,彫った面積:pct(M.area),外周の欠け:pct(M.rimFrac),左右対称度:pct(M.sym),彫りに費やした時間:fmtTime(M.carveSec*1000),刀数:M.strokes,彫りながら回した角度:M.spinDeg+'°',\n    押すときの反転:M.noFlip?'反転なし（初心者向け設定）':'本物どおり左右反転',朱肉の量:inkLabel(M.ink),押す強さ:pressLabel(M.pressure),印影のかすれ:M.ink<.03?'朱肉なしで何も写っていない':pct(1-M.coverage),滲み:M.blot>.35?'あり':'なし',\n    お辞儀角度:fmtAngle(M.angle),お辞儀判定:M.bowName,押した欄:boxLabel(M.box),同じ書類に押した回数:M.pressCount,研ぎ直した回数:M.regrinds,親方の評価:M.grade,布字の筆数:M.inkStrokes};\n  return `あなたは鹿児島に住む、胡散臭いが妙に説得力のある印相鑑定士「朱雀院 印斎（すざくいん いんさい）」です。\nユーザーが印房の親方に教わりながら、石の印材に筆で布字を書いて自由に彫り、稟議書に押した印鑑を鑑定してください。名前とは限らず、絵や模様や鏡文字かもしれません。画像がある場合はそれが実際の印影（朱の部分が紙に写った部分）です。\nまず印影に何が彫られているように見えるかを一言で見立て、それと計測データの数字に具体的に触れながら、大げさにもっともらしく鑑定してください。\n「お辞儀ハンコ」は上司の印に向けて傾けて押す日本の会社の謎マナーで、上司側へ傾くほど頭を下げています。\nエンタメとして楽しく。不安を煽る表現や断定的な不幸の予言は避ける。\n書き方の決まり：前置きなしで本題から書く。計測データの数字を2つ以上そのまま引用する。データと画像にないこと（性格の断定、過去の出来事、実績の数字）は作らない。「素晴らしい」「圧倒的」「魂」「宿る」のような大げさな言葉や抽象語は使わず、何がどうなっているかを書く。同じ内容の言い換えや、最後のまとめ・呼びかけは書かない。\n出力は次の見出しだけを使ったプレーンテキスト。全体で380字前後。Markdown記法は使わない。\n【見立て】\n【印相】漢字4〜5字の造語＋「相」\n【総評】\n【金運】\n【仕事運】（お辞儀角度と押した欄に触れる）\n【恋愛運】\n【ラッキーアイテム】（身近な日用品や食べ物。たまに鹿児島ネタでもよい）\n\n計測データ：${JSON.stringify(data)}`;\n}\nfunction updateEngine(){ $('#engine').textContent=sampleNs?'鑑定：朱雀院 印斎（印影の写真を見て書いています）':'鑑定：朱雀院 印斎'; }\nconst sleep=ms=>new Promise(r=>setTimeout(r,ms));\nasync function typewrite(el,text){\n  el.innerHTML='<span class=\"thinking\">鑑定士が印影を覗き込んでいます…</span>';\n  if(reduceMotion){ el.innerHTML=fmtK(text); return; }\n  await sleep(1100);\n  const chars=[...text], step=Math.max(1,Math.ceil(chars.length/90));\n  for(let i=0;i<=chars.length;i+=step){ el.innerHTML=fmtK(chars.slice(0,i).join('')); await sleep(24); }\n  el.innerHTML=fmtK(text);\n}\nconst toBlob=cv=>new Promise(r=>cv.toBlob(r,'image/png'));\nlet kanteiBusy=false;\n$('#btn-kantei').addEventListener('click',async e=>{\n  if(kanteiBusy||!state.last) return;\n  kanteiBusy=true; const btn=e.currentTarget; btn.disabled=true; syncDock();\n  const M=metrics(), out=$('#k-text'); let done=false;\n  if(sampleNs){\n    out.innerHTML='<span class=\"thinking\">鑑定士が印影を覗き込んでいます…</span>';\n    try{\n      const opts={modelTier:'default',onText:({text})=>{ out.innerHTML=fmtK(text); }};\n      try{ const lim=await sampleNs.limits(); if(lim&&lim.images){ const w=document.createElement('canvas'); w.width=w.height=N; const x=w.getContext('2d'); x.fillStyle='#fbf7ee'; x.fillRect(0,0,N,N); x.drawImage(state.last.imp.canvas,0,0); opts.images=[await toBlob(w)]; } }catch(_){}\n      const res=await sampleNs(buildPrompt(M),opts);\n      if(res&&res.text){ out.innerHTML=fmtK(res.text); done=true; }\n    }catch(err){\n      if(err&&(err.code==='not_granted'||err.code==='unavailable')){ sampleNs=null; updateEngine(); }\n      if(err&&err.code==='rate_limited') toast('鑑定士が混み合っています。オフライン版で鑑定します。');\n    }\n  }\n  if(!done){ const t=templateKantei(M); await typewrite(out,t); state.kanteiText=t; } else state.kanteiText=out.textContent;\n  btn.disabled=false; btn.textContent='もう一度鑑定してもらう'; kanteiBusy=false; $('#btn-cert').hidden=false; $('#btn-x').hidden=false;\n  if(state.counted!==state.last){ state.counted=state.last; lsSet('hanko.count',String(+(lsGet('hanko.count')||0)+1)); }\n  const nGot=(()=>{ try{ return JSON.parse(localStorage.getItem('hanko-titles')||'[]').filter(n=>TITLE_NAMES.includes(n)).length; }catch(e){ return 0; } })();\n  const certLine=!master.said.has('cert')?'鑑定書は画像にして持って帰れるぞ。友達に見せてみい。'\n    :nGot>=TITLE_NAMES.length?'称号を全部集めたんか…。わしでも持っとらんぞ。':nGot>=12?`称号は${nGot}個か。半分は越えたな。`:pick(['また一本、増えたな。','鑑定書、持って帰るか？','…悪くない一本じゃ。']);\n  master.said.add('cert');\n  say(certLine+'　保存は下の帯からじゃ。',{force:true,mood:'happy'}); syncDock();\n});\nlet toastT=0;\nfunction toast(msg){ const t=$('#toast'); t.textContent=msg; t.classList.add('show'); clearTimeout(toastT); toastT=setTimeout(()=>t.classList.remove('show'),3200); }\nasync function saveBlob(blob,filename){\n  if(!blob){ toast('画像を作れませんでした。'); return; }\n  if(downloadsNs){\n    try{ await downloadsNs.save({filename,data:blob}); toast('保存しました'); return; }\n    catch(err){ if(err&&err.code==='declined'){ toast('保存をやめました'); return; } if(err&&err.code==='rate_limited'){ toast('少し待ってから、もう一度押してください'); return; } }\n  }\n  const url=URL.createObjectURL(blob), a=document.createElement('a'); a.href=url; a.download=filename; document.body.appendChild(a); a.click(); a.remove();\n  setTimeout(()=>URL.revokeObjectURL(url),5000);\n  toast('保存されない場合は、印影の画像を長押し（右クリック）して保存してください');\n}\n$('#ex-straight').addEventListener('click',async()=>{ if(state.last) saveBlob(await toBlob(state.last.imp.canvas),'hanko.png'); });\n$('#ex-bow').addEventListener('click',async()=>{\n  if(!state.last) return;\n  const s=Math.ceil(N*1.42), c=document.createElement('canvas'); c.width=c.height=s; const x=c.getContext('2d');\n  x.translate(s/2,s/2); x.rotate(state.last.angle*Math.PI/180); x.drawImage(state.last.imp.canvas,-N/2,-N/2);\n  saveBlob(await toBlob(c),'hanko_ojigi.png');\n});\n$('#ex-doc').addEventListener('click',async()=>{ drawDoc(null); saveBlob(await toBlob(docCv),'hanko_ringi.png'); drawDoc(hover); });\n$('#btn-again').addEventListener('click',()=>restartAll());\nfunction shareURL(){ try{ const h=location.host; if(/^https?:$/.test(location.protocol)&&h&&!/claude|anthropic|localhost|127\\.0\\.0\\.1/.test(h)) return location.origin+'/'; }catch(e){} return ''; }\nasync function shareX(){\n  if(!state.last) return;\n  const M=metrics(), T=titles(M), t=T[0]&&T[0].n;\n  try{ const c=await makeCertificate(); saveBlob(await toBlob(c),'hanko_kanteisho.png'); }catch(e){}\n  const text=`源じいに教わって、石のハンコを彫った。\\n${M.material}・${M.shape}／親方の評価「${M.grade}」${t?`／称号「${t}」`:''}\\n#ハンコ工房`;\n  const u=shareURL(), href='https://x.com/intent/post?text='+encodeURIComponent(text)+(u?'&url='+encodeURIComponent(u):'');\n  const a=document.createElement('a'); a.href=href; a.target='_blank'; a.rel='noopener'; document.body.appendChild(a); a.click(); a.remove();\n  say('画像は保存しといた。投稿に貼っとけ。…わしの顔も写っとるじゃろ。',{force:true,mood:'proud'});\n}\n$('#btn-x').addEventListener('click',shareX);\n$('#btn-cert').addEventListener('click',async()=>{ if(!state.last) return; const c=await makeCertificate(); saveBlob(await toBlob(c),'hanko_kanteisho.png'); });\n$('#btn-check').addEventListener('click',e=>{ const on=$('#imp-box').classList.toggle('check-bg'); e.currentTarget.textContent=on?'和紙の上に表示':'背景を透過表示'; });\n\n\n\n/* ---------- 3Dで押す（稟議書が横から出てくる） ---------- */\nconst PAPER={x:0,z:11,w:21.6,h:13.5,y:.03};            // 1単位≒1cm、稟議書960×600pxを21.6×13.5に\nconst docTex=new THREE.CanvasTexture(docCv); docTex.colorSpace=THREE.SRGBColorSpace; docTex.anisotropy=8;\nconst paper=new THREE.Mesh(new THREE.PlaneGeometry(PAPER.w,PAPER.h).rotateX(-Math.PI/2),new THREE.MeshStandardMaterial({map:docTex,roughness:.92}));\npaper.position.set(40,PAPER.y,PAPER.z); paper.receiveShadow=true; paper.visible=false; scene.add(paper);\n// 押印用の朱肉\nconst pressPot=new THREE.Group(); pressPot.position.set(13.1,0,6.4); pressPot.visible=false; scene.add(pressPot);\n{ const pm=new THREE.MeshPhysicalMaterial({color:0xf3efe6,roughness:.25,clearcoat:.6});\n  const pt=new THREE.Mesh(new THREE.CylinderGeometry(2.1,2.25,1.1,48),pm); pt.position.y=.55; pt.castShadow=pt.receiveShadow=true; pressPot.add(pt);\n  const sh=new THREE.Mesh(new THREE.CircleGeometry(1.8,48).rotateX(-Math.PI/2),new THREE.MeshStandardMaterial({color:0xc83228,roughness:.95,emissive:0x3a0806})); sh.position.y=1.11; pressPot.add(sh);\n  const pk=new THREE.Mesh(new THREE.BoxGeometry(4.6,2.4,4.6),new THREE.MeshBasicMaterial({visible:false})); pk.position.y=1; pk.userData.tool='pad'; pressPot.add(pk); rackPick.push(pk); }\n// 手に持った印鑑（印面を下に）\nconst handSeal=new THREE.Group(), handInner=new THREE.Group(); handInner.rotation.z=Math.PI; handSeal.add(handInner); handSeal.visible=false; scene.add(handSeal);\nconst pressRing=new THREE.Mesh(new THREE.RingGeometry(.9,1,64).rotateX(-Math.PI/2),new THREE.MeshBasicMaterial({color:0xb08a4e,transparent:true,opacity:.0,depthWrite:false}));\npressRing.position.y=PAPER.y+.01; scene.add(pressRing);\nconst P={active:false,slide:0,cur:null,dip:null,hold:null,auto:null,lastY:1.6};\nfunction buildHandSeal(){\n  handInner.clear();\n  handInner.add(new THREE.Mesh(faceGeo,faceMat));\n  if(bodyGroup) bodyGroup.children.forEach(c=>{ const m=new THREE.Mesh(c.geometry,c.material); m.position.copy(c.position); m.rotation.copy(c.rotation); m.scale.copy(c.scale); m.castShadow=true; handInner.add(m); });\n}\nfunction paperHit(cx,cy){\n  const r=glCv.getBoundingClientRect(), ray=new THREE.Raycaster(); ray.setFromCamera(new THREE.Vector2((cx-r.left)/r.width*2-1,-(cy-r.top)/r.height*2+1),camera);\n  const o=ray.ray.origin, d=ray.ray.direction; if(Math.abs(d.y)<1e-6) return null; const t=(PAPER.y-o.y)/d.y; if(t<0) return null;\n  const wx=o.x+d.x*t, wz=o.z+d.z*t, dx=(wx-(PAPER.x-PAPER.w/2))/PAPER.w*DW, dy=(wz-(PAPER.z-PAPER.h/2))/PAPER.h*DH;\n  return {wx,wz,dx,dy,on:dx>=0&&dx<=DW&&dy>=0&&dy<=DH};\n}\nconst docToWorld=(dx,dy)=>({wx:PAPER.x-PAPER.w/2+dx/DW*PAPER.w, wz:PAPER.z-PAPER.h/2+dy/DH*PAPER.h});\n// 押印の画角。縦長の画面では担当欄と朱肉に寄せる（押印中に画面の向きが変わった時もやり直す）\nfunction framePress(){\n  // 横は「担当欄〜朱肉の右端」まで必ず入る距離まで引く（正方形に近い画面でも朱肉が外に出ない）\n  const tanH=Math.tan(17*Math.PI/180)*camera.aspect, needR=pressPot.position.x+2.2-3.5;\n  view.tgtT.set(3.5,0,PAPER.z-1.5); view.tElev=1.12; view.tDist=Math.max(26,needR/(tanH*.92)); view.tAz=.12; lamp.target.position.set(6,0,8.6);\n  if(camera.aspect<1){ view.tgtT.set(9.4,0,4.4); view.tDist=Math.max(26,6.4/(Math.tan(17*Math.PI/180)*camera.aspect)); view.tAz=0; view.tElev=1.2; lamp.target.position.set(10,0,7.5); }\n}\nfunction startPress(){\n  if(state.step!==1){ goStep(1); }\n  if(carving) endPointer();\n  updateStats(); buildHandSeal();\n  setPhase('press');\n  P.active=true; P.slide=0; P.hold=null; P.dip=null; P.auto=null; P.cur=docToWorld(boxCenter(3).x,boxCenter(3).y+140);\n  seal.visible=false; handSeal.visible=true; paper.visible=true; pressPot.visible=true; fude.visible=knife.visible=brushRing.visible=false; if(viseGroup) viseGroup.visible=false; chipMesh.visible=false; deskClutter.forEach(o=>o.visible=false);\n  $$('nav.steps button').forEach(b=>{ if(+b.dataset.go===2) b.setAttribute('aria-current','step'); else b.removeAttribute('aria-current'); });\n  drawDoc(null); docTex.needsUpdate=true;\n  framePress();\n  noise(900,.6,.08,.5,'lowpass');\n  P.inkOk=0; say('押してみい。朱肉は右。トン、トンと軽うにな。…担当の欄に、上司のほうへ少し頭を下げて押すのが作法じゃ。傾きはホイールか、下の ◁▷ じゃ。',{force:true,mood:'happy',choices:[{label:'自分で押す',primary:true,fn:()=>say('うむ。担当欄の上で長押しじゃ。離した瞬間に押される。',{force:true})},{label:'親方に押してもらう',fn:()=>masterPress()}]});\n}\nfunction endPress(){\n  if(P.active) setChoices(null);\n  $$('nav.steps button').forEach(b=>{ if(+b.dataset.go===1) b.setAttribute('aria-current','step'); else b.removeAttribute('aria-current'); });\n  P.active=false; handSeal.visible=false; paper.visible=false; pressPot.visible=false; pressRing.material.opacity=0; seal.visible=true; if(viseGroup) viseGroup.visible=true; chipMesh.visible=true; deskClutter.forEach(o=>o.visible=true);\n  view.tgtT.set(0,FACE_Y-.2,0); view.tElev=.74; view.tDist=10.5; view.tAz=Math.round(view.tAz/(Math.PI*2))*Math.PI*2; lamp.target.position.set(0,FACE_Y,0);\n}\nfunction newPaper(){ resetDoc(); P.slide=0; drawDoc(null); docTex.needsUpdate=true; noise(900,.6,.08,.5,'lowpass'); }\nfunction dip(){\n  if(P.dip||P.hold) return; P.lift=null;\n  P.dip={t0:performance.now(),from:{x:handSeal.position.x,z:handSeal.position.z}};\n}\nfunction masterPress(){\n  P.auto={t0:performance.now(),stage:0};\n  say('見とれ。わしが押せばこうじゃ。',{force:true,mood:'proud'});\n}\nfunction inkLabelShort(v){ return v<.03?'空':v<.4?'少なめ':v<=.8?'適量':'多すぎ'; }\nfunction updatePressHud(p){\n  const sub=$('#hud-submit'), show=!!state.last&&!P.hold&&!P.auto; if(sub.hidden===show) sub.hidden=!show;\n  $('#hud-tool').innerHTML=`朱肉：<b>${inkLabelShort(state.ink)}</b>`;\n  const b=judgeBow(state.angle);\n  // 押している間は「力」だけ。普段は次にやることを一つだけ示す\n  const t=p!=null?`力 ${'■'.repeat(Math.round(p/1.35*10))}${'□'.repeat(10-Math.round(p/1.35*10))} ${p>1?'強すぎ':p<.45?'弱い':'ちょうどええ'}`:'';\n  const tip=$('#hud-tip'); if(tip.textContent!==t) tip.textContent=t; tip.hidden=!t;\n  updateBigHint();\n}\nfunction doStamp(dx,dy,p,byMaster=false){\n  const imp=makeImpression(printSurface(),state.ink,p,(Math.random()*1e9)|0);\n  state.stamps.push({cv:imp.canvas,x:dx,y:dy,angle:state.angle,t0:performance.now()}); state.pressCount++;\n  state.last={imp,ink:state.ink,pressure:p,angle:state.angle,box:boxIndexAt(dx,dy),x:dx,y:dy}; state.kanteiText=null; $('#btn-cert').hidden=true; $('#btn-x').hidden=true;\n  state.ink=Math.max(0,state.ink-(.2+p*.1));\n  thump(140,50,.42,.16); noise(500,.7,.08,.12,'lowpass'); shake=.6;\n  P.lift={cx:lastClient?lastClient.x:-1,cy:lastClient?lastClient.y:-1,wx:P.cur?P.cur.wx:0,wz:P.cur?P.cur.wz:PAPER.z};\n  drawDoc(null); docTex.needsUpdate=true; showResult();\n  const s=pressScore(state.last); state.last.score=s;\n  setTimeout(()=>masterScore(s,byMaster),350);\n}\nfunction pressScore(L){\n  const b=judgeBow(L.angle);\n  let ink=L.ink<.03?0:clamp((L.imp.coverage-.3)/.6,0,1)*100-L.imp.blot*60; ink=clamp(Math.round(ink),0,100);\n  let pos; if(L.box===3){ const c=boxCenter(3); pos=clamp(Math.round(100-Math.hypot(L.x-c.x,L.y-c.y)*1.6),40,100); } else pos=L.box>=0?15:0;\n  return {total:Math.round(b.score*.4+ink*.3+pos*.3),bow:b.score,ink,pos,b};\n}\nfunction masterScore(s,byMaster){\n  const L=state.last; let t;\n  if(byMaster) t=pick(['…ほれ、これが手本じゃ。角度、朱の量、場所、全部見とけ。','こうじゃ。力はいらん、重さを預けるだけじゃ。','ほれ。…四十年押しとると、目をつぶっても押せる。']);\n  else if(L.ink<.03) t=pick(['朱肉をつけずに押してどうする。','…空押しか。気持ちだけは届いたかもしれん。']);\n  else if(L.box>=0&&L.box<3) t=pick([`そこは${LABELS[L.box]}の欄じゃ！下剋上か。`,`${LABELS[L.box]}の欄に押すとは…明日から席がないぞ。`,`おいおい、${LABELS[L.box]}の判を勝手に押したことになるぞ。`]);\n  else if(L.box<0) t=pick(['枠からはみ出しとるぞ。','どこに押しとる。欄の中じゃ。','…書類の余白に押すのは、落書きと言うんじゃ。']);\n  else t={敬礼:'よか角度じゃ。会社員の鑑じゃな。',直立不動:'まっすぐか。わしの頃は上司に頭を下げて押したもんじゃが…まあ時代か。',会釈:'軽い会釈か。もうちょい下げてもええぞ。',最敬礼:'深々と下げたな。何かやらかしたんか。',土下座:'やりすぎじゃ。ハンコが土下座しとる。',寝ている:'ハンコを寝かせてどうする。'}[s.b.name]||'上司に背を向けて押すとは、ええ度胸じゃ。';\n  if(!byMaster&&L.ink>=.03){ if(L.imp.coverage<.55) t+='それに朱が足らんで、かすれとる。'; else if(L.imp.blot>.35) t+='朱が滲んどる。つけすぎじゃ。'; }\n  try{ state.titlesShown=state.titlesShown||new Set(); const nt=titles(metrics()).find(x=>!state.titlesShown.has(x.n)); if(nt&&!byMaster){ state.titlesShown.add(nt.n); t+=`…称号「${nt.n}」を授ける。`; } }catch(e){}\n  const head=`<span class=\"grade\">${s.total}点</span><span class=\"score-break\">お辞儀 ${s.bow}・朱 ${s.ink}・場所 ${s.pos}</span><br>`;\n  typeHTML(head,t,s.total>=80?'laugh':s.total>=60?'happy':s.total>=35?'worried':'angry',[\n    {label:'鑑定士に見せる',primary:true,fn:()=>submitKantei()},\n    {label:'新しい紙で押し直す',fn:()=>{ newPaper(); say('新しい稟議書じゃ。今度はうまく押せよ。',{force:true}); }},\n    {label:byMaster?'自分でも押してみる':'親方に押してもらう',fn:()=>byMaster?say('よし、今度はお主の番じゃ。',{force:true}):masterPress()},\n    {label:'彫りに戻る',fn:()=>{ endPress(); setPhase('carve'); }}]);\n}\nasync function typeHTML(head,text,mood,choices){\n  if(Math.random()<GAL_RATE) text=galify(text);\n  setChoices(null); setMood(mood,6000); talking=true;\n  const ch=[...text];\n  sayHTML(head+esc(text),false); freshen(); speakFor(ch.length); gesture('nod');\n  setChoices(choices);\n}\nfunction pressDown(e){\n  const h=paperHit(e.clientX,e.clientY); if(!h||!h.on||P.dip||P.auto) return false;\n  P.lift=null; P.hold={t0:performance.now(),dx:h.dx,dy:h.dy,p:0}; P.cur={wx:h.wx,wz:h.wz}; return true;\n}\nfunction pressUp(){ if(!P.hold) return; const {dx,dy,p}=P.hold; P.hold=null; doStamp(dx,dy,p); }\nfunction updatePress(dt,now){\n  if(!P.active) return;\n  P.slide=Math.min(1,P.slide+dt*1.6); const e=1-Math.pow(1-P.slide,3);\n  paper.position.x=PAPER.x+(1-e)*34; paper.rotation.y=(1-e)*.25;\n  let tx=P.cur?P.cur.wx:0, tz=P.cur?P.cur.wz:PAPER.z, ty=1.6, p=null;\n  if(lastClient&&!P.hold&&!P.dip&&!P.auto){ const h=paperHit(lastClient.x,lastClient.y); if(h){ P.cur={wx:h.wx,wz:h.wz}; tx=h.wx; tz=h.wz; } }\n  // 押した後は印影が見えるよう、印を持ち上げて脇へ退ける（ポインタを動かすまで）\n  if(P.lift&&!P.hold&&!P.dip&&!P.auto){\n    if(lastClient&&P.lift.cx>=0&&Math.hypot(lastClient.x-P.lift.cx,lastClient.y-P.lift.cy)>28) P.lift=null;\n    else { tx=P.lift.wx+(pressPot.position.x-P.lift.wx)*.45; tz=P.lift.wz+2.2; ty=3.6; }\n  }\n  // 親方が押す\n  if(P.auto){\n    const t=(now-P.auto.t0)/1000, potC={x:pressPot.position.x,z:pressPot.position.z}, tgt=docToWorld(boxCenter(3).x-2,boxCenter(3).y+1);\n    state.angle=-24; $('#angle').value=-24; syncBowPill();\n    if(t<.6){ tx=potC.x; tz=potC.z; ty=1.6; }\n    else if(t<1.6){ tx=potC.x; tz=potC.z; const k=(t-.6)%.5/.5; ty=1.15+Math.abs(Math.sin(k*Math.PI))*.9; const n=Math.floor((t-.6)/.5); if(!P.auto['d'+n]){ P.auto['d'+n]=1; thump(200,90,.2,.08); state.ink=Math.min(.66,state.ink+.33); } }\n    else if(t<2.4){ tx=tgt.wx; tz=tgt.wz; ty=1.6; }\n    else if(t<3.3){ tx=tgt.wx; tz=tgt.wz; ty=PAPER.y; p=.78; }\n    else { P.auto=null; state.ink=Math.max(state.ink,.62); doStamp(boxCenter(3).x-2,boxCenter(3).y+1,.78,true); }\n    P.cur={wx:tx,wz:tz};\n  }\n  if(P.dip){\n    const t=(now-P.dip.t0)/1000;\n    if(t<.25){ tx=pressPot.position.x; tz=pressPot.position.z; ty=1.9; }\n    else if(t<.42||!P.dip.hit){ tx=pressPot.position.x; tz=pressPot.position.z; ty=1.15; if(!P.dip.hit){ P.dip.hit=1; state.ink=Math.min(1.2,state.ink+.13+Math.random()*.04); thump(260,120,.2,.07); if(state.ink>.95) say('つけすぎじゃ！それじゃ滲むぞ。',{key:'padmuch',gap:15000,force:true,mood:'angry'}); else if(state.ink>=.4&&state.ink<=.8&&!P.inkOk){ P.inkOk=1; say('…よし。そのくらいでええ。',{force:true,mood:'proud'}); } else talk('dip',{gap:6000}); } }\n    else if(t<.6){ tx=pressPot.position.x; tz=pressPot.position.z; ty=1.9; }\n    else { P.dip=null; }\n  }\n  if(P.hold){ P.hold.p=Math.min(1.35,(now-P.hold.t0)/1500); p=P.hold.p; ty=PAPER.y; tx=P.cur.wx; tz=P.cur.wz;\n    if(!P.hold.cued&&state.pressCount<3){ if(p>.25&&!P.hold.c1){ P.hold.c1=1; say('まだじゃ…',{force:true,mood:'thinking'}); } if(p>.62){ P.hold.cued=1; say('今じゃ！',{force:true,mood:'surprised'}); } } }\n  const k=Math.min(1,dt*(P.hold?30:14));\n  handSeal.position.x+=(tx-handSeal.position.x)*k; handSeal.position.z+=(tz-handSeal.position.z)*k; P.lastY+=(ty-P.lastY)*Math.min(1,dt*(P.hold?24:10)); handSeal.position.y=P.lastY;\n  handSeal.rotation.y=-state.angle*Math.PI/180;\n  pressRing.position.x=handSeal.position.x; pressRing.position.z=handSeal.position.z;\n  const rs=(state.shape==='oval'?R*.9:R*1.15)*(1+.15*(p||0)); pressRing.scale.set(rs,1,rs);\n  pressRing.material.opacity=p!=null?.85:.35; pressRing.material.color.setHex(p!=null&&p>1?0xc21f2b:0xb08a4e);\n  const last=state.stamps[state.stamps.length-1]; if(last&&now-last.t0<300){ drawDoc(null); docTex.needsUpdate=true; }\n  updatePressHud(p);\n  glCv.style.cursor=rackHover?'pointer':'none';\n}\n\n/* ---------- 工程の切り替え ---------- */\nfunction goStep(n){\n  if(n===2){ if(!state.started){ state.started=true; document.body.classList.remove('pre'); $('#intro').hidden=true; } if(state.phase==='paint') finishPaint(); n=1; state.step!==1&&goStep(1); startPress(); $$('nav.steps button').forEach(b=>{ if(+b.dataset.go===2) b.setAttribute('aria-current','step'); else b.removeAttribute('aria-current'); }); return; }\n  if(n===1&&state.phase==='press'){ endPress(); setPhase('carve'); }\n  if(n===3&&P.active) endPress();\n  if(!state.started){ state.started=true; document.body.classList.remove('pre'); $('#intro').hidden=true; }\n  if(shelfMode&&n!==1){ shelfMode=false; $('#intro').hidden=true; }\n  if(state.step===1&&n!==1){ if(carving) endPointer(); updateStats(); if(state.phase==='paint'){ finishPaint(); } }\n  state.step=n;\n  $$('.step').forEach(s=>s.hidden=+s.dataset.step!==n);\n  $$('nav.steps button').forEach(b=>{ if(+b.dataset.go===n) b.setAttribute('aria-current','step'); else b.removeAttribute('aria-current'); });\n  setChoices(null);\n  if(n===1){ stageEl.appendChild(masterEl); masterEl.className='master in-stage'; resize(); }\n  else if(n===3){ $('#m-slot3').appendChild(masterEl); masterEl.className='master inline'; }\n  else { document.body.appendChild(masterEl); masterEl.className='master floating'; }\n  if(n===2){ drawDoc(null); if(!state.review&&state.strokes>0) say('なんじゃ、わしに見せんで押しに行くんか。まあええ。',{key:'skipreview',once:true,force:true}); else say('朱肉はトントンと軽くつけるんじゃ。ベタッとつけたら滲むぞ。',{key:'pad0',once:true,force:true}); }\n  if(n===3){ rebuildShow(); renderStep3(); say('鑑定士の朱雀院か…あいつの言うことは話半分で聞いとけ。',{key:'kantei',once:true,force:true,mood:'worried'}); if(state.last&&state.kanteiFor!==state.last){ state.kanteiFor=state.last; setTimeout(()=>$('#btn-kantei').click(),700); } }\n  window.scrollTo({top:0,behavior:reduceMotion?'auto':'smooth'});\n}\ndocument.addEventListener('click',e=>{ const b=e.target.closest('[data-go]'); if(b) goStep(+b.dataset.go); });\nfunction masterOnPad(){ if(state.ink>.95) say('つけすぎじゃ！それじゃ滲むぞ。',{key:'padmuch',gap:15000,force:true}); }\nfunction masterOnStamp(){\n  const L=state.last, b=judgeBow(L.angle);\n  let t;\n  if(L.ink<.03) t='朱肉をつけずに押してどうする。';\n  else if(L.box>=0&&L.box<3) t=`そこは${LABELS[L.box]}の欄じゃ！下剋上か。`;\n  else if(L.box<0) t='枠からはみ出しとるぞ。';\n  else if(b.name==='敬礼') t='よか角度じゃ。会社員の鑑じゃな。';\n  else if(b.name==='直立不動') t='まっすぐか。わしの頃は上司に頭を下げて押したもんじゃが…まあ時代か。';\n  else if(b.name==='会釈') t='軽い会釈か。もうちょい下げてもええぞ。';\n  else if(b.name==='最敬礼') t='深々と下げたな。何かやらかしたんか。';\n  else if(b.name==='土下座') t='やりすぎじゃ。ハンコが土下座しとる。';\n  else if(b.name==='寝ている') t='ハンコを寝かせてどうする。';\n  else t='上司に背を向けて押すとは、ええ度胸じゃ。';\n  if(L.ink>=.03&&L.imp.coverage<.55) t+='それに朱が足らんで、かすれとる。';\n  else if(L.imp.blot>.35) t+='朱が滲んどる。つけすぎじゃ。';\n  const good=L.ink>=.03&&L.box===3&&b.score>=70&&L.imp.coverage>=.55&&L.imp.blot<=.35;\n  try{ state.titlesShown=state.titlesShown||new Set(); const nt=titles(metrics()).find(t=>!state.titlesShown.has(t.n)); if(nt){ state.titlesShown.add(nt.n); t+=`…称号「${nt.n}」を授ける。`; } }catch(e){}\n  say(t,{force:true,mood:good?'happy':null,choices:[{label:'鑑定士に見せる',primary:true,fn:()=>goStep(3)},{label:'押し直す',fn:()=>{ resetDoc(); say('新しい稟議書じゃ。今度はうまく押せよ。',{force:true}); }},{label:'彫りに戻る',fn:()=>goStep(1)}]});\n}\n\n/* ---------- 入門 ---------- */\nlet shelfMode=false;\nfunction restartAll(){\n  if(P.active) endPress();\n  seal.visible=true; handSeal.visible=false;\n  state.step=1; $$('.step').forEach(s=>s.hidden=+s.dataset.step!==1);\n  $$('nav.steps button').forEach(b=>{ if(+b.dataset.go===1) b.setAttribute('aria-current','step'); else b.removeAttribute('aria-current'); });\n  stageEl.appendChild(masterEl); masterEl.className='master in-stage'; resize(); setChoices(null);\n  state.started=false; shelfMode=false; state.selfGrade=null; state.kanteiText=null; state.spinTalk=0;\n  const [s,m]=pickedStock(); newStock(s,m);\n  $('#intro-title').textContent='もう一本、彫るか'; $('#intro-lead').textContent='石と形を選び直せる。'; $('#intro-go').textContent='この石を据える'; $('#intro-cancel').hidden=true; $('#intro-note').hidden=false;\n  setShowcase(true); syncIntroStone();\n  const it=$('#intro'); it.hidden=false; requestAnimationFrame(()=>it.classList.remove('out')); document.body.classList.add('pre');\n  window.scrollTo({top:0});\n}\nconst pickedStock=()=>[document.querySelector('input[name=shape]:checked').value,document.querySelector('input[name=mat]:checked').value];\nfunction closeIntro(){ const it=$('#intro'); it.classList.add('out'); setTimeout(()=>{ it.hidden=true; },500); }\nlet howtoOpen=false, howtoCb=null;\nfunction showHowto(cb){\n  $('#howto-ops').innerHTML=COARSE?'指1本：書く・彫る　／　指2本：見回す・寄る　／　下の札でも寄る・道具替えができます':'左ドラッグ：書く・彫る　／　右ドラッグ：見回す　／　ホイール：寄る　／　Space：かすを吹く';\n  $('#howto-close').textContent=cb?'朱を塗って始める':'閉じる';\n  howtoOpen=true; howtoCb=cb||null; $('#howto').hidden=false; setTimeout(()=>$('#howto-close').focus(),50);\n}\nfunction closeHowto(){ if(!howtoOpen) return; howtoOpen=false; $('#howto').hidden=true; lsSet('hanko.howto','1'); const cb=howtoCb; howtoCb=null; if(cb) cb(); }\n$('#howto-close').addEventListener('click',closeHowto);\n$('#howto').addEventListener('click',e=>{ if(e.target.id==='howto') closeHowto(); });\n$('#howto-open').addEventListener('click',()=>showHowto());\nfunction enterShop(){\n  if(state.started) return; state.started=true; ensureAudio();\n  closeIntro(); document.body.classList.remove('pre'); document.body.classList.add('seating');\n  seatStone(()=>{ document.body.classList.remove('seating'); const go=()=>{ state.startT=performance.now(); startPaint(); }; if(lsGet('hanko.howto')) go(); else showHowto(go); });\n}\nfunction openShelf(){\n  if(state.step!==1) goStep(1);\n  shelfMode=true; const it=$('#intro');\n  document.querySelector(`input[name=shape][value=\"${state.shape}\"]`).checked=true;\n  document.querySelector(`input[name=mat][value=\"${state.mat}\"]`).checked=true;\n  $('#intro-title').textContent='印材棚'; $('#intro-lead').textContent='石と形を選び直す。いまの印面と押した稟議書はリセットされる。';\n  $('#intro-go').textContent='この石に替える'; $('#intro-cancel').hidden=false; $('#intro-note').hidden=true;\n  it.hidden=false; requestAnimationFrame(()=>it.classList.remove('out'));\n  setShowcase(true); syncIntroStone();\n  say('どの石にする？巴林石は硬いぞ。',{force:true,mood:'thinking'});\n}\nfunction syncIntroStone(){ const sh=document.querySelector('input[name=shape]:checked'), mt=document.querySelector('input[name=mat]:checked'); const L=el=>el.nextElementSibling; $('#intro-stone').textContent=`${L(mt).querySelector('span').firstChild.textContent}・${L(sh).textContent.trim()}　―　${L(mt).querySelector('small').textContent}`; }\n$$('input[name=shape],input[name=mat]').forEach(el=>el.addEventListener('change',()=>{ syncIntroStone(); if(!state.started){ const [s,m]=pickedStock(); newStock(s,m); SHOW.lift=Math.max(SHOW.lift,2.0); } ensureAudio(); thump(240,120,.12,.06); }));\n$('#intro-go').addEventListener('click',()=>{\n  if(!shelfMode){ enterShop(); return; }\n  shelfMode=false; const [s,m]=pickedStock(); closeIntro(); newStock(s,m); seatStone(()=>toast('新しい石を印床に据えました'));\n});\n$('#intro-cancel').addEventListener('click',()=>{ shelfMode=false; closeIntro(); seatStone(()=>say('そうか。続けろ。',{force:true})); });\nif(COARSE){ $('#intro-note').textContent='音が出ます。指でなぞって書く・彫る／2本指で見回す・寄る／道具は画面下の札で替える'; }\ndocument.addEventListener('keydown',e=>{ if(!state.started&&state.step===1&&e.key==='Enter'){ e.preventDefault(); enterShop(); } },true);\n\n/* ---------- 起動 ---------- */\nstageEl.appendChild(masterEl);\nupdateInk();\nbuildProps();\nbuildRack(); updateRack();\nnewStock('round','seiden');\nsetShowcase(true); view.az=view.tAz; view.elev=view.tElev; view.dist=view.tDist; TGT.copy(view.tgtT); syncIntroStone();\n$('#intro-go').disabled=false; $('#intro-go').textContent='この石を据える';\nresize();\nrequestAnimationFrame(loop);\n(async()=>{\n  const G='\"Zen Kaku Gothic New\"';\n  await Promise.all([\n    document.fonts.load('800 100px \"Shippori Mincho B1\"','鈴木高橋伊藤稟議書').catch(()=>{}),\n    document.fonts.load(`400 17px ${G}`,'起案日者標記の件について下記とおり稟議いたします件名金額目的備考おやつ芋けんぴ購入円税込午後集中力維持ためご承認ください至急時間以上年月担当あなた0123456789（）：。、').catch(()=>{}),\n    document.fonts.load(`700 16px ${G}`,'件名金額目的備考社長部長課長担当　').catch(()=>{})\n  ]);\n  bossImps=['鈴木','高橋','伊藤'].map((nm,k)=>makeImpression(bossSurface(nm),.6,.72+k*.05,1000+k).canvas);\n  buildDocBase(); drawDoc(null);\n  try{\n    if(window.claude&&typeof window.claude.use==='function'){\n      const [s,d]=await Promise.all([window.claude.use('sample').catch(()=>null),window.claude.use('downloads').catch(()=>null)]);\n      sampleNs=s; downloadsNs=d; updateEngine();\n    }\n  }catch(e){}\n  // デプロイナウ等で /api/ai（サーバー側でAIを呼ぶ口）があれば、それを使う\n  if(!sampleNs&&location.protocol.startsWith('http')){\n    try{ const r=await fetch('/api/ai',{method:'GET',cache:'no-store'}); if(r.ok){ const j=await r.json(); if(j&&j.ok){ sampleNs=makeEndpointAI(); updateEngine(); } } }catch(e){}\n  }\n})();\nfunction blobToDataURL(b){ return new Promise((res,rej)=>{ const fr=new FileReader(); fr.onload=()=>res(fr.result); fr.onerror=rej; fr.readAsDataURL(b); }); }\nfunction makeEndpointAI(){\n  const f=async(prompt,opts={})=>{\n    const imgs=[]; for(const b of (opts.images||[])) imgs.push(await blobToDataURL(b));\n    const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt,images:imgs,tier:opts.modelTier||'quick'})});\n    if(!r.ok) throw {code:r.status===429?'rate_limited':'unavailable'};\n    const j=await r.json(); if(!j||!j.text) throw {code:'unavailable'};\n    if(opts.onText) opts.onText({text:j.text});\n    return {text:j.text};\n  };\n  f.limits=async()=>({images:true});\n  return f;\n}\n</script>\n</body>\n</html>\n";
